    ["01-2"] = {name="Durotar", nameA="Durotar: {a:367} & {a:362}", shortA="Durotar: {a:367} +", tips={{k="取捨", text="Faites Assumer ses responsabilités. Récupérez Morceaux de canevas aux côtés des autres objectifs Donjon de Tiragarde."}, {k="取捨", text="Remettez Vaincre les traîtres pour déverrouiller Des épaves. Faites-le aux côtés de Un esprit parfaitement éduqué."}, {k="取捨", text="Enregistrez la chaîne de donjon La Faille de l'Ombre. Si vous envisagez d'exécuter Gouffre de Ragefeu, prenez Ennemis cachés ( → →) à partir de Thrall. Obtenez le badge pour auprès du camp Lame ardente au nord."}, {k="提醒", text="En dessous du niveau 12? Faites Des lignes sécurisées, Rocher du crâne ou les premières quêtes Une menace venue d'en bas.", s={{"En dessous du niveau 12?"}, {"Faites Des lignes sécurisées, Rocher du crâne ou les premières quêtes Une menace venue d'en bas"}}}}, danger={[1]="Les escaliers et les portes du Donjon de Tiragarde peuvent attirer les marins de l'étage. Dégagez d'abord le mur extérieur et l'entrée.", [2]="Les géants des mers parcourent la région des Nagas sur la côte nord. Éliminez les monstres à proximité avant d'en tirer un. Retirez-vous le long du rivage si vous avez des ennuis."}, grind={[1]={mob="Soldat de marine de Kul Tiras", note="Des foules normales denses à Donjon de Tiragarde. Tirez dehors pour éviter les ajouts dans les couloirs. Récupérez Morceaux de canevas pour le nouveau sac."}, [2]={mob="Garde de guerre Tranchecrin", note="Les foules normales se regroupent à l'ouest de Tranchecolline. Longez le bord du camp et surveillez les patrouilles. Associez-le au Empiètement."}, [3]={mob="Sorcière des tempêtes Terrevent", note="Les foules normales se regroupent dans le nord de Durotar. Utilisez le couvercle pour fermer les roulettes. Faites Des lignes sécurisées ou broyez à 12 avant Orgrimmar."}}, supply={[1]={npc="Trayexir"}, [2]={npc="Grosk l'aubergiste"}, [3]={npc="Wuark"}, [4]={npc="Grosk l'aubergiste"}, [5]={npc="Ghrawt"}, [6]={npc="Doras"}}, steps={[1]={npc="Ukor", tgt="Ukor", desc="Recherchez Ukor sur la route allant du Vallée des épreuves au Village de Sen'jin."}, [2]={hint="Parler à Maître Gadrin au village de Sen'jin."}, [3]={npc="Maître Gadrin", tgt="Maître Gadrin"}, [4]={npc="Lar Prowltusk", tgt="Lar Prowltusk"}, [5]={npc="Vel'rin Fang", tgt="Vel'rin Fang"}, [6]={npc="Maître Vornal", tgt="Maître Vornal"}, [7]={npc="Maître Gadrin", tgt="Maître Gadrin"}, [8]={npc="Maître Gadrin", tgt="Maître Gadrin"}, [9]={npc="Maître Gadrin", tgt="Maître Gadrin"}, [10]={npc="Vel'rin Fang", tgt="Vel'rin Fang"}, [11]={npc="Xar'Ti", tgt="Xar'Ti"}, [12]={npc="Maître Vornal", tgt="Maître Vornal"}, [13]={npc="Pa'zula", tgt="Pa'zula", tag="Facultatif", desc="Ne faites cela que si vous pouvez obtenir les matériaux désenchanteurs."}, [14]={text="Enregistrez-vous d'abord au Tranchecolline."}, [15]={hint="Tuez 6 rampantes noirecrêtes et 6 rôdeuses noirecrêtes dans le sud de Durotar, puis informez-en Gar'thok à Tranchecolline."}, [16]={hint="Apportez le journal à Brakk près de Tranchecolline.", tag="Facultatif"}, [17]={npc="Brakk", tgt="Brakk", tag="Facultatif"}, [18]={npc="Brakk", tgt="Brakk", tag="Facultatif"}, [19]={hint="Asseyez-vous près du feu de camp basique de Brakk et attendez de recevoir l'amélioration Repos amplifié.", tag="Facultatif"}, [20]={npc="Brakk", tgt="Brakk", tag="Facultatif"}, [21]={npc="Brakk", tgt="Brakk", tag="Facultatif"}, [22]={npc="Brakk", tgt="Brakk", tag="Facultatif", desc="Apprenez d'abord Dépeçage. Rendez-vous à Orgrimmar."}, [23]={hint="Parler à Orgnil Soulscar à Tranchecolline."}, [24]={hint="Apporter le Fardeau d'Ukor à l'aubergiste Grosk à Tranchecolline."}, [25]={npc="Orgnil Soulscar", tgt="Orgnil Soulscar"}, [26]={npc="Gar'Thok", tgt="Gar'Thok"}, [27]={npc="Grosk l'aubergiste", tgt="Grosk l'aubergiste"}, [28]={text="À Tranchecolline, liez votre pierre de foyer avec Grosk l'aubergiste (51.51, 41.64)."}, [29]={npc="Gar'Thok", tgt="Gar'Thok"}, [30]={npc="Orgnil Soulscar", tgt="Orgnil Soulscar"}, [31]={npc="Cuisinier Torka", tgt="Cuisinier Torka"}, [32]={npc="Gar'Thok", tgt="Gar'Thok"}, [33]={npc="Furl Scornbrow", tgt="Furl Scornbrow", star={"Sac en cuir fait main"}}, [34]={npc="Turroc", tgt="Turroc"}, [35]={npc="Cuisinier Torka", tgt="Cuisinier Torka"}, [36]={hint="Parlez au cuisinier Torka, à Tranchecolline, pour apprendre à cuisiner.", tag="Facultatif"}, [37]={npc="Cuisinier Torka", tgt="Cuisinier Torka", tag="Facultatif"}, [38]={text="Donjon de Tiragarde → les épaves → Combe des Kolkar et Îles de l'Écho"}, [39]={hint="Tuer 10 Marins de Kul Tiras, 8 Soldats de marine de Kul Tiras et le Lieutenant Benedict, puis retourner voir Gar'Thok à Tranchecolline."}, [40]={hint="Apporter 8 Morceaux de canevas à Furl Scornbrow, dans la la tour de guet de Tranchecolline."}, [41]={hint="Récupérez la hache d'armes d'écumeur, l'arc d'écumeur et le bouclier d'écumeur aux alentours du donjon de Tiragarde, puis rapportez-les à Turroc à Tranchecolline."}, [42]={npc="Vieille enveloppe", npcObj=true, desc="Récupérez la clé de Lieutenant Benedict. Ouvrez le coffre à l'étage pour le Vieille enveloppe."}, [43]={npc="Sac perdu d'Ukor", npcObj=true, tag="Facultatif", desc="Si vous pillez le pack en chemin, démarrez la quête et dirigez-vous vers le sud jusqu'à Ukor."}, [44]={text="Revenir à Tranchecolline à partir de Donjon de Tiragarde. Foyer si prêt."}, [45]={hint="Apporter les Ordres de l'amiral Proudmoore à Gar'Thok de Tranchecolline."}, [46]={npc="Gar'Thok", tgt="Gar'Thok"}, [47]={npc="Gar'Thok", tgt="Gar'Thok"}, [48]={npc="Turroc", tgt="Turroc", desc="Un Grunt de Tranchecolline propose également cette quête (53.06, 42.48)."}, [49]={npc="Furl Scornbrow", tgt="Furl Scornbrow", star={"Sac en cuir fait main"}}, [50]={npc="Gar'Thok", tgt="Gar'Thok"}, [51]={npc="Gar'Thok", tgt="Gar'Thok", tag="Facultatif"}, [52]={hint="Apporter 4 Yeux de makrura intacts et 8 Fioles de mucus de clampant à maître Vornal, au village de Sen'jin."}, [53]={hint="Gar'Thok de Tranchecolline veut que vous retrouviez 3 Outils gnomes parmi les épaves près de la côte."}, [54]={hint="Rapportez son sac à Ukor dans le sud de Durotar.", tag="Facultatif"}, [55]={npc="Ukor", tgt="Ukor", tag="Facultatif"}, [56]={npc="Maître Vornal", tgt="Maître Vornal"}, [57]={hint="Détruire 3 Jeux de Plans d'attaque dans la combe des Kolkar, pour Lar Prowltusk à l'extérieur du village de Sen'jin."}, [58]={npc="Pal'juh", tgt="Pal'juh", tag="Facultatif", desc="Recherchez Pal'juh sur Combe des Kolkar. Dégagez la route avant de démarrer l'escorte."}, [59]={hint="Aidez Pal'juh à sortir de la combe des Kolkar, puis informez-en maître Vornal, au village de Sen'jin.", tag="Facultatif", desc="Recherchez Pal'juh sur Combe des Kolkar. Dégagez la route avant de démarrer l'escorte."}, [60]={npc="Maître Vornal", tgt="Maître Vornal", tag="Facultatif", desc="Recherchez Pal'juh sur Combe des Kolkar. Dégagez la route avant de démarrer l'escorte."}, [61]={npc="Lar Prowltusk", tgt="Lar Prowltusk"}, [62]={hint="Rapporter 3 Oeufs de fouette-queue au cuisinier Torka, à Tranchecolline."}, [63]={hint="Apporter 4 Peaux de tigres de Durotar à Vel'rin Fang, au village de Sen'jin."}, [64]={hint="Récupérer le Crâne de Minshina dans le Cercle de puissance, sur les îles de l'Écho."}, [65]={hint="Battre Zalazane."}, [66]={hint="Récupérez 8 idoles de Loas oubliées sur les îles de l'Écho. Apportez-les au maître Gadrin, au village de Sen'jin."}, [67]={hint="Apportez les œufs de la matriarche griffesang à Xar'Ti, au village de Sen'jin."}, [68]={hint="Pa'zula du village de Sen'jin vous demande de récupérer 3 résidus lumineux. Vous pourrez obtenir des résidus lumineux en désenchantant les pendentifs maléficiés obtenus sur les Trolls des îles de l'Écho.", tag="Facultatif", desc="Le pendentif Maléfice tombe ici. Obtenez Résidu lumineux en désenchantant."}, [69]={npc="Vel'rin Fang", tgt="Vel'rin Fang"}, [70]={npc="Maître Gadrin", tgt="Maître Gadrin"}, [71]={npc="Maître Gadrin", tgt="Maître Gadrin"}, [72]={npc="Maître Gadrin", tgt="Maître Gadrin"}, [73]={npc="Xar'Ti", tgt="Xar'Ti"}, [74]={npc="Pa'zula", tgt="Pa'zula", tag="Facultatif"}, [75]={text="Utilisez votre pierre de foyer pour revenir à Tranchecolline ou prenez la route du nord."}, [76]={npc="Cuisinier Torka", tgt="Cuisinier Torka"}, [77]={npc="Gar'Thok", tgt="Gar'Thok"}, [78]={text="À l'ouest de Tranchecolline et au nord de Durotar"}, [79]={hint="Tuer 4 hurans Tranchecrin, 4 Eclaireurs Tranchecrin, 4 Lève-poussière Tranchecrin et 4 Gardes de guerre Tranchecrin pour Gar'Thok de Tranchecolline."}, [80]={hint="Le cuisinier Torka de Tranchecolline souhaite que vous ramassiez 8 figues de Barbarie dans les terres des Tranchecrins à l'ouest de la ville."}, [81]={npc="Gar'Thok", tgt="Gar'Thok"}, [82]={npc="Cuisinier Torka", tgt="Cuisinier Torka"}, [83]={npc="Orgnil Soulscar", tgt="Orgnil Soulscar", desc="Min. Niveau 9."}, [84]={hint="Trouvez Heglan Ombredœil au nord du donjon de Tiragarde.", desc="Min. Niveau 9."}, [85]={npc="Heglan Ombredoeil", tgt="Heglan Ombredoeil", desc="Min. Niveau 9."}, [86]={npc="Heglan Ombredoeil", tgt="Heglan Ombredoeil"}, [87]={hint="Trouvez des traces de ce qui a attaqué Heglan Ombredœil."}, [88]={npc="Orgnil Soulscar", tgt="Orgnil Soulscar"}, [89]={npc="Orgnil Soulscar", tgt="Orgnil Soulscar"}, [90]={hint="Apporter la Griffe de Fizzle à Orgnil Soulscar à Tranchecolline."}, [91]={hint="Récupérez 9 ailerons épineux de Nagas."}, [92]={npc="Orgnil Soulscar", tgt="Orgnil Soulscar"}, [93]={npc="Orgnil Soulscar", tgt="Orgnil Soulscar"}, [94]={npc="Orgnil Soulscar", tgt="Orgnil Soulscar", tag="Facultatif", desc="Géant des mers d'élite sur la côte nord. Regroupez-vous ou sautez si nécessaire."}, [95]={hint="Tuez le Géant des mers au large de la côte nord de Durotar, puis rapportez une preuve de votre victoire.", tag="Facultatif", desc="Géant des mers d'élite sur la côte nord. Regroupez-vous ou sautez si nécessaire."}, [96]={npc="Orgnil Soulscar", tgt="Orgnil Soulscar", tag="Facultatif", desc="Géant des mers d'élite sur la côte nord. Regroupez-vous ou sautez si nécessaire."}, [97]={npc="Orgnil Soulscar", tgt="Orgnil Soulscar"}, [98]={hint="Parler à Margoz."}, [99]={npc="Margoz", tgt="Margoz"}, [100]={npc="Margoz", tgt="Margoz"}, [101]={hint="Prendre les Colliers brûlants des sectateurs au Rocher du crâne."}, [102]={npc="Margoz", tgt="Margoz"}, [103]={npc="Margoz", tgt="Margoz", tag="Facultatif"}, [104]={text="XP en option avant le niveau 12"}, [105]={npc="Rezlak", tgt="Rezlak", tag="Facultatif"}, [106]={hint="Retrouver 5 Sacs de marchandises et les rendre à Rezlak près d'Orgrimmar.", tag="Facultatif"}, [107]={npc="Rezlak", tgt="Rezlak", tag="Facultatif"}, [108]={npc="Rezlak", tgt="Rezlak", tag="Facultatif"}, [109]={hint="Tuer 12 Terrevent farouches et 8 Sorcières des tempêtes Terrevent pour Rezlak près du Ravin asséché.", tag="Facultatif"}, [110]={npc="Rezlak", tgt="Rezlak", tag="Facultatif"}, [111]={npc="Misha Tor'kren", tgt="Misha Tor'kren", tag="Facultatif"}, [112]={hint="Trouver un indice du sort de Kron et en informer Misha Tor'kren, à la ferme, au nord-ouest de Tranchecolline.", tag="Facultatif"}, [113]={npc="Misha Tor'kren", tgt="Misha Tor'kren", tag="Facultatif"}, [114]={npc="Orbe de tempête émoussé", npcObj=true, tag="Facultatif", desc="Acceptez uniquement si vous récupérez le Orbe de tempête émoussé."}, [115]={hint="Apportez l'orbe de tempête émoussé à Rezlak, près du ravin Asséché.", tag="Facultatif", desc="Acceptez uniquement si vous récupérez le Orbe de tempête émoussé."}, [116]={npc="Rezlak", tgt="Rezlak", tag="Facultatif", desc="Acceptez uniquement si vous récupérez le Orbe de tempête émoussé."}, [117]={npc="Rezlak", tgt="Rezlak", tag="Facultatif"}, [118]={hint="Apportez 5 organes de lézard-tonnerre chargés à Rezlak, près du ravin Asséché.", tag="Facultatif"}, [119]={npc="Rezlak", tgt="Rezlak", tag="Facultatif"}, [120]={npc="Sabot d'Halikor", npcObj=true, tag="Facultatif", desc="Si vous trouvez Halikor et parvenez à le battre, récupérez son sabot."}, [121]={text="Micros Orgrimmar et transfert La Croisée"}, [122]={text="Pour les quêtes ou l'entraînement Orgrimmar, suivez la route principale vers le nord en passant par la porte sud. Apprenez le point de vol de Doras (45.12, 63.89) et validez les quêtes à proximité."}, [123]={hint="Porter les Ordres de l'amiral Proudmoore à Nazgrel, dans les appartements de Thrall à Orgrimmar.", tag="Facultatif"}, [124]={npc="Nazgrel", tgt="Nazgrel", tag="Facultatif"}, [125]={hint="Apporter un Spécimen de collier à Neeru Fireblade à Orgrimmar.", tag="Facultatif"}, [126]={npc="Neeru Fireblade", tgt="Neeru Fireblade", tag="Facultatif"}, [127]={hint="Parlez à Thuwd, à Orgrimmar, pour apprendre à fabriquer un objet de camping propre à votre métier une fois que vous vous serez fait la main.", tag="Facultatif"}, [128]={npc="Thuwd", tgt="Thuwd", tag="Facultatif"}, [129]={hint="Rapportez le sabot d'Halikor à Orgrimmar.", tag="Facultatif"}, [130]={npc="Kamari", tgt="Kamari", tag="Facultatif"}, [131]={text="Après la remise des quêtes de la ville, dirigez-vous vers Tranchecolline ou courez vers le sud le long de la route principale. Évitez ce voyage si vous êtes resté en dehors de la ville."}, [132]={npc="Pisteur Takrin", tgt="Pisteur Takrin", desc="Nécessite le niveau 10. Attendez environ 12 heures pour vous diriger vers le La Croisée."}, [133]={hint="Suivre la route de l'ouest, celle qui part de Tranchecolline, et qui arrive aux Tarides par un pont."}, [134]={npc="Kargal Battlescar", tgt="Kargal Battlescar"}, [135]={npc="Kargal Battlescar", tgt="Kargal Battlescar"}, [136]={text="Allez vers l'ouest à partir de Poste de garde extérieur. Tournez vers le sud au carrefour en T pour le La Croisée."}, [137]={hint="Suivre la route à l'ouest à partir du Poste de garde extérieur de Kargal."}, [138]={npc="Sergra Darkthorn", tgt="Sergra Darkthorn"}, [139]={npc="Kaplak", tgt="Kaplak", desc="Fil d'Ariane Orc. Les trolls peuvent récupérer La Main brisée directement depuis Therzok."}, [140]={hint="Aller voir Therzok dans la Faille de l'ombre à Orgrimmar.", desc="Fil d'Ariane Orc. Les trolls peuvent récupérer La Main brisée directement depuis Therzok."}, [141]={npc="Therzok", tgt="Therzok", desc="Fil d'Ariane Orc. Les trolls peuvent récupérer La Main brisée directement depuis Therzok."}, [142]={npc="Therzok", tgt="Therzok", desc="Volez d'abord Clé de Tazan, puis récupérez son pack. Gardez la clé pour le suivi."}, [143]={hint="Tuer Tazan et apporter sa Sacoche à Therzok, à la Faille de l'ombre à Orgrimmar.", desc="Volez d'abord Clé de Tazan, puis récupérez son pack. Gardez la clé pour le suivi."}, [144]={npc="Therzok", tgt="Therzok", desc="Volez d'abord Clé de Tazan, puis récupérez son pack. Gardez la clé pour le suivi."}, [145]={npc="Therzok", tgt="Therzok", desc="Conservez la clé et attendez que Therzok propose La Main brisée avant d'ouvrir le pack.", star={"Lame de malice", {"ROGUE"}}}, [146]={hint="Voler la Clé de Tazan puis l'utiliser pour ouvrir sa Sacoche et livrer son contenu à Therzok dans la Faille de l'ombre à Orgrimmar.", desc="Conservez la clé et attendez que Therzok propose La Main brisée avant d'ouvrir le pack."}, [147]={npc="Therzok", tgt="Therzok", desc="Conservez la clé et attendez que Therzok propose La Main brisée avant d'ouvrir le pack.", star={"Lame de malice", {"ROGUE"}}}, [148]={npc="Swart", tgt="Swart", desc="Commencez à Tranchecolline ou Sabot-de-Sang. Les deux dérivations rejoignent la même chaîne La Croisée."}, [149]={hint="Trouver Kranal Fiss dans les Tarides.", desc="Commencez à Tranchecolline ou Sabot-de-Sang. Les deux dérivations rejoignent la même chaîne La Croisée."}, [150]={npc="Kranal Fiss", tgt="Kranal Fiss", desc="Commencez à Tranchecolline ou Sabot-de-Sang. Les deux dérivations rejoignent la même chaîne La Croisée."}, [151]={npc="Sian'dur", tgt="Sian'dur", tag="Facultatif", desc="Effectuez l'une des trois introductions ou obtenez Dompter la bête directement à partir de Thotar."}, [152]={hint="Parler à Thotar, à Tranchecolline.", tag="Facultatif", desc="Effectuez l'une des trois introductions ou obtenez Dompter la bête directement à partir de Thotar."}, [153]={npc="Thotar", tgt="Thotar", tag="Facultatif", desc="Effectuez l'une des trois introductions ou obtenez Dompter la bête directement à partir de Thotar."}, [154]={npc="Kali Remik", tgt="Kali Remik", tag="Facultatif", desc="Effectuez l'une des trois introductions ou obtenez Dompter la bête directement à partir de Thotar."}, [155]={hint="Parler à Thotar, à Tranchecolline.", tag="Facultatif", desc="Effectuez l'une des trois introductions ou obtenez Dompter la bête directement à partir de Thotar."}, [156]={npc="Thotar", tgt="Thotar", tag="Facultatif", desc="Effectuez l'une des trois introductions ou obtenez Dompter la bête directement à partir de Thotar."}, [157]={npc="Kary Thunderhorn", tgt="Kary Thunderhorn", tag="Facultatif", desc="Effectuez l'une des trois introductions ou obtenez Dompter la bête directement à partir de Thotar."}, [158]={hint="Parler à Thotar, à Tranchecolline.", tag="Facultatif", desc="Effectuez l'une des trois introductions ou obtenez Dompter la bête directement à partir de Thotar."}, [159]={npc="Thotar", tgt="Thotar", tag="Facultatif", desc="Effectuez l'une des trois introductions ou obtenez Dompter la bête directement à partir de Thotar."}, [160]={npc="Thotar", tgt="Thotar"}, [161]={hint="Utiliser le Bâtonnet de domptage pour dompter un sanglier tacheté redoutable. S'entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Thotar de Tranchecolline."}, [162]={npc="Thotar", tgt="Thotar"}, [163]={npc="Thotar", tgt="Thotar", desc="Prérequis permanent : Dompter la bête. La deuxième cible est un Clampant de l'écume."}, [164]={hint="Utiliser le Bâtonnet de domptage pour dompter un Clampant de l'écume. S'entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Thotar, à Tranchecolline.", desc="Prérequis permanent : Dompter la bête. La deuxième cible est un Clampant de l'écume."}, [165]={npc="Thotar", tgt="Thotar", desc="Prérequis permanent : Dompter la bête. La deuxième cible est un Clampant de l'écume."}, [166]={npc="Thotar", tgt="Thotar", desc="Prérequis éternel : Dompter la bête. Apprivoisez un troisième Scorpide blindé."}, [167]={hint="Domptez un Scorpide blindé à l'aide du Bâtonnet de domptage. Entraînez-vous puis retournez voir Thotar à Tranchecolline.", desc="Prérequis éternel : Dompter la bête. Apprivoisez un troisième Scorpide blindé."}, [168]={npc="Thotar", tgt="Thotar", desc="Prérequis éternel : Dompter la bête. Apprivoisez un troisième Scorpide blindé."}, [169]={npc="Thotar", tgt="Thotar", desc="Après l'apprivoisement, entraînez les compétences des animaux de compagnie dans le Vallée de l'Honneur de Orgrimmar."}, [170]={hint="Adressez-vous à Orkmar Grimshot à Orgrimmar.", desc="Après l'apprivoisement, entraînez les compétences des animaux de compagnie dans le Vallée de l'Honneur de Orgrimmar."}, [171]={npc="Ormak Grimshot", tgt="Ormak Grimshot", desc="Après l'apprivoisement, entraînez les compétences des animaux de compagnie dans le Vallée de l'Honneur de Orgrimmar."}, [172]={npc="Ophek", tgt="Ophek", tag="Facultatif", desc="Sautez le fil d'Ariane si vous le souhaitez. Horde Les démonistes peuvent accepter cette quête."}, [173]={hint="Parler à Gan'rul Bloodeye à Orgrimmar.", tag="Facultatif", desc="Sautez le fil d'Ariane si vous le souhaitez. Horde Les démonistes peuvent accepter cette quête."}, [174]={npc="Gan'rul Bloodeye", tgt="Gan'rul Bloodeye", tag="Facultatif", desc="Sautez le fil d'Ariane si vous le souhaitez. Horde Les démonistes peuvent accepter cette quête."}, [175]={npc="Gan'rul Bloodeye", tgt="Gan'rul Bloodeye", desc="Récupérez la tablette auprès de Rocher du crâne, à l'est de Orgrimmar."}, [176]={hint="Récupérer la Tablette de Verga pour Gan'rul Bloodeye à Orgrimmar.", desc="Récupérez la tablette auprès de Rocher du crâne, à l'est de Orgrimmar."}, [177]={npc="Gan'rul Bloodeye", tgt="Gan'rul Bloodeye", desc="Récupérez la tablette auprès de Rocher du crâne, à l'est de Orgrimmar."}, [178]={npc="Gan'rul Bloodeye", tgt="Gan'rul Bloodeye", desc="Utilisez le glyphe de Neeru, battez le Marcheur du Vide, puis rendez-vous à Gan'rul."}, [179]={hint="Utiliser les Glyphes d'invocation pour invoquer et soumettre un marcheur du Vide, puis rapporter les Glyphes d'invocation à Gan'rul Bloodeye, à Orgrimmar.", desc="Utilisez le glyphe de Neeru, battez le Marcheur du Vide, puis rendez-vous à Gan'rul."}, [180]={npc="Gan'rul Bloodeye", tgt="Gan'rul Bloodeye", desc="Utilisez le glyphe de Neeru, battez le Marcheur du Vide, puis rendez-vous à Gan'rul."}, [181]={npc="Tai'jin", tgt="Tai'jin", desc="Entraînez d'abord Soins inférieurs (rang 2) et Mot de pouvoir : Robustesse."}, [182]={hint="Trouver le grunt Kor'ja et la guérir de ses blessures en utilisant Soins inférieurs (Rang 2). Lui accorder ensuite le Mot de pouvoir : Robustesse, puis retourner voir Tai'jin, sur Tranchecolline.", desc="Entraînez d'abord Soins inférieurs (rang 2) et Mot de pouvoir : Robustesse."}, [183]={npc="Tai'jin", tgt="Tai'jin", desc="Entraînez d'abord Soins inférieurs (rang 2) et Mot de pouvoir : Robustesse."}, [184]={npc="Tai'jin", tgt="Tai'jin"}, [185]={hint="Parler à Ur'kyo à Orgrimmar."}, [186]={npc="Ur'kyo", tgt="Ur'kyo"}, [187]={npc="Ur'kyo", tgt="Ur'kyo"}, [188]={hint="Remplissez les objectifs de la quête."}, [189]={npc="Ur'kyo", tgt="Ur'kyo"}, [190]={npc="Uthel'nay", tgt="Uthel'nay", tag="Facultatif", desc="Demandez Uthel'nay dans Orgrimmar ou Thurston Xane dans Thunder Bluff. Un'Thuwa propose Les Tas de Ju-Ju."}, [191]={hint="Aller voir Un'thuwa.", tag="Facultatif", desc="Si vous êtes dans Village de Sen'jin, récupérez Les Tas de Ju-Ju directement auprès de Un'Thuwa."}, [192]={npc="Un'Thuwa", tgt="Un'Thuwa", tag="Facultatif", desc="Si vous êtes dans Village de Sen'jin, récupérez Les Tas de Ju-Ju directement auprès de Un'Thuwa."}, [193]={npc="Un'Thuwa", tgt="Un'Thuwa"}, [194]={hint="Détruire 4 Tas de Ju-Ju, puis retourner voir Un'thuwa au village de Sen'jin."}, [195]={npc="Un'Thuwa", tgt="Un'Thuwa"}, [196]={text="Apprenez le point de vol de Devrak (51.50, 30.34). Vous pouvez lier votre pierre de foyer avec Boorand Plainswind l'aubergiste (51.99, 29.89)."}}},
    ["01-3"] = {name="Camp Narache", tips={{k="交通", text="Vous venez d'une autre zone de départ? Dirigez-vous vers Sabot-de-Sang, puis suivez la route vers le sud jusqu'à Mesa de Nuage rouge jusqu'à Camp Narache. Voir les notes de voyage ci-dessus."}, {k="取捨", text="Faites Le Rite de force, La fin de Brochaigu! et Les sangliers de guerre apprivoisés sur une boucle Ravin de Roncelame. Acceptez L'attaque du Camp Narache si vous pillez la carte."}, {k="提醒", text="En dessous du niveau 6? Tuez Sanglier de guerre ou Huran Dos-hirsute le long du bord de Ravin de Roncelame, puis dirigez-vous vers Sabot-de-Sang.", s={{"En dessous du niveau 6?"}, {"Tuez Sanglier de guerre ou Huran Dos-hirsute le long du bord de Ravin de Roncelame, puis dirigez-vous vers Sabot-de-Sang"}}}}, danger={[1]="Quilboar emballe la rampe étroite dans Ravin de Roncelame. Effacez-le avant de tirer Chef Brochaigu Mantépine. Retraite vers Mesa de Nuage rouge."}, grind={[1]={mob="Trotteur des plaines", note="Des foules normales denses et pour la plupart neutres près du puits sud-est de Camp Narache. Tirez un ennemi à la fois pendant La chasse commence."}, [2]={mob="Puma des montagnes", note="Des foules normales denses et pour la plupart neutres sur le versant sud de Mesa de Nuage rouge. Tirez un ennemi à la fois pour obtenir les peaux nécessaires dans La chasse continue."}, [3]={mob="Sanglier de guerre Dos-hirsute", note="Les foules normales se regroupent parmi Huran Dos-hirsute dans Ravin de Roncelame. Dégagez d'abord les bords. Associez-le avec Sanglier de guerre et Le Rite de force."}}, supply={[1]={npc="Bronk Steelrage"}, [2]={npc="Moodan Sungrain"}, [3]={npc="Kawnie Softbreeze"}}, steps={[1]={npc="Bon-cadeau (Camp Narache)", npcObj=true, tag="Facultatif, Nécessite une vérification dans le jeu", desc="Acceptez uniquement si vous possédez un Bon-cadeau (Camp Narache). Faites un clic droit sur le bon de départ de votre course. Il n'y a pas de pick-up sur la carte."}, [2]={hint="Apporter le Bon-cadeau (Camp Narache) à Vorn Skyseer.", tag="Facultatif", desc="Acceptez uniquement si vous possédez un Bon-cadeau (Camp Narache)."}, [3]={npc="Vorn Skyseer", tgt="Vorn Skyseer", tag="Facultatif", desc="Acceptez uniquement si vous possédez un Bon-cadeau (Camp Narache)."}, [4]={npc="Grull Hawkwind", tgt="Grull Hawkwind"}, [5]={npc="Chef Hawkwind", tgt="Chef Hawkwind"}, [6]={hint="Grull Hawkwind, à Camp Narache voudrait que vous lui apportiez 7 Plumes de trotteurs des plaines et 7 morceaux de Viande de trotteur des plaines."}, [7]={hint="Partir chercher la mère du Chef Hawkwind, près du puits, au sud-est de Camp Narache."}, [8]={npc="Grand-mère Hawkwind", tgt="Grand-mère Hawkwind"}, [9]={npc="Grand-mère Hawkwind", tgt="Grand-mère Hawkwind"}, [10]={hint="Prendre une Cruche d'eau du puits.", desc="Récupérez le Cruche d'eau dans le puits à côté de Grand-mère Hawkwind."}, [11]={npc="Grull Hawkwind", tgt="Grull Hawkwind"}, [12]={npc="Chef Hawkwind", tgt="Chef Hawkwind"}, [13]={npc="Grull Hawkwind", tgt="Grull Hawkwind"}, [14]={npc="Chef Hawkwind", tgt="Chef Hawkwind"}, [15]={npc="Brave Windfeather", tgt="Brave Windfeather"}, [16]={hint="Grull Hawkwind, à Camp Narache, voudrait que vous lui apportiez 10 Peaux de puma des montagnes."}, [17]={hint="Aller voir le Prophète Graytongue qui vit dans les collines au sud de Camp Narache."}, [18]={npc="Prophète Graytongue", tgt="Prophète Graytongue"}, [19]={npc="Prophète Graytongue", tgt="Prophète Graytongue"}, [20]={npc="Prophète Graytongue", tgt="Prophète Graytongue", tag="Facultatif", desc="Apportez l'encens à l'autel sud-est dans les 10 minutes suivant sa réception.", star={"Bourse en cuir brûlée"}}, [21]={hint="Portez l'encens fumant jusqu'au sanctuaire de An'she et de Mu'sha, dans les collines au sud-est. Vous avez dix minutes avant que l'encens ne soit réduit en cendres !", tag="Facultatif", desc="Apportez l'encens à l'autel sud-est dans les 10 minutes suivant sa réception."}, [22]={npc="Feu rituel", npcObj=true, tag="Facultatif", desc="Apportez l'encens à l'autel sud-est dans les 10 minutes suivant sa réception.", star={"Bourse en cuir brûlée"}}, [23]={npc="Grull Hawkwind", tgt="Grull Hawkwind"}, [24]={npc="Grull Hawkwind", tgt="Grull Hawkwind"}, [25]={hint="Tuer des Dos-hirsute dans le Ravin de Roncelame et apporter 12 Ceintures de Dos-hirsute au chef Hawkwind au camp Narache."}, [26]={hint="Apporter la Tête du chef Brochaigu Mantépine à Brave Windfeather à la mesa de Nuage rouge."}, [27]={hint="Grull Hawkwind, à Camp Narache, voudrait que vous tuiez des sangliers de guerre, et que vous rapportiez 8 Groins de sanglier de guerre et 8 Flancs de sanglier de guerre."}, [28]={npc="Carte couverte de poussière", npcObj=true, tag="Facultatif", desc="Récupérez la carte tachée de saleté sur Huran Dos-hirsute et cliquez dessus avec le bouton droit."}, [29]={npc="Chef Hawkwind", tgt="Chef Hawkwind"}, [30]={npc="Brave Windfeather", tgt="Brave Windfeather"}, [31]={npc="Grull Hawkwind", tgt="Grull Hawkwind"}, [32]={hint="Apporter les Plans d'attaque Dos-hirsute au chef Hawkwind, au camp Narache.", tag="Facultatif"}, [33]={npc="Chef Hawkwind", tgt="Chef Hawkwind", tag="Facultatif"}, [34]={npc="Chef Hawkwind", tgt="Chef Hawkwind"}, [35]={npc="Chef Hawkwind", tgt="Chef Hawkwind", tag="Facultatif"}, [36]={npc="Antur Fallow", tgt="Antur Fallow", tag="Facultatif", desc="Prise en charge à Antur Fallow, du côté ouest du camp."}, [37]={npc="Grull Hawkwind", tgt="Grull Hawkwind", desc="Terminez La chasse commence, puis prenez la quête d'introduction auprès du maître de classe."}, [38]={hint="Lire la Note simple, et parler à Harutt Thunderhorn, à Camp Narache.", desc="Terminez La chasse commence, puis prenez la quête d'introduction auprès du maître de classe."}, [39]={npc="Harutt Thunderhorn", tgt="Harutt Thunderhorn", desc="Terminez La chasse commence, puis prenez la quête d'introduction auprès du maître de classe."}, [40]={npc="Grull Hawkwind", tgt="Grull Hawkwind", desc="Terminez La chasse commence, puis prenez la quête d'introduction auprès du maître de classe."}, [41]={hint="Lire la Note runique, et parler à Meela Dawnstrider, à Camp Narache.", desc="Terminez La chasse commence, puis prenez la quête d'introduction auprès du maître de classe."}, [42]={npc="Meela Dawnstrider", tgt="Meela Dawnstrider", desc="Terminez La chasse commence, puis prenez la quête d'introduction auprès du maître de classe."}, [43]={npc="Prophétesse Ravenfeather", tgt="Prophétesse Ravenfeather"}, [44]={hint="Apporter 2 Applications de Baume rituel au Prophète Ravenfeather au Camp Narache."}, [45]={npc="Prophétesse Ravenfeather", tgt="Prophétesse Ravenfeather"}, [46]={npc="Prophétesse Ravenfeather", tgt="Prophétesse Ravenfeather", desc="Buvez le Sapta pour voir le Manifestation de terre mineure."}, [47]={hint="Trouver le Rocher des kodos et boire le Sapta de terre.", desc="Buvez le Sapta pour voir le Manifestation de terre mineure."}, [48]={npc="Manifestation de terre mineure", tgt="Manifestation de terre mineure", desc="Buvez le Sapta pour voir le Manifestation de terre mineure."}, [49]={npc="Manifestation de terre mineure", tgt="Manifestation de terre mineure", desc="Terminez la quête pour obtenir votre Totem de terre."}, [50]={hint="Apporter le Quartz brut à la prophétesse Ravenfeather au Camp Narache.", desc="Terminez la quête pour obtenir votre Totem de terre."}, [51]={npc="Prophétesse Ravenfeather", tgt="Prophétesse Ravenfeather", desc="Terminez la quête pour obtenir votre Totem de terre."}, [52]={npc="Grull Hawkwind", tgt="Grull Hawkwind"}, [53]={hint="Lire la Note gravée, et parler à Lanka Farshot, sur la Mesa de Nuage rouge."}, [54]={npc="Lanka Farshot", tgt="Lanka Farshot"}, [55]={npc="Grull Hawkwind", tgt="Grull Hawkwind"}, [56]={hint="Lire la Note verdoyante, et parler à Gart Mistrunner, à Camp Narache."}, [57]={npc="Gart Mistrunner", tgt="Gart Mistrunner"}, [58]={text="Quittez Mesa de Nuage rouge et suivez la route vers le nord jusqu'à Sabot-de-Sang."}}},
    ["01-4"] = {name="Mulgore", nameA="Mulgore: {a:222}", tips={{k="取捨", text="Effectuez Le Rite de vision ( → →), Le Rite de sagesse et Voyage à Thunder Bluff. Débloquer le point de vol sur la dernière étape."}, {k="取捨", text="Validez chaque quête de puits avant de prendre la suivante. Tauren uniquement. Ignorez la chaîne Puits Wildmane si vous êtes déjà au niveau 12. Tauren uniquement.", s={{"Validez chaque quête de puits avant de prendre la suivante. Tauren uniquement. Ignorez la chaîne Puits Wildmane si vous êtes déjà au niveau 12. Tauren uniquement.", {race={"Tauren"}}}}}, {k="取捨", text="Vous exécutez Gouffre de Ragefeu? Récupérez Tester la force de l'ennemi et À la recherche de la sacoche perdue auprès de Rahauro dans Thunder Bluff."}, {k="提醒", text="Besoin de XP pour le niveau 12? Broyez des harpies dans le nord de Mulgore, ou dirigez-vous vers Rochers rouges ou la Venture Co. Mine. Consultez les quêtes de classe ci-dessous pour débloquer le niveau 10.", s={{"Besoin de XP pour le niveau 12?"}, {"Broyez des harpies dans le nord de Mulgore, ou dirigez-vous vers Rochers rouges ou la Venture Co"}, {"Mine"}, {"Consultez les quêtes de classe ci-dessous pour débloquer le niveau 10"}}}}, danger={[1]="Les patrouilles et les mineurs peuvent se rassembler au sein de la Venture Co. Mine. Nettoyez d'abord l'extérieur, prenez le presse-papiers et quittez le tunnel."}, grind={[1]={mob="Traqueur des prairies", note="Des foules normales dispersées au nord de Sabot-de-Sang. Tirez un ennemi à la fois dans l'herbe et surveillez les vagabonds. Récupérez les matériaux Mazzranache."}, [2]={mob="Superviseur de la KapitalRisk", note="Les foules normales se regroupent autour de Venture Co. Mine. Tirez de l'extérieur et surveillez les travailleurs et les patrouilles. Associez-le aux quêtes de la mine."}, [3]={mob="Matriarche Furie-des-vents", note="Des foules normales denses au camp de harpies au nord-ouest de Mulgore. Tirez le long du bord pour éviter les roulettes. Broyez ici si vous êtes proche du niveau 12."}}, supply={[1]={npc="Kauth l'aubergiste"}, [2]={npc="Harant Ironbrace"}, [3]={npc="Kauth l'aubergiste"}, [4]={npc="Kennah Hawkseye"}, [5]={npc="Tal"}}, steps={[1]={hint="Apportez le paquet de fournitures à Kaga Sabot-sauvage près de Sabot-de-Sang.", tag="Facultatif"}, [2]={npc="Kaga Sabot-sauvage", tgt="Kaga Sabot-sauvage", tag="Facultatif"}, [3]={npc="Kaga Sabot-sauvage", tgt="Kaga Sabot-sauvage", tag="Facultatif"}, [4]={hint="Asseyez-vous près du feu de camp basique de Kaga et attendez de recevoir l'amélioration Repos amplifié.", tag="Facultatif"}, [5]={npc="Kaga Sabot-sauvage", tgt="Kaga Sabot-sauvage", tag="Facultatif"}, [6]={npc="Kaga Sabot-sauvage", tgt="Kaga Sabot-sauvage", tag="Facultatif"}, [7]={npc="Kaga Sabot-sauvage", tgt="Kaga Sabot-sauvage", tag="Facultatif", desc="Apprenez Dépeçage avant d'accepter. Rendez-vous une fois que vous remplissez les exigences de compétence."}, [8]={hint="Apporter le Totem de Hawkwind à Baine Sabot-de-Sang à Sabot-de-Sang. Suivre la route hors du camp Narache."}, [9]={npc="Baine Bloodhoof", tgt="Baine Bloodhoof"}, [10]={hint="Livrer le Ballot de fourrures à l'aubergiste Kauth à Sabot-de-Sang.", tag="Facultatif"}, [11]={npc="Kauth l'aubergiste", tgt="Kauth l'aubergiste", tag="Facultatif"}, [12]={text="liez votre pierre de foyer avec Kauth l'aubergiste dans Sabot-de-Sang (45.93, 64.16)."}, [13]={npc="Baine Bloodhoof", tgt="Baine Bloodhoof"}, [14]={hint="Parler à Zarlman Deux-Lunes, à Sabot-de-Sang."}, [15]={npc="Zarlman Deux-Lunes", tgt="Zarlman Deux-Lunes"}, [16]={npc="Zarlman Deux-Lunes", tgt="Zarlman Deux-Lunes"}, [17]={npc="Harken Windtotem", tgt="Harken Windtotem"}, [18]={npc="Maur Raincaller", tgt="Maur Raincaller"}, [19]={npc="Baine Bloodhoof", tgt="Baine Bloodhoof"}, [20]={npc="Brave Wildrunner", tgt="Brave Wildrunner"}, [21]={npc="Mull Thunderhorn", tgt="Mull Thunderhorn"}, [22]={npc="Krang Stonehoof", tgt="Krang Stonehoof", tag="Facultatif"}, [23]={hint="Battez 3 autres personnages-joueurs en duel ou guerriers novices pour Tang Sabot-de-Pierre.", tag="Facultatif"}, [24]={npc="Krang Stonehoof", tgt="Krang Stonehoof", tag="Facultatif"}, [25]={npc="Ahab Sabot-de-Blé", tgt="Ahab Sabot-de-Blé", tag="Facultatif"}, [26]={hint="Parlez à Pyall Sabots-Feutrés, à Sabot-de-Sang, pour apprendre à cuisiner.", tag="Facultatif"}, [27]={npc="Pyall Silentstride", tgt="Pyall Silentstride", tag="Facultatif"}, [28]={hint="Parlez à Yonn Entaille-Profonde, à Sabot-de-Sang, pour apprendre à fabriquer un objet de camping propre à votre métier une fois que vous vous serez fait la main.", tag="Facultatif"}, [29]={npc="Yonn Deepcut", tgt="Yonn Deepcut", tag="Facultatif"}, [30]={text="À l'est de Sabot-de-Sang → caravane et centaures"}, [31]={hint="Collecter 2 Pierres de puits et 2 Pommes de pin et les rapporter à Zarlman Deux-Lunes, à Sabot-de-Sang."}, [32]={hint="Apporter 8 Trophées de plumes de Rapace à Harken Windtotem, à Sabot-de-Sang."}, [33]={hint="Apporter un Coeur de loup des plaines, un Fémur de puma des basses plaines, une Ecaille de trotteur des plaines et un Gésier de rapace à Maur Raincaller, à Sabot-de-Sang."}, [34]={hint="Apporter 6 Pattes de loup des prairies et 4 Serres de trotteur des plaines à Mull Thunderhorn à Sabot-de-Sang."}, [35]={npc="Mull Thunderhorn", tgt="Mull Thunderhorn"}, [36]={npc="Mull Thunderhorn", tgt="Mull Thunderhorn"}, [37]={hint="Utiliser le Totem de purification de Winterhoof au puits Winterhoof, puis retourner voir Mull Thunderhorn."}, [38]={hint="Trouvez la longue-marche Malah Longuebrise à l'est de Sabot-de-Sang, près de la frontière de Mulgore."}, [39]={npc="Malah Longuebrise", tgt="Malah Longuebrise"}, [40]={npc="Malah Longuebrise", tgt="Malah Longuebrise"}, [41]={npc="Morin Cloudstalker", tgt="Morin Cloudstalker"}, [42]={hint="Examiner le contenu d'une caisse de provisions à la caravane dévastée, pour Morin Cloudstalker."}, [43]={npc="Caisse de ravitaillements scellée", npcObj=true}, [44]={npc="Caisse de ravitaillements scellée", npcObj=true}, [45]={hint="Rapporter les Documents de la KapitalRisk à Morin Cloudstalker, à côté de Sabot-de-Sang."}, [46]={npc="Morin Cloudstalker", tgt="Morin Cloudstalker"}, [47]={npc="Morin Cloudstalker", tgt="Morin Cloudstalker"}, [48]={npc="Morin Cloudstalker", tgt="Morin Cloudstalker"}, [49]={npc="Mull Thunderhorn", tgt="Mull Thunderhorn"}, [50]={npc="Mull Thunderhorn", tgt="Mull Thunderhorn"}, [51]={hint="Apportez le rapport de la longue-marche Malah au brave Course-Sauvage à Sabot-de-Sang."}, [52]={npc="Brave Wildrunner", tgt="Brave Wildrunner"}, [53]={npc="Brave Wildrunner", tgt="Brave Wildrunner"}, [54]={hint="Apportez le rapport de la longue-marche Malah à Baine Sabot-de-Sang."}, [55]={npc="Baine Bloodhoof", tgt="Baine Bloodhoof"}, [56]={npc="Baine Bloodhoof", tgt="Baine Bloodhoof"}, [57]={npc="Zarlman Deux-Lunes", tgt="Zarlman Deux-Lunes"}, [58]={npc="Harken Windtotem", tgt="Harken Windtotem"}, [59]={npc="Zarlman Deux-Lunes", tgt="Zarlman Deux-Lunes"}, [60]={npc="Baine Bloodhoof", tgt="Baine Bloodhoof"}, [61]={npc="Ruul Eagletalon", tgt="Ruul Eagletalon"}, [62]={npc="Yaw Sharpmane", tgt="Yaw Sharpmane", tag="Facultatif"}, [63]={text="Ouest : Palemane et le chantier de fouilles. Suivez la vision du voyant"}, [64]={hint="Tuer 10 Tanneurs crins-pâles, 8 Ecorcheurs crins-pâles et 5 Braconniers crins-pâles, puis retourner voir Baine Sabot-de-Sang, à Sabot-de-Sang."}, [65]={hint="Collecter 5 Piolets de prospecteur."}, [66]={hint="Consommer l'Eau des Prophètes devant le feu tribal, à Sabot-de-Sang et suivre la vision quand elle apparaîtra.", desc="Buvez Eau des Prophètes par le feu de camp. Suivez la vision NW; faire des quêtes en route."}, [67]={npc="Périth Sabot-tempête", tgt="Périth Sabot-tempête", tag="Facultatif", desc="Pour éviter un city trip anticipé, accompagnez-le maintenant et rendez-vous lors de votre première visite Thunder Bluff."}, [68]={hint="Aidez Périth Sabot-tempête à fuir le rocher des Crins-pâles, et allez aux Pitons-du-Tonnerre pour informer Cairne Sabot-de-Sang que Périth est sain et sauf.", tag="Facultatif"}, [69]={npc="Prophète Wiserunner", tgt="Prophète Wiserunner"}, [70]={npc="Prophète Wiserunner", tgt="Prophète Wiserunner"}, [71]={hint="Rapporter 6 Griffes de Traqueur et 6 Griffes de puma à Mull Thunderhorn."}, [72]={text="Utilisez votre pierre de foyer pour revenir à Sabot-de-Sang et validez ensemble les quêtes western."}, [73]={npc="Baine Bloodhoof", tgt="Baine Bloodhoof"}, [74]={npc="Baine Bloodhoof", tgt="Baine Bloodhoof"}, [75]={npc="Maur Raincaller", tgt="Maur Raincaller"}, [76]={npc="Mull Thunderhorn", tgt="Mull Thunderhorn"}, [77]={npc="Mull Thunderhorn", tgt="Mull Thunderhorn"}, [78]={hint="Ahab Sabot-de-Blé, à Sabot-de-Sang en Mulgore, veut que vous nourrissiez son précieux chiot, Kyle le Frénétique.", tag="Facultatif", desc="Apportez un Viande de trotteur tendre et attendez que Kyle se rapproche avant de le nourrir."}, [79]={npc="Ahab Sabot-de-Blé", tgt="Ahab Sabot-de-Blé", tag="Facultatif"}, [80]={text="Puits du nord, pierres rouges et mine du nord-est"}, [81]={hint="Utilisez le Totem de purification de Thunderhorn au puits Thunderhorn, puis retournez voir Mull."}, [82]={hint="Voyager aux Rochers rouges, à l'est de Thunder Bluff et parler à Esprit ancestral."}, [83]={npc="Gardien du savoir Raintotem", tgt="Gardien du savoir Raintotem"}, [84]={hint="Le Gardien du savoir Raintotem veut que vous tuiez 8 Intrus Dos-hirsute aux Rochers rouges."}, [85]={hint="Apporter 8 Serres de Furie-des-vents à Ruul Eagletalon, à Sabot-de-Sang."}, [86]={npc="Esprit ancestral", tgt="Esprit ancestral"}, [87]={npc="Gardien du savoir Raintotem", tgt="Gardien du savoir Raintotem"}, [88]={npc="Esprit ancestral", tgt="Esprit ancestral"}, [89]={hint="Tuez 6 Centaures galak et 4 estafettes galak, puis apportez la tête d'Herak le Pilleur à Baine Sabot-de-Sang."}, [90]={hint="Tuer 14 Travailleurs de la KapitalRisk et 6 Superviseurs de la KapitalRisk pour Morin Cloudstalker de Sabot-de-Sang."}, [91]={hint="Tuer le Superviseur Fizsprocket et rapporter son Ecritoire à Morin Cloudstalker, à Sabot-de-Sang."}, [92]={npc="Plans d'expansion de Mulgore", npcObj=true, tag="Facultatif", desc="Récupérez Plans d'expansion de Mulgore sur Superviseur Fizsprocket pour démarrer la quête."}, [93]={hint="Récupérez les pages du superviseur Vibrouage se trouvant encore à l'intérieur de la mine de la KapitalRisk, et apportez-les à Morin Traqueur-de-Nuage, près de Sabot-de-Sang.", tag="Facultatif", desc="Récupérez les trois notes à l'intérieur du Venture Co. Mine avant de partir."}, [94]={hint="Abattez Chakuyak, puis rapportez sa fourrure.", tag="Facultatif"}, [95]={npc="Morin Cloudstalker", tgt="Morin Cloudstalker"}, [96]={npc="Morin Cloudstalker", tgt="Morin Cloudstalker"}, [97]={npc="Morin Cloudstalker", tgt="Morin Cloudstalker", tag="Facultatif"}, [98]={npc="Morin Cloudstalker", tgt="Morin Cloudstalker", tag="Facultatif", desc="En dessous du niveau 12? Faites plus de quêtes près de la mine."}, [99]={hint="Apportez la clé de déboiseur à Morin Traqueur-de-Nuage, à l'extérieur de Sabot-de-Sang.", tag="Facultatif", desc="En dessous du niveau 12? Faites plus de quêtes près de la mine."}, [100]={npc="Morin Cloudstalker", tgt="Morin Cloudstalker", tag="Facultatif", desc="En dessous du niveau 12? Faites plus de quêtes près de la mine."}, [101]={npc="Baine Bloodhoof", tgt="Baine Bloodhoof"}, [102]={npc="Ruul Eagletalon", tgt="Ruul Eagletalon"}, [103]={npc="Yaw Sharpmane", tgt="Yaw Sharpmane", tag="Facultatif"}, [104]={npc="Baine Bloodhoof", tgt="Baine Bloodhoof"}, [105]={npc="Mull Thunderhorn", tgt="Mull Thunderhorn"}, [106]={npc="Mull Thunderhorn", tgt="Mull Thunderhorn", tag="Facultatif"}, [107]={hint="Apporter 8 Dents de loup alpha des prairies à Mull Thunderhorn, à Sabot-de-Sang.", tag="Facultatif"}, [108]={npc="Mull Thunderhorn", tgt="Mull Thunderhorn", tag="Facultatif"}, [109]={npc="Mull Thunderhorn", tgt="Mull Thunderhorn", tag="Facultatif"}, [110]={hint="Utiliser le Totem de purification de Wildmane au puits Wildmane, puis retournez voir Mull Thunderhorn.", tag="Facultatif"}, [111]={npc="Mull Thunderhorn", tgt="Mull Thunderhorn", tag="Facultatif"}, [112]={npc="Mull Thunderhorn", tgt="Mull Thunderhorn", tag="Facultatif"}, [113]={npc="Skorn Whitecloud", tgt="Skorn Whitecloud", tag="Facultatif"}, [114]={hint="Apporter 4 Griffes de Rôdeurs des basses plaines à Melor Stonehoof à Thunder Bluff.", tag="Facultatif"}, [115]={text="Débloquer Thunder Bluff et continuez vers le La Croisée"}, [116]={text="Suivez la route principale de Mulgore jusqu'à Thunder Bluff. Prenez l'ascenseur et apprenez le point de vol de Tal (47.00, 49.83)."}, [117]={hint="Parler à Cairne Sabot-de-Sang à Thunder Bluff."}, [118]={hint="Sollicitez une audience auprès de Cairne Sabot-de-Sang aux Pitons-du-Tonnerre."}, [119]={npc="Cairne Bloodhoof", tgt="Cairne Bloodhoof"}, [120]={npc="Cairne Bloodhoof", tgt="Cairne Bloodhoof"}, [121]={npc="Cairne Bloodhoof", tgt="Cairne Bloodhoof", tag="Facultatif"}, [122]={hint="Apportez le rapport de Corne-Tonnerre à l'archidruide Hamuul Totem-Runique, aux Pitons-du-Tonnerre.", tag="Facultatif"}, [123]={npc="Archidruide Hamuul Runetotem", tgt="Archidruide Hamuul Runetotem", tag="Facultatif"}, [124]={npc="Melor Stonehoof", tgt="Melor Stonehoof", tag="Facultatif"}, [125]={npc="Eylah Cornesol", tgt="Eylah Cornesol", tag="Facultatif", desc="Achetez les quatre matériaux sur la falaise. Utilisez l'encens sur Cime des chasseurs."}, [126]={hint="Achetez un paquet d'herbes à Nida l'herboriste, un fagot de brindilles de cèdre à Nata la fournisseuse de composants d'enchantements, des fibres tendineuses à Mahu le fournisseur de matériel de travail du cuir, ainsi que du silex et de l'amadou de cérémonie à Naal le fournisseur de matériel de cuisine.", tag="Facultatif", desc="Achetez les quatre matériaux sur la falaise. Utilisez l'encens sur Cime des chasseurs."}, [127]={npc="Eylah Cornesol", tgt="Eylah Cornesol", tag="Facultatif", desc="Achetez les quatre matériaux sur la falaise. Utilisez l'encens sur Cime des chasseurs."}, [128]={npc="Veren Tallstrider", tgt="Veren Tallstrider", tag="Facultatif", desc="Apprenez d'abord Dépeçage, puis remettez 12 Cuir léger."}, [129]={hint="Apporter 12 pièces de Cuir léger à Veren Tallstrider, à Thunder Bluff.", tag="Facultatif", desc="Apprenez d'abord Dépeçage, puis remettez 12 Cuir léger. Rendez-vous à Thunder Bluff. Skin des bêtes de bas niveau pour Cuir léger ou achetez-le."}, [130]={npc="Veren Tallstrider", tgt="Veren Tallstrider", tag="Facultatif", desc="Apprenez d'abord Dépeçage, puis remettez 12 Cuir léger."}, [131]={npc="Veren Tallstrider", tgt="Veren Tallstrider", tag="Facultatif", desc="Répondez à l'exigence Travail du cuir. Apportez 4 Cuir léger et 4 Bobine de fil grossier."}, [132]={hint="Apporter 4 pièces de Cuir léger et 4 Bobines de fil grossier à Veren Tallstrider, à Thunder Bluff.", tag="Facultatif", desc="Répondez à l'exigence Travail du cuir. Apportez 4 Cuir léger et 4 Bobine de fil grossier. Rendez-vous à Thunder Bluff. Skin ou acheter Cuir léger. Achetez Bobine de fil grossier auprès d'un fournisseur."}, [133]={npc="Veren Tallstrider", tgt="Veren Tallstrider", tag="Facultatif", desc="Répondre aux exigences LW. Apportez 4 Cuir léger et 4 Bobine de fil grossier. Boramu (44.08, 44.89)."}, [134]={text="Au niveau 12, quittez Mulgore par la porte est. Apprenez le point de vol de Omusa Thunderhorn dans Camp Taurajo (44.45, 59.15)."}, [135]={npc="Kirge Sternhorn", tgt="Kirge Sternhorn", tag="Facultatif", desc="Récupérer en passant Camp Taurajo. Dirigez-vous vers le La Croisée."}, [136]={hint="Parler à Thork, à la Croisée des Tarides.", tag="Facultatif", desc="Récupérer en passant Camp Taurajo. Dirigez-vous vers le La Croisée."}, [137]={npc="Thork", tgt="Thork", tag="Facultatif", desc="Récupérer en passant Camp Taurajo. Dirigez-vous vers le La Croisée."}, [138]={npc="Narm Skychaser", tgt="Narm Skychaser", desc="Commencez dans Sabot-de-Sang. Continuer L'appel du feu - L'appel du feu de Kranal ou au La Croisée."}, [139]={hint="Trouver Kranal Fiss dans les Tarides.", desc="Commencez dans Sabot-de-Sang. Continuer L'appel du feu - L'appel du feu de Kranal ou au La Croisée."}, [140]={npc="Kranal Fiss", tgt="Kranal Fiss", desc="Commencez dans Sabot-de-Sang. Continuer L'appel du feu - L'appel du feu de Kranal ou au La Croisée."}, [141]={npc="Kary Thunderhorn", tgt="Kary Thunderhorn", tag="Facultatif", desc="Choisissez l'un des trois fils d'Ariane ou obtenez Dompter la bête à partir de Yaw Sharpmane."}, [142]={hint="Parler à Yaw Sharpmane, au village Bloodhoof.", tag="Facultatif", desc="Choisissez l'un des trois fils d'Ariane ou obtenez Dompter la bête à partir de Yaw Sharpmane."}, [143]={npc="Yaw Sharpmane", tgt="Yaw Sharpmane", tag="Facultatif", desc="Choisissez l'un des trois fils d'Ariane ou obtenez Dompter la bête à partir de Yaw Sharpmane."}, [144]={npc="Sian'dur", tgt="Sian'dur", tag="Facultatif", desc="Choisissez l'un des trois fils d'Ariane ou obtenez Dompter la bête à partir de Yaw Sharpmane."}, [145]={hint="Parler à Yaw Sharpmane, au village Bloodhoof.", tag="Facultatif", desc="Choisissez l'un des trois fils d'Ariane ou obtenez Dompter la bête à partir de Yaw Sharpmane."}, [146]={npc="Yaw Sharpmane", tgt="Yaw Sharpmane", tag="Facultatif", desc="Choisissez l'un des trois fils d'Ariane ou obtenez Dompter la bête à partir de Yaw Sharpmane."}, [147]={npc="Thotar", tgt="Thotar", tag="Facultatif", desc="Choisissez l'un des trois fils d'Ariane ou obtenez Dompter la bête à partir de Yaw Sharpmane."}, [148]={hint="Parler à Yaw Sharpmane, à Sabot-de-Sang.", tag="Facultatif", desc="Choisissez l'un des trois fils d'Ariane ou obtenez Dompter la bête à partir de Yaw Sharpmane."}, [149]={npc="Yaw Sharpmane", tgt="Yaw Sharpmane", tag="Facultatif", desc="Choisissez l'un des trois fils d'Ariane ou obtenez Dompter la bête à partir de Yaw Sharpmane."}, [150]={npc="Yaw Sharpmane", tgt="Yaw Sharpmane"}, [151]={hint="Utiliser le Bâtonnet de domptage pour dompter un trotteur des plaines adulte. S'entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Yaw Sharpmane, à Sabot-de-Sang."}, [152]={npc="Yaw Sharpmane", tgt="Yaw Sharpmane"}, [153]={npc="Yaw Sharpmane", tgt="Yaw Sharpmane"}, [154]={hint="Utiliser le Bâtonnet de domptage pour dompter un Traqueur des prairies. S'entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Yaw Sharpmane, à Sabot-de-Sang."}, [155]={npc="Yaw Sharpmane", tgt="Yaw Sharpmane"}, [156]={npc="Yaw Sharpmane", tgt="Yaw Sharpmane"}, [157]={hint="Utiliser le Bâtonnet de domptage pour dompter un Rapace. S'entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Yaw Sharpmane, à Sabot-de-Sang."}, [158]={npc="Yaw Sharpmane", tgt="Yaw Sharpmane"}, [159]={npc="Yaw Sharpmane", tgt="Yaw Sharpmane", desc="Après les trois apprentissages, entraînez les compétences des animaux de compagnie sur Cime des chasseurs dans Thunder Bluff."}, [160]={hint="Parler à Holt Thunderhorn, sur la Cime des Chasseurs, à Thunder Bluff.", desc="Après les trois apprentissages, entraînez les compétences des animaux de compagnie sur Cime des chasseurs dans Thunder Bluff."}, [161]={npc="Holt Thunderhorn", tgt="Holt Thunderhorn", desc="Après les trois apprentissages, entraînez les compétences des animaux de compagnie sur Cime des chasseurs dans Thunder Bluff."}, [162]={npc="Gennia Runetotem", tgt="Gennia Runetotem", tag="Facultatif", desc="Effectuez l'une des trois introductions ou récupérez Reflet-de-Lune à partir de Turak Runetotem."}, [163]={hint="Parler à Turak Runetotem, sur la Cime des Anciens de Thunder Bluff.", tag="Facultatif", desc="Effectuez l'une des trois introductions ou récupérez Reflet-de-Lune à partir de Turak Runetotem."}, [164]={npc="Turak Runetotem", tgt="Turak Runetotem", tag="Facultatif", desc="Effectuez l'une des trois introductions ou récupérez Reflet-de-Lune à partir de Turak Runetotem."}, [165]={npc="Pala l'aubergiste", tgt="Pala l'aubergiste", tag="Facultatif", desc="Effectuez l'une des trois introductions ou récupérez Reflet-de-Lune à partir de Turak Runetotem."}, [166]={hint="Parler à Turak Runetotem, sur la Cime des Anciens de Thunder Bluff.", tag="Facultatif", desc="Effectuez l'une des trois introductions ou récupérez Reflet-de-Lune à partir de Turak Runetotem."}, [167]={npc="Turak Runetotem", tgt="Turak Runetotem", tag="Facultatif", desc="Effectuez l'une des trois introductions ou récupérez Reflet-de-Lune à partir de Turak Runetotem."}, [168]={npc="Gryshka l'aubergiste", tgt="Gryshka l'aubergiste", tag="Facultatif", desc="Effectuez l'une des trois introductions ou récupérez Reflet-de-Lune à partir de Turak Runetotem."}, [169]={hint="Parler à Turak Runetotem, sur la Cime des Anciens de Thunder Bluff.", tag="Facultatif", desc="Effectuez l'une des trois introductions ou récupérez Reflet-de-Lune à partir de Turak Runetotem."}, [170]={npc="Turak Runetotem", tgt="Turak Runetotem", tag="Facultatif", desc="Effectuez l'une des trois introductions ou récupérez Reflet-de-Lune à partir de Turak Runetotem."}, [171]={npc="Turak Runetotem", tgt="Turak Runetotem", desc="Apprenez la téléportation auprès de Turak Runetotem, puis utilisez-la pour atteindre Reflet-de-Lune."}, [172]={hint="Utiliser le sort \"Téléportation : Reflet-de-Lune\" pour aller à Reflet-de-Lune. Une fois sur place, parler à Dendrite Starblaze, au village de Havrenuit.", desc="Apprenez la téléportation auprès de Turak Runetotem, puis utilisez-la pour atteindre Reflet-de-Lune."}, [173]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze", desc="Apprenez la téléportation auprès de Turak Runetotem, puis utilisez-la pour atteindre Reflet-de-Lune."}, [174]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze", desc="Parlez à Esprit du Grand ours au nord-ouest, puis retournez à Havrenuit."}, [175]={hint="Aller voir l'esprit du Grand ours, au nord-ouest de Reflet-de-Lune et apprendre ce qu'il peut vous enseigner sur la nature de l'ours. Quand cela est fait, retourner voir Dendrite Starblaze, à Havrenuit, dans Reflet-de-Lune.", desc="Parlez à Esprit du Grand ours au nord-ouest, puis retournez à Havrenuit."}, [176]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze", desc="Parlez à Esprit du Grand ours au nord-ouest, puis retournez à Havrenuit."}, [177]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze"}, [178]={hint="Retourner à Thunder Bluff, et parler à Turak Runetotem, sur la Cime des Anciens."}, [179]={npc="Turak Runetotem", tgt="Turak Runetotem"}, [180]={npc="Turak Runetotem", tgt="Turak Runetotem"}, [181]={hint="Utiliser la Poussière lunaire cénarienne sur la Pierre des séléniens, entre Mulgore et les Tarides, pour invoquer Lunegriffe. Affronter Lunegriffe, et gagner la force physique et spirituelle qu'il possède."}, [182]={npc="Turak Runetotem", tgt="Turak Runetotem"}, [183]={text="Suivez la route vers le nord jusqu'au La Croisée. Apprenez le point de vol de Devrak (51.50, 30.34) et liez votre pierre de foyer avec Boorand Plainswind l'aubergiste (51.99, 29.89)."}}},
    ["01-5"] = {name="Le Glas", tips={{k="交通", text="Vous venez d'une autre zone de départ? Descendez à la tour zeppelin au sud de Brill et suivez la route vers l'ouest jusqu'à Le Glas. Voir les notes de voyage ci-dessus."}, {k="提醒", text="Commencez par Réveil brutal à l'intérieur de la crypte (Mort-vivant uniquement). Récupérez Les Déchus auprès de Prêtre des ombres Sarvis (30.84, 66.20). S'il n'a pas de quête, suivez la route jusqu'à Brill.", s={{"Commencez par Réveil brutal à l'intérieur de la crypte (Mort-vivant uniquement)", {race={"Scourge"}}}, {"Récupérez Les Déchus auprès de Prêtre des ombres Sarvis (30.84, 66.20)"}, {"S'il n'a pas de quête, suivez la route jusqu'à Brill"}}}, {k="提醒", text="Tuez les squelettes de Rattlecage jusqu'au niveau 3, puis acceptez La dernière volonté de Marla. Dirigez-vous vers Brill au niveau 6 ou une fois que vous avez terminé cette section.", s={{"Tuez les squelettes de Rattlecage jusqu'au niveau 3, puis acceptez La dernière volonté de Marla"}, {"Dirigez-vous vers Brill au niveau 6 ou une fois que vous avez terminé cette section"}}}}, danger={[1]="Le tunnel étroit du Grottes des Tisse-nuit peut tirer des groupes d'araignées des deux côtés. Dégagez l'entrée avant d'entrer."}, grind={[1]={mob="Zombie décharné", note="Des foules normales denses et pour la plupart neutres au nord de Le Glas. Tirez sur un ennemi à la fois pendant Les Déchus aux niveaux 1 et 2."}, [2]={mob="Araignée Tisse-nuit", note="Des foules normales denses à l'intérieur de Grottes des Tisse-nuit. Dégagez par étapes depuis l'entrée pour éviter des tirages supplémentaires. Associez-le aux quêtes de la grotte."}, [3]={mob="Initié écarlate", note="Des foules normales denses dans le camp écarlate oriental. Dégagez le long du bord pour éviter de tirer les fanatiques. Associez-le à la quête du brassard."}}, supply={[1]={npc="Forgeron Rand"}, [2]={npc="Joshua Kien"}, [3]={npc="Joshua Kien"}}, steps={[1]={npc="Fossoyeur Mordo", tgt="Fossoyeur Mordo"}, [2]={hint="Parler au prêtre des ombres Sarvis."}, [3]={npc="Prêtre des ombres Sarvis", tgt="Prêtre des ombres Sarvis"}, [4]={npc="Prêtre des ombres Sarvis", tgt="Prêtre des ombres Sarvis"}, [5]={hint="Le prêtre des ombres Sarvis veut que vous tuiez 8 Zombies lunatiques et 8 Zombies décharnés."}, [6]={npc="Prêtre des ombres Sarvis", tgt="Prêtre des ombres Sarvis"}, [7]={npc="Novice Elreth", tgt="Novice Elreth"}, [8]={hint="La novice Elreth a besoin de 6 Pattes de charognard et de 6 Ailes de chauve-souris du crépuscule."}, [9]={npc="Novice Elreth", tgt="Novice Elreth"}, [10]={npc="Prêtre des ombres Sarvis", tgt="Prêtre des ombres Sarvis"}, [11]={npc="Garde noir Saltain", tgt="Garde noir Saltain"}, [12]={npc="Exécuteur Arren", tgt="Exécuteur Arren"}, [13]={npc="Novice Elreth", tgt="Novice Elreth"}, [14]={npc="Aramis Mainmartel", tgt="Aramis Mainmartel"}, [15]={hint="Tuez 12 Squelettes Cliquethorax, puis retournez voir le prêtre des ombres Sarvis au Glas."}, [16]={hint="Fouiller Le Glas et ses alentours pour trouver 6 pièces de fournitures de récupération, et les ramener au Garde noir Saltain."}, [17]={hint="L'Exécuteur Arren veut que vous tuiez 10 Jeunes Tisse-nuit et 8 Araignées Tisse-nuit."}, [18]={hint="Apporter le Cadavre de Samuel Fipps sur la Tombe de Marla, puis retourner voir la novice Elreth."}, [19]={hint="Libérez 6 victimes entoilées dans la grotte des tisse-nuit pour Aramis Mainmartel, au Glas."}, [20]={npc="Prêtre des ombres Sarvis", tgt="Prêtre des ombres Sarvis"}, [21]={npc="Garde noir Saltain", tgt="Garde noir Saltain"}, [22]={npc="Exécuteur Arren", tgt="Exécuteur Arren"}, [23]={npc="Novice Elreth", tgt="Novice Elreth"}, [24]={npc="Aramis Mainmartel", tgt="Aramis Mainmartel"}, [25]={npc="Exécuteur Arren", tgt="Exécuteur Arren"}, [26]={hint="Apporter à l'Exécuteur Arren 12 Bracelets écarlates, que vous trouverez sur des Convertis écarlates et des Initiés écarlates."}, [27]={npc="Exécuteur Arren", tgt="Exécuteur Arren"}, [28]={npc="Exécuteur Arren", tgt="Exécuteur Arren"}, [29]={hint="Tuer Meven Korgal, le messager, au camp de la Croisade, puis ramener toutes les informations trouvées à l'Exécuteur Arren."}, [30]={npc="Exécuteur Arren", tgt="Exécuteur Arren"}, [31]={npc="Exécuteur Arren", tgt="Exécuteur Arren"}, [32]={npc="Prêtre des ombres Sarvis", tgt="Prêtre des ombres Sarvis", desc="Remettez d'abord Les Déchus. Alt. Ramassage : Novice Elreth (30.86, 66.05)."}, [33]={hint="Lisez le parchemin consacré et parlez à Aramis Mainmartel, dans l'église du Glas.", desc="Remettez d'abord Les Déchus dans Le Glas."}, [34]={npc="Aramis Mainmartel", tgt="Aramis Mainmartel", desc="Remettez d'abord Les Déchus dans Le Glas."}, [35]={npc="Aramis Mainmartel", tgt="Aramis Mainmartel", desc="Remettez Les Déchus avant de quitter Le Glas."}, [36]={hint="Soignez 5 nécrogardes blessés avec votre technique Lumière sacrée.", desc="Remettez Les Déchus avant de quitter Le Glas."}, [37]={npc="Aramis Mainmartel", tgt="Aramis Mainmartel", desc="Remettez Les Déchus avant de quitter Le Glas."}, [38]={npc="Aramis Mainmartel", tgt="Aramis Mainmartel", desc="Remettez d'abord Redécouverte de la Lumière."}, [39]={hint="Trouvez la paladine effrayée au Glas.", desc="Remettez d'abord Redécouverte de la Lumière."}, [40]={npc="Aramis Mainmartel", tgt="Aramis Mainmartel", desc="Remettez d'abord Redécouverte de la Lumière."}, [41]={npc="Aramis Mainmartel", tgt="Aramis Mainmartel", desc="Acceptez avant de quitter Le Glas. Rendez-vous à votre arrivée à Brill."}, [42]={npc="Prêtre des ombres Sarvis", tgt="Prêtre des ombres Sarvis", desc="Terminez Les Déchus, puis prenez la quête d'introduction auprès du maître de classe."}, [43]={hint="Lire le Parchemin simple, et parler à Dannal Stern, au Glas.", desc="Terminez Les Déchus, puis prenez la quête d'introduction auprès du maître de classe."}, [44]={npc="Dannal Stern", tgt="Dannal Stern", desc="Terminez Les Déchus, puis prenez la quête d'introduction auprès du maître de classe."}, [45]={npc="Prêtre des ombres Sarvis", tgt="Prêtre des ombres Sarvis", desc="Terminez Les Déchus, puis prenez la quête d'introduction auprès du maître de classe."}, [46]={hint="Lire le Parchemin codé, et parler à David Trias, au Glas.", desc="Terminez Les Déchus, puis prenez la quête d'introduction auprès du maître de classe."}, [47]={npc="David Trias", tgt="David Trias", desc="Terminez Les Déchus, puis prenez la quête d'introduction auprès du maître de classe."}, [48]={npc="Prêtre des ombres Sarvis", tgt="Prêtre des ombres Sarvis"}, [49]={hint="Lire le Rouleau contaminé, et parler à Maximillion, au Glas."}, [50]={npc="Maximillion", tgt="Maximillion"}, [51]={npc="Venya Marthand", tgt="Venya Marthand", desc="Itinéraire Le Glas. Horde Les démonistes peuvent accepter cette quête."}, [52]={hint="Apporter 3 Crânes de Cliquethorax à Venya Marthand.", desc="Itinéraire Le Glas. Horde Les démonistes peuvent accepter cette quête."}, [53]={npc="Venya Marthand", tgt="Venya Marthand", desc="Itinéraire Le Glas. Horde Les démonistes peuvent accepter cette quête."}, [54]={npc="Prêtre des ombres Sarvis", tgt="Prêtre des ombres Sarvis", desc="Remettez Les Déchus pour déverrouiller le parchemin."}, [55]={hint="Lire le Parchemin béni, et parler au sombre clerc Duesten, dans l'église du Glas.", desc="Remettez Les Déchus pour déverrouiller le parchemin."}, [56]={npc="Sombre clerc Duesten", tgt="Sombre clerc Duesten", desc="Remettez Les Déchus pour déverrouiller le parchemin."}, [57]={npc="Sombre clerc Duesten", tgt="Sombre clerc Duesten"}, [58]={hint="Parler au sombre clerc Beryl dans les Clairières de Tirisfal."}, [59]={npc="Sombre clerc Beryl", tgt="Sombre clerc Beryl"}, [60]={npc="Prêtre des ombres Sarvis", tgt="Prêtre des ombres Sarvis", desc="Remettez d'abord Les Déchus."}, [61]={hint="Lire le Parchemin glyphé, et parler à Isabella, dans l'église du Glas.", desc="Remettez d'abord Les Déchus."}, [62]={npc="Isabella", tgt="Isabella", desc="Remettez d'abord Les Déchus."}, [63]={text="Prenez la route est en sortant de Le Glas jusqu'à Brill."}}},
    ["01-6"] = {name="Clairières de Tirisfal", nameA="Clairières de Tirisfal: {a:159}", tips={{k="提醒", text="Si vous n'avez pas accepté Informations décisives, commencez à l'auberge Brill et récupérez le premier lot de quêtes.", s={{"Si vous n'avez pas accepté Informations décisives, commencez à l'auberge Brill et récupérez le premier lot de quêtes"}}}, {k="取捨", text="Réalisez les objectifs écarlate, araignée et mousse grave sur la boucle sud-est. Associez les murlocs de la rive nord aux quêtes d'Agamand. Validez les quêtes à proximité et partez pour le La Croisée au niveau 12."}, {k="取捨", text="Achetez Bobine de fil grossier auprès d'un vendeur pour Le Frisson de la mort près de l'auberge. Si vous avez encore besoin de peaux de murloc de la rive nord pour Des peaux pour les Réprouvés, terminez-les lors de votre prochain voyage sur la côte."}, {k="取捨", text="Terminez les deux quêtes locales Aube d'argent pour débloquer Forteresse de Bandarion (La forteresse de Bandarion) (Orques, Trolls et Mort-vivant uniquement). Certains suivis concernent uniquement le Mort-vivant. Si vous vous dirigez directement vers le La Croisée, partez après les deux quêtes locales.", s={{"Terminez les deux quêtes locales Aube d'argent pour débloquer Forteresse de Bandarion (La forteresse de Bandarion) (Orques, Trolls et Mort-vivant uniquement)", {race={"Orc", "Troll", "Scourge"}}}, {"Certains suivis concernent uniquement le Mort-vivant", {race={"Scourge"}}}, {"Si vous vous dirigez directement vers le La Croisée, partez après les deux quêtes locales"}}}, {k="提醒", text="En dessous du niveau 12? Faites les quêtes En Guerre avec la Croisade écarlate, La Crypte Familiale, ou Aube d'argent, L'émissaire de l'Aube d'argent, Le Culte des damnés, et Les vestiges de la guerre, selon la disponibilité et l'endroit où vous vous trouvez.", s={{"En dessous du niveau 12?"}, {"Faites les quêtes En Guerre avec la Croisade écarlate, La Crypte Familiale, ou Aube d'argent, L'émissaire de l'Aube d'argent, Le Culte des damnés, et Les vestiges de la guerre, selon la disponibilité et l'endroit où vous vous trouvez"}}}}, danger={[1]="Surveillez les zombies et les esprits errants dans le cimetière sud-est. Dégager le long du bord pour ne pas être enfermé."}, grind={[1]={mob="Missionnaire écarlate", note="Roulettes normales éparses au sud-ouest de Brill. Tirez un ennemi à la fois du bord lors des premières quêtes Croisade écarlate."}, [2]={mob="Esprit vagabond", note="Les monstres normaux se regroupent avec les Blood Zombies dans le cimetière sud-est. Surveillez les patrouilles. Associez Patrouille d'arrière-garde à la quête des herbes du cimetière."}, [3]={mob="Néophyte sombre", note="Des foules normales denses près des quêtes Aube d'argent au sud-est. Tirez un ennemi à la fois du bord du camp pour éviter les Dark Enforcers. Broyer de 11 à 12."}}, supply={[1]={npc="Renée l'aubergiste"}, [2]={npc="Abe Winters"}, [3]={npc="Renée l'aubergiste"}, [4]={npc="Mme Winters"}, [5]={npc="Doras"}}, steps={[1]={npc="Garde noir Simmer", tgt="Garde noir Simmer"}, [2]={npc="Gordo", tgt="Gordo"}, [3]={hint="Volez 10 Potirons dans la ferme à l'ouest, juste au nord du Glas, et apportez-les à l'Apothicaire Johaan à Brill."}, [4]={hint="Récolter 3 herbes des ténèbres et les apporter à l'Apprenti Apothicaire Holland au cimetière de Brill."}, [5]={hint="Livrer les documents de la Croisade écarlate à l'Exécuteur Zygand à Brill."}, [6]={npc="Exécuteur Zygand", tgt="Exécuteur Zygand"}, [7]={npc="Apothicaire Johaan", tgt="Apothicaire Johaan"}, [8]={npc="Apprenti apothicaire Holland", tgt="Apprenti apothicaire Holland"}, [9]={text="liez votre pierre de foyer avec Renée l'aubergiste dans Brill (61.72, 52.05)."}, [10]={npc="Apothicaire Johaan", tgt="Apothicaire Johaan"}, [11]={hint="Donner la citrouille enchantée au Zélote écarlate capturé qui est gardé dans le cellier de la taverne des Pendus."}, [12]={npc="Zélote écarlate capturé", tgt="Zélote écarlate capturé"}, [13]={npc="Garde noir Dillinger", tgt="Garde noir Dillinger"}, [14]={npc="Magistrat Sevren", tgt="Magistrat Sevren"}, [15]={npc="Apothicaire Johaan", tgt="Apothicaire Johaan"}, [16]={npc="Apprenti apothicaire Holland", tgt="Apprenti apothicaire Holland"}, [17]={npc="Exécuteur Zygand", tgt="Exécuteur Zygand"}, [18]={npc="Exécuteur Zygand", tgt="Exécuteur Zygand"}, [19]={npc="Exécuteur Zygand", tgt="Exécuteur Zygand"}, [20]={npc="Recherché !", npcObj=true}, [21]={text="À l'extérieur de Brill et du camp Scarlet à l'ouest"}, [22]={hint="Rapporter 7 Griffes putrides au Garde noir Dillinger à Brill."}, [23]={hint="Tuer des Profanateurs Poils-putrides et des Gnolls Poils-putrides."}, [24]={hint="Collecter 5 fioles de Sang de sombredogues pour l'Apothicaire Johaan de la ville de Brill."}, [25]={hint="Récolter 10 Herbes maléfiques et les apporter à l'apprenti apothicaire Holland."}, [26]={hint="Tuer 10 Guerriers écarlates pour l'Exécuteur Zygand."}, [27]={hint="Punissez 5 nécrogardes pour l'exécuteur Zygand."}, [28]={hint="Obtenez les rapports des nécrogardes Dillinger et Kristof et de Gordo pour l'exécuteur Zygand."}, [29]={npc="Garde noir Dillinger", tgt="Garde noir Dillinger"}, [30]={npc="Magistrat Sevren", tgt="Magistrat Sevren"}, [31]={npc="Apothicaire Johaan", tgt="Apothicaire Johaan"}, [32]={npc="Apprenti apothicaire Holland", tgt="Apprenti apothicaire Holland"}, [33]={npc="Exécuteur Zygand", tgt="Exécuteur Zygand"}, [34]={npc="Exécuteur Zygand", tgt="Exécuteur Zygand"}, [35]={npc="Exécuteur Zygand", tgt="Exécuteur Zygand"}, [36]={npc="Garde noir Dillinger", tgt="Garde noir Dillinger"}, [37]={npc="Apothicaire Johaan", tgt="Apothicaire Johaan"}, [38]={npc="Garde noir Burgess", tgt="Garde noir Burgess"}, [39]={npc="Exécuteur Zygand", tgt="Exécuteur Zygand"}, [40]={npc="Apprenti apothicaire Holland", tgt="Apprenti apothicaire Holland"}, [41]={npc="Magistrat Sevren", tgt="Magistrat Sevren"}, [42]={text="Murlocs de la côte nord, Œil-de-ver et Moulins d'Agamand"}, [43]={npc="Coleman Farthing", tgt="Coleman Farthing"}, [44]={npc="Coleman Farthing", tgt="Coleman Farthing"}, [45]={npc="Gretchen Dedmar", tgt="Gretchen Dedmar"}, [46]={hint="L'Apothicaire Johaan de la ville de Brill a besoin de 5 Ecailles d'Aileron noir prises sur les murlocs des Clairières de Tirisfal."}, [47]={hint="Tuer Œil-de-ver et rapporter ses griffes à l'Exécuteur Zygand pour toucher la récompense."}, [48]={hint="Rassemblez 5 Côtes ébréchées et 3 Crânes noircis et rapportez-les au garde noir Dillinger à Brill."}, [49]={hint="Rapporter les restes de Gregor, de Nissa et de Thurman à Coleman Farthing, à Brill."}, [50]={hint="Tuer Devlin Agamand et ramener ses restes à Coleman Farthing à Brill."}, [51]={npc="Une lettre pour Yvette", npcObj=true, tag="Facultatif"}, [52]={npc="Apothicaire Johaan", tgt="Apothicaire Johaan"}, [53]={npc="Exécuteur Zygand", tgt="Exécuteur Zygand"}, [54]={npc="Garde noir Dillinger", tgt="Garde noir Dillinger"}, [55]={npc="Coleman Farthing", tgt="Coleman Farthing"}, [56]={npc="Coleman Farthing", tgt="Coleman Farthing"}, [57]={hint="Trouver Yvette Farthing. Lui donner la lettre de Thurman Agamand.", tag="Facultatif"}, [58]={npc="Yvette Farthing", tgt="Yvette Farthing", tag="Facultatif"}, [59]={npc="Coleman Farthing", tgt="Coleman Farthing"}, [60]={hint="Parler au magistrat Sevren à Brill."}, [61]={npc="Magistrat Sevren", tgt="Magistrat Sevren"}, [62]={npc="Apothicaire Johaan", tgt="Apothicaire Johaan"}, [63]={text="Camp écarlate du sud, avant-poste sud-est et Ferme des Balnir"}, [64]={hint="Tuer le capitaine Perrine ainsi que 3 Zélotes écarlates et 3 Missionnaires écarlates."}, [65]={hint="Parler à la Garde noire Linnea."}, [66]={npc="Garde noir Linnea", tgt="Garde noir Linnea"}, [67]={npc="Garde noir Linnea", tgt="Garde noir Linnea"}, [68]={npc="Garde noir Linnea", tgt="Garde noir Linnea"}, [69]={npc="Shelene Rhobart", tgt="Shelene Rhobart", tag="Facultatif", desc="Garde noir Linnea propose également cette quête (65.49, 60.25)."}, [70]={hint="Tuer 8 Horreurs sanguinolentes et 8 Esprits vagabonds, puis revenez voir Linnea, à son camp."}, [71]={hint="Récoltez 5 herbes sépulcrales et apportez-les à l'apprenti apothicaire Holland."}, [72]={hint="L'Apothicaire Johaan de la ville de Brill désire que vous lui rameniez 4 échantillons de Venin de Tisse-nuit vicieuse."}, [73]={hint="Rapporter 5 Peaux de chauve-souris du crépuscule et une Bobine de fil grossier à Gretchen Dedmar à Brill."}, [74]={npc="Garde noir Linnea", tgt="Garde noir Linnea"}, [75]={hint="Retourner voir le Magistrat Sevren à Brill."}, [76]={npc="Magistrat Sevren", tgt="Magistrat Sevren"}, [77]={npc="Apprenti apothicaire Holland", tgt="Apprenti apothicaire Holland"}, [78]={npc="Apothicaire Johaan", tgt="Apothicaire Johaan"}, [79]={npc="Gretchen Dedmar", tgt="Gretchen Dedmar"}, [80]={npc="Apothicaire Johaan", tgt="Apothicaire Johaan"}, [81]={hint="Apporter la Boisson spéciale de Johaan au Montagnard captif."}, [82]={npc="Montagnard capturé", tgt="Montagnard capturé"}, [83]={npc="Exécuteur Zygand", tgt="Exécuteur Zygand"}, [84]={npc="Exécuteur Zygand", tgt="Exécuteur Zygand"}, [85]={hint="Apportez à Shelene Rhobart 8 membranes d'ailes de chauve-souris de la pénombre, 6 peaux de sombredogue et 3 peaux de Murloc aileron noir.", tag="Facultatif"}, [86]={npc="Shelene Rhobart", tgt="Shelene Rhobart", tag="Facultatif"}, [87]={hint="L'Exécuteur Zygand de Brill vous a chargé de liquider le capitaine Vachon et 5 Frères écarlates."}, [88]={hint="Apporter 10 Anneaux de la Croisade écarlate au Garde noir Burgess à Brill."}, [89]={npc="Exécuteur Zygand", tgt="Exécuteur Zygand"}, [90]={npc="Garde noir Burgess", tgt="Garde noir Burgess"}, [91]={npc="Exécuteur Zygand", tgt="Exécuteur Zygand", tag="Facultatif", desc="Le plus éloigné du village. N'y allez que si vous êtes encore en dessous du niveau 12."}, [92]={hint="Assassiner le capitaine Melrach et ses deux gardes du corps pour l'Exécuteur Zygand de la ville de Brill.", tag="Facultatif", desc="Le plus éloigné du village. N'y allez que si vous êtes encore en dessous du niveau 12."}, [93]={npc="Exécuteur Zygand", tgt="Exécuteur Zygand", tag="Facultatif", desc="Le plus éloigné du village. N'y allez que si vous êtes encore en dessous du niveau 12."}, [94]={npc="Magistrat Sevren", tgt="Magistrat Sevren", tag="Facultatif", desc="Acceptez une fois les deux quêtes Agamand terminées.", star={"Bâton de sombrebois", {"MAGE", "PRIEST", "WARLOCK", "DRUID", "SHAMAN"}}}, [95]={hint="Tuer 8 Spectres ancestraux et 8 Ancêtres pourrissants.", tag="Facultatif", desc="Acceptez une fois les deux quêtes Agamand terminées."}, [96]={npc="Magistrat Sevren", tgt="Magistrat Sevren", tag="Facultatif", desc="Acceptez une fois les deux quêtes Agamand terminées.", star={"Bâton de sombrebois", {"MAGE", "PRIEST", "WARLOCK", "DRUID", "SHAMAN"}}}, [97]={text="Extra XP ou nouvelles quêtes avant le niveau 12"}, [98]={npc="Garde noir Terrence", tgt="Garde noir Terrence", tag="Facultatif"}, [99]={hint="Trouvez le membre de l'Aube d'argent près de l'entrée de Fossoyeuse.", tag="Facultatif"}, [100]={npc="Hadric Harlson", tgt="Hadric Harlson", tag="Facultatif"}, [101]={npc="Hadric Harlson", tgt="Hadric Harlson", tag="Facultatif"}, [102]={npc="Hadric Harlson", tgt="Hadric Harlson", tag="Facultatif"}, [103]={hint="Tuez 8 néophytes sombres et 8 massacreurs sombres dans les clairières de Tirisfal.", tag="Facultatif"}, [104]={hint="Rassemblez 12 fragments de cristal nécrotique dans les clairières de Tirisfal.", tag="Facultatif"}, [105]={npc="Hadric Harlson", tgt="Hadric Harlson", tag="Facultatif"}, [106]={npc="Hadric Harlson", tgt="Hadric Harlson", tag="Facultatif"}, [107]={npc="Hadric Harlson", tgt="Hadric Harlson", tag="Facultatif", desc="Cela vous éloigne du poste sud-est. Sautez si vous êtes pressé."}, [108]={hint="Retrouvez Leonid Barthalomew à la forteresse de Bandarion, dans les clairières de Tirisfal.", tag="Facultatif", desc="Cela vous éloigne du poste sud-est. Sautez si vous êtes pressé."}, [109]={npc="Leonid Barthalomew le Révéré", tgt="Leonid Barthalomew le Révéré", tag="Facultatif", desc="Cela vous éloigne du poste sud-est. Sautez si vous êtes pressé."}, [110]={npc="Garde noir Linnea", tgt="Garde noir Linnea", tag="Facultatif", desc="Élite. Sautez si vous êtes solo."}, [111]={hint="Apportez le cœur de Fendécorche à la nécrogarde Linnea.", tag="Facultatif", desc="Élite. Sautez si vous êtes solo."}, [112]={npc="Garde noir Linnea", tgt="Garde noir Linnea", tag="Facultatif", desc="Élite. Sautez si vous êtes solo."}, [113]={npc="Apothicaire Johaan", tgt="Apothicaire Johaan", tag="Facultatif", desc="Rendez-vous lorsque vous vous dirigez vers Forêt des Pins argentés (Silverpine Forest) au niveau 16."}, [114]={hint="Suivez la route vers l'est à la sortie du Glas pour rejoindre le village de Brill. Présentez-vous à Shari Morpuits afin de poursuivre votre entraînement."}, [115]={npc="Shari Morpuits", tgt="Shari Morpuits"}, [116]={npc="Shari Morpuits", tgt="Shari Morpuits", desc="Acceptez lorsque vous revenez à Brill au niveau 8."}, [117]={hint="Trouvez la forteresse de Bandarion et présentez-vous devant Breton Samuels.", desc="Acceptez lorsque vous revenez à Brill au niveau 8."}, [118]={npc="Danitha Morr", tgt="Breton Samuels", desc="Acceptez lorsque vous revenez à Brill au niveau 8."}, [119]={npc="Danitha Morr", tgt="Breton Samuels", desc="Nécessite le niveau 7. Faites-le lors de votre premier voyage au donjon au niveau 8."}, [120]={hint="Tuez 8 attaquants aileron noir et 8 oracles aileron noir, puis retournez voir Breton Samuels une fois que c'est fait.", desc="Nécessite le niveau 7. Faites-le lors de votre premier voyage au donjon au niveau 8."}, [121]={npc="Danitha Morr", tgt="Breton Samuels", desc="Nécessite le niveau 7. Faites-le lors de votre premier voyage au donjon au niveau 8."}, [122]={npc="Danitha Morr", tgt="Breton Samuels", desc="Remettez d'abord Des Murlocs à nos portes."}, [123]={hint="Parlez aux habitants la forteresse de Bandarion.", desc="Remettez d'abord Des Murlocs à nos portes."}, [124]={npc="Danitha Morr", tgt="Danitha Morr", desc="Remettez d'abord Des Murlocs à nos portes."}, [125]={npc="Jorin Croge", tgt="Jorin Croge", desc="Facultatif. Au niveau 9, faites cela dans Ombreval aux côtés de Les ternis."}, [126]={npc="Danitha Morr", tgt="Danitha Morr", desc="Remettez d'abord En patrouille. Faites cela avec Procéder aux réparations si vous l'avez déjà."}, [127]={hint="Récupérez 12 morceaux de bois solides à Ombreval, dans les clairières de Tirisfal.", desc="Nécessite le niveau 8. Ignorer si déjà terminé."}, [128]={hint="Tuez 8 manœuvres ternis et 6 zélotes ternis, puis récupérez la tête du commandant Rudolph Gelhardt dans les clairières de Tirisfal."}, [129]={npc="Jorin Croge", tgt="Jorin Croge", desc="Facultatif. Sautez si vous l'avez fait au niveau 8."}, [130]={npc="Danitha Morr", tgt="Danitha Morr"}, [131]={npc="Danitha Morr", tgt="Danitha Morr", desc="Rendez d'abord Les ternis, ou attendez votre voyage Fossoyeuse pour Une leçon de divinité si vous êtes proche du niveau 12."}, [132]={hint="Apportez la tête de Rudolph Gelhardt à Sylvanas Coursevent, à Fossoyeuse.", desc="Rendez d'abord Les ternis, ou attendez votre voyage Fossoyeuse pour Une leçon de divinité si vous êtes proche du niveau 12."}, [133]={npc="Dame Sylvanas Windrunner", tgt="Dame Sylvanas Windrunner", desc="Rendez d'abord Les ternis, ou attendez votre voyage Fossoyeuse pour Une leçon de divinité si vous êtes proche du niveau 12."}, [134]={npc="Danitha Morr", tgt="Danitha Morr", desc="Au niveau 12, voyez Danitha après les quêtes du fort. Apportez 10 Etoffe de lin à Fossoyeuse."}, [135]={hint="Parlez à Tanis Aulnebois, à Fossoyeuse.", desc="Au niveau 12, voyez Danitha après les quêtes du fort. Apportez 10 Etoffe de lin à Fossoyeuse."}, [136]={npc="Tanis Aulnebois", tgt="Tanis Aulnebois", desc="Au niveau 12, voyez Danitha après les quêtes du fort. Apportez 10 Etoffe de lin à Fossoyeuse."}, [137]={npc="Tanis Aulnebois", tgt="Tanis Aulnebois"}, [138]={hint="Apporter 10 morceaux d'étoffe de lin à Tanis Aulnebois, à Fossoyeuse."}, [139]={npc="Tanis Aulnebois", tgt="Tanis Aulnebois"}, [140]={npc="Tanis Aulnebois", tgt="Tanis Aulnebois"}, [141]={hint="Retournez voir Danitha Morr, à la forteresse de Bandarion."}, [142]={npc="Danitha Morr", tgt="Danitha Morr"}, [143]={npc="Danitha Morr", tgt="Danitha Morr", desc="Si vous perdez le Symbole de vie, demandez un remplacement au Danitha Morr."}, [144]={hint="Parlez au nécrogarde Billmuth, à la forteresse de Bandarion .", desc="Si vous perdez le Symbole de vie, demandez un remplacement au Danitha Morr."}, [145]={npc="Nécrogarde Billmuth", tgt="Nécrogarde Billmuth", desc="Si vous perdez le Symbole de vie, demandez un remplacement au Danitha Morr."}, [146]={npc="Nécrogarde Billmuth", tgt="Nécrogarde Billmuth"}, [147]={hint="Prenez le Symbole de vie et utilisez-le pour ressusciter le nécrogarde Falgan dans la vallée de Tissevenin."}, [148]={npc="Nécrogarde Falgan", tgt="Nécrogarde Falgan"}, [149]={npc="Nécrogarde Falgan", tgt="Nécrogarde Falgan"}, [150]={hint="Dérobez les plans d'attaque de la Croisade écarlate aux croisés écarlates de la vallée de Tissevenin, puis retrouvez le nécrogarde Billmuth à la forteresse de Bandarion."}, [151]={npc="Nécrogarde Billmuth", tgt="Nécrogarde Billmuth"}, [152]={npc="Nécrogarde Billmuth", tgt="Nécrogarde Billmuth", desc="Apprenez Rédemption après avoir validé la quête."}, [153]={hint="Parlez à Danitha Morr au donjon de la forteresse de Bandarion.", desc="Apprenez Rédemption après avoir validé la quête."}, [154]={npc="Danitha Morr", tgt="Danitha Morr", desc="Apprenez Rédemption après avoir validé la quête."}, [155]={npc="Austil de Mon", tgt="Austil de Mon", desc="Choisissez cette chaîne ou Le vétéran Uzzek → La voie de la défense dans les Tarides."}, [156]={hint="Parler au Garde noir Dillinger à Brill.", desc="Choisissez cette chaîne ou Le vétéran Uzzek → La voie de la défense dans les Tarides."}, [157]={npc="Garde noir Dillinger", tgt="Garde noir Dillinger", desc="Choisissez cette chaîne ou Le vétéran Uzzek → La voie de la défense dans les Tarides."}, [158]={npc="Garde noir Dillinger", tgt="Garde noir Dillinger", desc="Éliminez les foules près du cimetière avant de commencer l'événement."}, [159]={hint="Tuer Ulag le Fendeur, puis parler au Garde noire Dillinger.", desc="Éliminez les foules près du cimetière avant de commencer l'événement."}, [160]={npc="Garde noir Dillinger", tgt="Garde noir Dillinger", desc="Éliminez les foules près du cimetière avant de commencer l'événement."}, [161]={npc="Garde noir Dillinger", tgt="Garde noir Dillinger", tag="Facultatif", desc="Quête de récompense d'arme facultative."}, [162]={hint="Parler à Coleman Farthing.", tag="Facultatif", desc="Quête de récompense d'arme facultative."}, [163]={npc="Coleman Farthing", tgt="Coleman Farthing", tag="Facultatif", desc="Quête de récompense d'arme facultative."}, [164]={npc="Coleman Farthing", tgt="Coleman Farthing", tag="Facultatif", desc="Trouvez un conteneur pour chacune des quatre armes."}, [165]={hint="Rapporter à Coleman Farthing la Hache de la famille Agamand, l'Epée de la famille Agamand, la Masse de la famille Agamand et la Dague de la famille Agamand.", tag="Facultatif", desc="Trouvez un conteneur pour chacune des quatre armes."}, [166]={npc="Coleman Farthing", tgt="Coleman Farthing", tag="Facultatif", desc="Trouvez un conteneur pour chacune des quatre armes."}, [167]={npc="Coleman Farthing", tgt="Coleman Farthing", tag="Facultatif", desc="Remettez d'abord L'héritage des Agamand.", star={"Hache de l'héritier", {"WARRIOR"}}}, [168]={hint="Remplissez les objectifs de la quête.", tag="Facultatif", desc="Remettez d'abord L'héritage des Agamand."}, [169]={npc="Coleman Farthing", tgt="Coleman Farthing", tag="Facultatif", desc="Remettez d'abord L'héritage des Agamand.", star={"Hache de l'héritier", {"WARRIOR"}}}, [170]={npc="Marion Call", tgt="Marion Call"}, [171]={hint="Aller voir Mennet Carkad dans le Quartier des voleurs de Fossoyeuse."}, [172]={npc="Mennet Carkad", tgt="Mennet Carkad"}, [173]={npc="Mennet Carkad", tgt="Mennet Carkad", desc="Vérifiez la route de la patrouille avant de vous diriger vers Fossoyeuse pour vous rendre."}, [174]={hint="Trouver la Lettre de recommandation d'Astor et l'apporter à Mennet Carkad dans le Quartier des voleurs.", desc="Vérifiez la route de la patrouille avant de vous diriger vers Fossoyeuse pour vous rendre."}, [175]={npc="Mennet Carkad", tgt="Mennet Carkad", desc="Vérifiez la route de la patrouille avant de vous diriger vers Fossoyeuse pour vous rendre."}, [176]={npc="Mennet Carkad", tgt="Mennet Carkad"}, [177]={hint="Aller voir Andron Gant à Fossoyeuse."}, [178]={npc="Andron Gant", tgt="Andron Gant"}, [179]={npc="Andron Gant", tgt="Andron Gant"}, [180]={hint="Apporter le Grand Livre d'Astor à Mennet Carkad dans le Quartier des voleurs de Fossoyeuse."}, [181]={npc="Mennet Carkad", tgt="Mennet Carkad"}, [182]={npc="Mennet Carkad", tgt="Mennet Carkad", star={"Lame de malice", {"ROGUE"}}}, [183]={hint="Livrer le Grand Livre d'Andron à Varimathras au Hall de la Dame noire à Fossoyeuse."}, [184]={npc="Varimathras", tgt="Varimathras", star={"Lame de malice", {"ROGUE"}}}, [185]={npc="Ageron Kargal", tgt="Ageron Kargal", tag="Facultatif", desc="Sautez le fil d'Ariane si vous le souhaitez. Horde Les démonistes peuvent accepter cette quête."}, [186]={hint="Parler à Carendin Halgar à Fossoyeuse.", tag="Facultatif", desc="Sautez le fil d'Ariane si vous le souhaitez. Horde Les démonistes peuvent accepter cette quête."}, [187]={npc="Carendin Halgar", tgt="Carendin Halgar", tag="Facultatif", desc="Sautez le fil d'Ariane si vous le souhaitez. Horde Les démonistes peuvent accepter cette quête."}, [188]={npc="Carendin Halgar", tgt="Carendin Halgar", desc="Récupérez Grimoire d'Egalin dans la tour en ruine au sud de Brill."}, [189]={hint="Retrouver le Grimoire d'Egalin et l'apporter à Carendin Halgar au Temple des damnés.", desc="Récupérez Grimoire d'Egalin dans la tour en ruine au sud de Brill."}, [190]={npc="Carendin Halgar", tgt="Carendin Halgar", desc="Récupérez Grimoire d'Egalin dans la tour en ruine au sud de Brill."}, [191]={npc="Carendin Halgar", tgt="Carendin Halgar", desc="Utilisez la rune au cercle d'invocation Quartier de la magie et battez le Marcheur du Vide."}, [192]={hint="Utiliser les Runes d'invocation pour invoquer et soumettre un marcheur du Vide, puis rapporter les Runes d'invocation à Carendin Halgar, au Temple des Damnés.", desc="Utilisez la rune au cercle d'invocation Quartier de la magie et battez le Marcheur du Vide."}, [193]={npc="Carendin Halgar", tgt="Carendin Halgar", desc="Utilisez la rune au cercle d'invocation Quartier de la magie et battez le Marcheur du Vide."}, [194]={npc="Sombre clerc Beryl", tgt="Sombre clerc Beryl", desc="Entraînez d'abord Soins inférieurs (rang 2) et Mot de pouvoir : Robustesse."}, [195]={hint="Trouver le Garde noir Kel et le guérir de ses blessures en utilisant Soins inférieurs (Rang 2). Lui accorder ensuite le Mot de pouvoir : Robustesse, puis retourner voir le sombre clerc Beryl, à Brill.", desc="Entraînez d'abord Soins inférieurs (rang 2) et Mot de pouvoir : Robustesse."}, [196]={npc="Sombre clerc Beryl", tgt="Sombre clerc Beryl", desc="Entraînez d'abord Soins inférieurs (rang 2) et Mot de pouvoir : Robustesse."}, [197]={npc="Aelthalyste", tgt="Aelthalyste"}, [198]={hint="Remplissez les objectifs de la quête."}, [199]={npc="Aelthalyste", tgt="Aelthalyste"}, [200]={npc="Cain Firesong", tgt="Cain Firesong"}, [201]={hint="Aller voir Anastasia Hartwell."}, [202]={npc="Anastasia Hartwell", tgt="Anastasia Hartwell"}, [203]={npc="Anastasia Hartwell", tgt="Anastasia Hartwell"}, [204]={hint="Apporter des Gueules-de-loup du jardin des Balnir à Anastasia Hartwell dans le Quartier de la magie de Fossoyeuse."}, [205]={npc="Anastasia Hartwell", tgt="Anastasia Hartwell"}, [206]={text="Montez à bord du zeppelin Orgrimmar sur la plate-forme ouest de Zapetta, au sud-est de Brill (60.74, 58.87). Descendez sur la plate-forme sud de la tour est à l'extérieur de Orgrimmar (50.82, 13.54)."}, [207]={text="Entrez Orgrimmar et apprenez le point de vol de Doras (45.12, 63.89). Volez vers le La Croisée s'il est déverrouillé. Sinon, dirigez-vous vers le sud jusqu'à Tranchecolline, traversez vers l'ouest dans les Tarides et continuez jusqu'à La Croisée. Apprenez le point de vol de Devrak (51.50, 30.34) et liez votre pierre de foyer avec Boorand Plainswind l'aubergiste (51.99, 29.89)."}}},
    ["01-7"] = {tips={{k="交通", text="Vous venez d'une autre zone de départ? Montez à bord du Skycutter au quai sud de Plateau de Guette-ciel à Mulgore (34.30, 25.80). Descendez au quai ouest de Valanaar (57.90, 80.90) et suivez la route vers le nord jusqu'à Bosquet de Thendal."}, {k="提醒", text="Suivez la route vers le nord de Valanaar à Bosquet de Thendal. D'autres races Horde peuvent effectuer des quêtes secondaires partagées. L'addon masque les étapes verrouillées par la course et celles avec des prérequis manquants. Aux niveaux 1 à 3, tuez les jeunes vuldrens et les cirrusflies avant les quêtes de rassemblement et de village. Toujours en dessous de 12? Terminez dans Sabot-de-Sang.", s={{"Suivez la route vers le nord de Valanaar à Bosquet de Thendal"}, {"D'autres races Horde peuvent effectuer des quêtes secondaires partagées"}, {"L'addon masque les étapes verrouillées par la course et celles avec des prérequis manquants"}, {"Aux niveaux 1 à 3, tuez les jeunes vuldrens et les cirrusflies avant les quêtes de rassemblement et de village"}, {"Toujours en dessous de 12?"}, {"Terminez dans Sabot-de-Sang"}}}, {k="取捨", text="Suivez la chaîne d'îles de Bosquet de Thendal en passant par Shen'dar et Valanaar jusqu'au Sanctuaire d'Akir. En dessous du niveau 12? Faites les quêtes secondaires du verger ou du Forêt de Trombenoire avant de monter à bord du zeppelin."}, {k="取捨", text="Reprenez les quêtes d'apprenti et de bandit ensemble. Ajoutez Hippogriffe Harcèlement (Harceleurs hippogriffes) si vous êtes Skyborne. Le problème avec les fièregriffes récompense un Sacoche simple en cuir. Des mages perturbateurs propose Idole des flots changeants aux druides. Les chamans obtiennent Totem des flammes chargées de L'appel du feu.", s={{"Reprenez les quêtes d'apprenti et de bandit ensemble"}, {"Ajoutez Hippogriffe Harcèlement (Harceleurs hippogriffes) si vous êtes Skyborne", {race={"天裔精靈"}}}, {"Le problème avec les fièregriffes récompense un Sacoche simple en cuir"}, {"Des mages perturbateurs propose Idole des flots changeants aux druides", {class={"DRUID"}}}, {"Les chamans obtiennent Totem des flammes chargées de L'appel du feu", {class={"SHAMAN"}}}}}, {k="提醒", text="Les quêtes La suite des évènements et Le Cercle terrestre affichent le niveau 13 dans le journal, mais vous pouvez les récupérer à partir du niveau 7 une fois que vous avez terminé la chaîne d'îles, selon QuestieDB.", s={{"Les quêtes La suite des évènements et Le Cercle terrestre affichent le niveau 13 dans le journal, mais vous pouvez les récupérer à partir du niveau 7 une fois que vous avez terminé la chaîne d'îles, selon QuestieDB"}}}}, danger={[1]="Mettez votre race sur votre barre d'action avant de sauter du belvédère Bosquet de Thendal. Utilisez-le immédiatement après avoir sauté.", [2]="Les Stormchasers Al'Aketh sont mélangés aux fantassins dans le camp Forêt de Trombenoire. Tirez un à la fois depuis le bord et évitez le milieu."}, grind={[1]={mob="Jeune vuldrène", note="Des foules normales denses dans Bosquet de Thendal. Tirez un ennemi à la fois et surveillez les essaims à proximité. Grind vers le début aux niveaux 1-2."}, [2]={mob="Bandit des hautes-terres", note="Des foules normales denses dans le Hautes-terres de Shen'dar. Tirez les bandits du bord du camp pour éviter les groupes. Associez-le avec L'élément du crime et Les pierres de vent chapardées."}, [3]={mob="Chasse-tempêtes al'aketh", note="Des foules normales denses dans Forêt de Trombenoire. Tirez depuis le bord pour éviter les fantassins. Associez-le au Indignes même dans la mort ou broyez-le à 12."}}, supply={[1]={npc="Fevrath Marteau-Céleste"}, [2]={npc="Uualia Solcrête"}, [3]={npc="Uualia Solcrête"}, [4]={npc="Citoyen de Zéphras"}, [5]={npc="Aedi Triple-Forgé"}, [6]={npc="Citoyen de Zéphras"}, [7]={npc="Belandiel Longvol"}, [8]={npc="Donaal Bassebrise"}, [9]={npc="Taliaa Brilleciel"}, [10]={npc="Donaal Bassebrise"}, [11]={npc="Antelariaa Mirenuée"}, [12]={npc="Tal"}}, steps={[1]={npc="Dalia la Collectionneuse", tgt="Ailee Cœur-Lointain"}, [2]={hint="Parlez à Rorian le Cherchejour dans le bosquet de Thendal."}, [3]={npc="Ailee Cœur-Lointain", tgt="Rorian le Cherchejour"}, [4]={npc="Ailee Cœur-Lointain", tgt="Rorian le Cherchejour"}, [5]={npc="Falorne Tombevent", tgt="Elatrell Frêleplume"}, [6]={npc="Myriaal Sillebrume", tgt="Myriaal Sillebrume"}, [7]={npc="Halaan Oeil-de-Faucon", tgt="Halaan Oeil-de-Faucon"}, [8]={hint="Éliminez 8 jeunes vuldrènes dans le bosquet de Thendal."}, [9]={hint="Éliminez 8 mouches-cirrus agaçantes dans le bosquet de Thendal."}, [10]={hint="Sautez du haut de la tour de guet du bosquet de Thendal et utilisez votre compétence Marche sur l'air pour ralentir votre chute.", desc="Sautez de la tour de guet, puis utilisez Marche sur l'air avant d'atterrir."}, [11]={hint="Parlez à Halaan Œil-de-Faucon et empruntez son don pour observer le pylône d'ancrage au loin."}, [12]={npc="Ailee Cœur-Lointain", tgt="Rorian le Cherchejour"}, [13]={npc="Falorne Tombevent", tgt="Elatrell Frêleplume"}, [14]={npc="Ailee Cœur-Lointain", tgt="Rorian le Cherchejour"}, [15]={npc="Halaan Oeil-de-Faucon", tgt="Halaan Oeil-de-Faucon"}, [16]={npc="Falorne Tombevent", tgt="Elatrell Frêleplume"}, [17]={npc="Destin Triple-Forgé", tgt="Dalia la Collectionneuse"}, [18]={npc="Ailee Cœur-Lointain", tgt="Rorian le Cherchejour"}, [19]={npc="Ventaari Vœu-Radieux", tgt="Ventaari Vœu-Radieux"}, [20]={hint="Détruisez la reine mouche-cirrus dans le bosquet de Thendal."}, [21]={hint="Récupérez 15 blocs de pierres de vent sur des pierres de vent brutes dans le bosquet de Thendal."}, [22]={hint="Utilisez votre compétence raciale Vue céleste à la convergence élémentaire dans le bosquet de Thendal.", desc="Utilisez le Vue céleste racial Skyborne par le Convergence élémentaire."}, [23]={npc="Falorne Tombevent", tgt="Elatrell Frêleplume"}, [24]={npc="Destin Triple-Forgé", tgt="Dalia la Collectionneuse"}, [25]={npc="Ventaari Vœu-Radieux", tgt="Ventaari Vœu-Radieux"}, [26]={hint="Parlez à Yala Veillevent dans le bosquet de Thendal."}, [27]={npc="Yala Veillevent", tgt="Yala Veillevent"}, [28]={npc="Yala Veillevent", tgt="Yala Veillevent"}, [29]={hint="Tuez 6 vents tourbillonnants et 7 convertis al'aketh dans le bosquet de Thendal."}, [30]={npc="Yala Veillevent", tgt="Yala Veillevent"}, [31]={npc="Yala Veillevent", tgt="Yala Veillevent"}, [32]={hint="Signalez la présence des Al'Aketh à Rorian le Cherchejour dans le bosquet de Thendal."}, [33]={npc="Ailee Cœur-Lointain", tgt="Rorian le Cherchejour"}, [34]={npc="Ailee Cœur-Lointain", tgt="Rorian le Cherchejour"}, [35]={hint="Parlez à Aetheen des Trombes dans le bosquet de Thendal."}, [36]={npc="Elatrell Frêleplume", tgt="Aetheen des Trombes"}, [37]={npc="Valreaa Venduval", tgt="Valreaa Venduval"}, [38]={npc="Elatrell Frêleplume", tgt="Aetheen des Trombes"}, [39]={hint="Récupérez 6 griffes d'urseras faméliques sur les urseras faméliques dans le bosquet de Thendal."}, [40]={hint="Tuez 8 charognards urseras et récupérez la tête d'Urs'anah, la mère de la tanière, dans le bosquet de Thendal."}, [41]={npc="Valreaa Venduval", tgt="Valreaa Venduval"}, [42]={npc="Elatrell Frêleplume", tgt="Aetheen des Trombes"}, [43]={npc="Elatrell Frêleplume", tgt="Aetheen des Trombes"}, [44]={npc="Elatrell Frêleplume", tgt="Aetheen des Trombes"}, [45]={npc="Hanaa Ventenuit", tgt="Hanaa Ventenuit", tag="Facultatif"}, [46]={hint="Tuez 6 brutes al'aketh, 4 néophytes al'aketh et Malduko Fracasse-nuage dans le bosquet de Thendal.", tag="Facultatif"}, [47]={npc="Hanaa Ventenuit", tgt="Hanaa Ventenuit", tag="Facultatif"}, [48]={text="Shen'dar, hippogriffes et bandits"}, [49]={hint="Présentez-vous à la connétable Aonda à Shen'dar."}, [50]={npc="Connétable Aonda", tgt="Connétable Aonda"}, [51]={hint="Parlez à Raan Aile-sauvage près de Shen'dar."}, [52]={npc="Raan Aile-sauvage", tgt="Raan Aile-sauvage"}, [53]={text="liez votre pierre de foyer avec Coriella Calmebrise dans Shen'dar (43.01, 43.23)."}, [54]={npc="Connétable Aonda", tgt="Connétable Aond