    [826] = {n="Zalazane", d="Battre Zalazane.\nTuer 8 Trolls vaudou et 8 Trolls maléficiés.\nApporter la Tête de Zalazane à Gadrin.", tgo={{"Troll maléficié"}, {"Troll vaudou"}, {"Zalazane"}}},
    [827] = {n="Rocher du crâne", d="Prendre les Colliers brûlants des sectateurs au Rocher du crâne.\nLes apporter à Margoz à son camp.", tgo={{"Nervi de la Lame ardente", "Néophyte de la Lame ardente", "Fanatique de la Lame ardente"}}},
    [828] = {n="Margoz", d="Parler à Margoz."},
    [829] = {n="Neeru Fireblade", d="Apporter un Spécimen de collier à Neeru Fireblade à Orgrimmar."},
    [830] = {n="Les ordres de l'amiral", d="Apporter les Ordres de l'amiral Proudmoore à Gar'Thok de Tranchecolline."},
    [831] = {n="Les ordres de l'amiral", d="Porter les Ordres de l'amiral Proudmoore à Nazgrel, dans les appartements de Thrall à Orgrimmar."},
    [833] = {n="Cimetière sacré", d="Le Gardien du savoir Raintotem veut que vous tuiez 8 Intrus Dos-hirsute aux Rochers rouges.", tgo={{"Intrus Dos-hirsute"}}},
    [834] = {n="Des vents dans le désert", d="Retrouver 5 Sacs de marchandises et les rendre à Rezlak près d'Orgrimmar.", objs={"Sac de ravitaillement dérobé"}},
    [835] = {n="Des lignes sécurisées", d="Tuer 12 Terrevent farouches et 8 Sorcières des tempêtes Terrevent pour Rezlak près du Ravin asséché.", tgo={{"Terrevent sauvage"}, {"Sorcière des tempêtes Terrevent"}}},
    [837] = {n="Empiètement", d="Tuer 4 hurans Tranchecrin, 4 Eclaireurs Tranchecrin, 4 Lève-poussière Tranchecrin et 4 Gardes de guerre Tranchecrin pour Gar'Thok de Tranchecolline.", tgo={{"Huran Tranchecrin"}, {"Eclaireur Tranchecrin"}, {"Lève-poussière Tranchecrin"}, {"Garde de guerre Tranchecrin"}}},
    [838] = {n="Scholomance", d="Parler au Pharmacien Dithers à la Barricade, dans les Maleterres de l'ouest."},
    [840] = {n="Sous les drapeaux de la Horde", d="Suivre la route de l'ouest, celle qui part de Tranchecolline, et qui arrive aux Tarides par un pont.\nS'arrêter à l'avant-poste orc sur le pont.\nDonner votre lettre de recrutement à Kargal Battlescar aux Tarides."},
    [842] = {n="Conscription à la Croisée", d="Suivre la route à l'ouest à partir du Poste de garde extérieur de Kargal.\nA l'intersection en T, tourner à gauche et suivre la route vers le sud.\nTrouver Sergra Darkthorn où les routes se croisent à l'intérieur de la Croisée."},
    [843] = {n="La réclamation de Gann", d="Gann Stonespire veut que vous tuiez 15 Excavateurs de Bael'dun et 5 Surveillants de Bael'dun.\nApporter le Journal de Khazgorm à Gann Stonespire.", tgo={{"Excavateur de Bael'dun"}, {"Contremaître de Bael'dun"}, {"Prospecteur Khazgorm"}}},
    [844] = {n="La menace des trotteurs des plaines", d="Collecter 7 Becs de trotteurs des plaines et les apporter à Sergra Darkthorn à la Croisée.", tgo={{"Grand trotteur des plaines", "Trotteur des plaines hargneux", "Trotteur des plaines fugitif"}}},
    [845] = {n="Les zhévras", d="Tuer des Messagers zhévras et apporter 4 Sabots de zhévra à Sergra Darkthorn à la Croisée.", tgo={{"Messager zhévra", "Etalon zhévra", "Coursier zhévra"}}},
    [847] = {n="La ruse du raptor", d="Parler à Tor'gan."},
    [848] = {n="Spores fongiques", d="Apporter 4 Spores fongiques à l'Apothicaire Helbrim à la Croisée.", objs={"Champignon chargé"}},
    [850] = {n="Les chefs des Kolkar", d="Apporter la Tête de Barak à Regthar Deathgate, à l'ouest de la Croisée.", tgo={{"Barak Kodobane"}}},
    [851] = {n="Verog le Derviche", d="Apporter la Tête de Verog à Regthar Deathgate, à l'ouest de la Croisée.", tgo={{"Verog le Derviche"}}},
    [852] = {n="Hezrul Marque-de-sang", d="Apporter la Tête d'Hezrul à Regthar Deathgate, à l'ouest de la Croisée.", tgo={{"Hezrul Marque-de-sang"}}},
    [853] = {n="Apothicaire Zamah", d="Apporter les Spores fondues à l'Apothicaire Zamah à Thunder Bluff, avant que la limite de temps ne soit dépassée."},
    [854] = {n="Un voyage à la Croisée", d="Parler à Thork, à la Croisée des Tarides."},
    [855] = {n="Les bracelets de centaures", d="Apporter 15 Bracelets de centaures à Regthar Deathgate, à l'ouest de la Croisée.", tgo={{"Querelleur kolkar", "Légion-tempête kolkar", "Coursier kolkar"}}},
    [858] = {n="Contact", d="Récupérer la Clé de contact et l'apporter à Wizzlecrank.", tgo={{"Superviseur Lugwizzle"}}},
    [860] = {n="Sergra Darkthorn", d="Parler à Sergra Darkthorn, à la Croisée."},
    [861] = {n="La voie du chasseur", d="Apporter 4 Griffes de Rôdeurs des basses plaines à Melor Stonehoof à Thunder Bluff.", tgo={{"Rôdeur des basses plaines"}}},
    [863] = {n="La fuite", d="Protéger Wizzlecrank et le Déchiqueteur gobelin volé jusqu'à Sputtervalve à Ratchet."},
    [865] = {n="Les cornes de raptors", d="Collecter 5 Cornes de raptors intactes prises sur des Faucheurs solécaille, et les apporter à Mebok Mizzyrix à Ratchet.", tgo={{"Faucheur solécaille", "Ishamuhale", "Takk le Bondisseur"}}},
    [867] = {n="Les harpies pillardes", d="Collecter 8 Griffes d'Ensorçaile.\nLes apporter à Darsok Swiftdagger à la Croisée.", tgo={{"Harpie Ensorçaile", "Volplume Ensorçaile", "Tueuse Ensorçaile"}}},
    [868] = {n="La chasse aux œufs", d="Apporter 12 Œufs de silithide et la Griffe d'excavation à Korran, à la Croisée.", objs={"Antre des silithides"}},
    [869] = {n="Les raptors voleurs", d="Apporter 12 Têtes de raptor à Gazrog, à la Croisée.", tgo={{"Flagellant solécaille", "Hurleur solécaille", "Faucheur solécaille"}}},
    [870] = {n="Les Bassins oubliés", d="Rendre compte de vos découvertes à Tonga Runetotem."},
    [871] = {n="Stopper les attaques des hurans", d="Dans la tribu Tranchecrin, tuer 8 Sourciers, 8 Tisseuses d'épines et 3 Chasseurs, puis retourner voir Thork.", tgo={{"Sourcier Tranchecrin"}, {"Tisseuse d'épines Tranchecrin"}, {"Chasseur Tranchecrin"}}},
    [872] = {n="La perturbation cesse", d="Tuer 8 Géomanciennes Tranchecrin, 8 Défenseurs Tranchecrin et Kreenig Grondegroin.\nPuis apporter la Défense de Kreenig Grondegroin à Thork à la Croisée.", tgo={{"Géomancienne Tranchecrin"}, {"Défenseur Tranchecrin"}, {"Kreenig Grondegroin"}}},
    [875] = {n="Lieutenants harpies", d="Rassembler 6 Anneaux de lieutenant harpie sur des Tueuses Ensorçaile et les apporter à Darsok Swiftdagger à la Croisée.", tgo={{"Tueuse Ensorçaile"}}},
    [876] = {n="Serena Plumesang", d="Tuer Serena Plumesang et apporter sa tête à Darsok Swiftdagger à la Croisée.", tgo={{"Serena Plumesang"}}},
    [877] = {n="L'oasis stagnante", d="Retourner voir Tonga Runetotem à la Croisée, après avoir enquêté à l'Oasis stagnante.", objs={"Fissure bouillonnante"}},
    [878] = {n="Tribus en guerre", d="Tuer 6 Sourciers Dos-hirsute, 12 Tisseurs d'épines Dos-hirsute et 12 Géomanciennes Dos-hirsute puis retourner auprès de Mangletooth au camp Taurajo dans les Tarides.", tgo={{"Sourcier Dos-hirsute"}, {"Tisseur d'épines Dos-hirsute"}, {"Géomancienne Dos-hirsute"}}},
    [879] = {n="Une trahison de l'intérieur", d="Tuer Nak, Kuz et Lok Plaie-des-orcs et apporter leurs crânes à Mangletooth au Camp Taurajo dans les Tarides.", tgo={{"Kuz"}, {"Nak"}, {"Lok Plaie-des-orcs"}}},
    [880] = {n="Source de vie", d="Apporter 8 Carapaces de Gueules d'acier altérées à Tonga Runetotem à la Croisée.", tgo={{"Gueule d'acier des oasis", "Oasis Snapjaw Hatchling"}}},
    [881] = {n="Echeyakee", d="Apporter la Peau d'Echeyakee à Sergra Darkthorn à la Croisée.", tgo={{"Echeyakee"}}},
    [882] = {n="Ishamuhale", d="Apporter le Croc d'Ishamuhale à Jorn au Camp Taurajo.", tgo={{"Ishamuhale"}}},
    [883] = {n="Lakota'mani", d="Apporter le Sabot de Lakota'mani à Jorn au Camp Taurajo."},
    [884] = {n="Owatanka", d="Apporter l'Epine caudale d'Owatanka à Jorn au Camp Taurajo."},
    [885] = {n="Washte Pawne", d="Apporter la Plume de Washte Pawne à Jorn Skyseer au Camp Taurajo."},
    [886] = {n="Les oasis des Tarides", d="Parler à Tonga Runetotem à la Croisée."},
    [887] = {n="Les flibustiers des Mers du sud", d="Tuer 12 Brigands et 6 Canonniers des Mers du Sud pour Gazlowe de Ratchet.", tgo={{"Brigand des Mers du sud"}, {"Canonnier des Mers du sud"}}},
    [888] = {n="Course à la lentille", d="Retrouver la Cargaison de bottes et la Lentille de télescope pour Gazlowe de Ratchet.", objs={"Marché de Drizzlik", "Fragile - Ne pas jeter"}},
    [890] = {n="La livraison perdue", d="Apporter le Grand Livre de Gazlowe au Maître des quais Dizzywig."},
    [891] = {n="Sous le feu de l'ennemi", d="Le capitaine Thalo'thas Brightsun de Ratchet veut que vous collectiez 10 Médailles de Theramore et que vous tuiez le Capitaine Fairmount, le Canonnier Whessan et le Canonnier Smythe.", tgo={{"Capitaine Fairmount"}, {"Canonnier Whessan"}, {"Canonnier Smythe"}, {"Soldat de marine de Theramore", "Protectrice de Theramore", "Capitaine Fairmount"}}},
    [892] = {n="La livraison perdue", d="Rapporter le Grand Livre de Gazlowe à Gazlowe à Ratchet."},
    [893] = {n="Des armes de choix", d="Apporter un Poignard de Tranchecrin, une Baguette Tranchecrin carbonisée et un Bouclier Tranchecrin à Tatternack Steelforge au camp Taurajo dans les Tarides.", tgo={{"Guide Tranchecrin", "Traqueur Tranchecrin"}, {"Prophète Tranchecrin"}, {"Frénétique Tranchecrin"}}},
    [894] = {n="Samophlange", d="Accéder à la Console de contrôle au Centre de recherches de la KapitalRisk."},
    [895] = {n="ON RECHERCHE : baron de Longrivage", d="Apporter la tête du baron de Longrivage à Gazlowe à Ratchet.", tgo={{"Baron de Longrivage"}}},
    [896] = {n="La bonne fortune d'un mineur pauvre", d="Prendre l'Emeraude œil-de-chat à l'un des Surveillants ou l'un des Massacreurs de la KapitalRisk pour le Maître des quais Dizzywig à Ratchet.", tgo={{"Massacreur de la KapitalRisk", "Surveillant de la KapitalRisk", "Chef Copperplug"}}},
    [897] = {n="Le Moissonneur", d="Apporter la Tête du Moissonneur à Jorn Skyseer."},
    [898] = {n="Hors du fort", d="Escorter en toute sécurité Gilthares Firebough jusqu'au capitaine Brightsun à Ratchet."},
    [899] = {n="Consumé par la haine", d="Apporter 60 Défenses de huran Dos-hirsute à Mankrik, à la Croisée.", tgo={{"Chasseur Dos-hirsute", "Sourcier Dos-hirsute", "Tisseur d'épines Dos-hirsute"}}},
    [900] = {n="Samophlange", d="Fermer la Valve de contrôle du carburant, la Valve de réglage et la Valve de contrôle principale, puis utiliser à nouveau la console de contrôle.", objs={"Valve de commande principale", "Valve de contrôle du carburant", "Valve de réglage"}},
    [901] = {n="Samophlange", d="Obtenir la Clé de la console de l'artisan Sniggles, puis l'utiliser sur la console de contrôle.", tgo={{"Artisan Sniggles"}}},
    [902] = {n="Samophlange", d="Rapporter le Samophlange à Sputtervalve à Ratchet."},
    [903] = {n="Les rôdeurs des Tarides", d="Collecter 7 Griffes de Rôdeur des savanes pour Sergra Darkthorn à la Croisée.", tgo={{"Rôdeur des savanes"}}},
    [905] = {n="Les Faucheurs furieux", d="Tuer des raptors solécaille et récupérer leurs plumes. Placer ces plumes dans les 3 nids de Faucheurs solécaille, puis retourner voir Sergra Darkthorn à la Croisée.", objs={"Nid de raptor bleu", "Nid de raptor jaune", "Nid de raptor rouge"}},
    [906] = {n="Une trahison de l'intérieur", d="Apporter le Crâne de Lok à Thork à la Croisée des Tarides."},
    [907] = {n="Les lézards-tonnerre enragés", d="Apporter 3 doses de Sang de lézard-tonnerre à Jorn Skyseer, à Camp Taurajo.", tgo={{"Orageux", "Tête-tonnerre", "Groin-tempête"}}},
    [913] = {n="Le cri du faucon-tonnerre", d="Trouver et tuer un faucon-tonnerre, et rapporter ses ailes à Jorn Skyseer, au Camp Taurajo.", tgo={{"Jeune faucon-tonnerre", "Grand faucon-tonnerre", "Faucon-tonnerre des nuages"}}},
    [914] = {n="Les druides du Croc", d="Apporter les Gemmes de Cobrahn, d'Anacondra, de Pythas et de Serpentis à Nara Wildmane à Thunder Bluff.", tgo={{"Seigneur Cobrahn", "Forme de serpent Cobrahn"}, {"Dame Anacondra"}, {"Seigneur Pythas"}, {"Seigneur Serpentis"}}, star={"Bâton au croissant", {"MAGE", "PRIEST", "WARLOCK", "DRUID", "SHAMAN"}}},
    [959] = {n="Fuite de porto aux docks", d="Le grutier Bigglefuzz de Ratchet veut que vous repreniez la Bouteille de porto vieille de 99 ans à Magglish le Dingue, qui se cache dans les Cavernes des lamentations.", tgo={{"Magglish le Dingue"}}},
    [962] = {n="Fleur de serpent", d="L'Apothicaire Zamah à Thunder Bluff veut que vous récoltiez 10 Fleurs de serpent.", objs={"Fleur de serpent"}},
    [964] = {n="Fragments de squelette", d="Apporter 15 Fragments de squelette au Pharmacien Dithers à la Barricade, dans les Maleterres de l'ouest.", tgo={{"Ecorcheur Squelette", "Ensorceleur Squelette", "Terreur Squelette"}}},
    [974] = {n="À la recherche de la source", d="Découvrir la zone la plus chaude de la crête de la Fournaise, pour Krakle, au cratère d'Un'Goro.\nQuand vous trouvez une zone de chaleur, cliquez avec le bouton droit de la souris sur le thermomètre afin de prendre la température. Continuez vos recherches jusqu'à avoir trouvé la zone la plus chaude.", objs={"Point chaud de la crête de la Fournaise"}},
    [977] = {n="Yéti ? Y es-tu ?", d="Collecter 2 Cornes de yéti en parfait état pour Umi Rumplesnicker, à Long-guet", tgo={{"Matriarche Chardon de glace", "Patriarche Chardon de glace"}}},
    [980] = {n="Les nouvelles sources", d="Se rendre au Berceau-de-l'Hiver et parler à Donova Snowden."},
    [992] = {n="Étude des eaux de Gadgetzan", d="Utiliser la Fiole de sourcier vide à la mare près du Guet de Tristesable. Une fois l'échantillon récolté, remettre la Fiole de sourcier pleine au grand géomètre Fizzledowser à Gadgetzan.", objs={"Mare du Guet de Tristesable"}},
    [1000] = {n="La nouvelle frontière", d="Parler à l'archidruide Hamuul Runetotem, sur la Cime des Anciens de Thunder Bluff. Evoquer l'appel du Cercle cénarien concernant l'exploration des frontières de Kalimdor."},
    [1013] = {n="Le Livre d'Ur", d="Apporter le \"Livre d'Ur\" au Gardien Bel'dugur à l'Apothicarium à Fossoyeuse.", objs={"Le Livre d'Ur"}},
    [1014] = {n="Arugal doit mourir", d="Tuer Arugal et apporter sa Tête à Dalar Dawnweaver au Sépulcre.", tgo={{"Archimage Arugal", "Arugal"}}},
    [1048] = {n="Au monastère écarlate", d="Tuer le grand inquisiteur Whitemane, le commandant Mograine de la Croisade, le champion Herod et le maître-chien Loksey, et retourner faire son rapport à Varimathras à Fossoyeuse.", tgo={{"Grand Inquisiteur Whitemane"}, {"Commandant écarlate Mograine"}, {"Herod"}, {"Maître-chien Loksey"}}},
    [1049] = {n="Compendium des Déchus", d="Trouver le « Compendium des Déchus » au Monastère dans les Clairières de Tirisfal et retourner voir le Sage Truthseeker à Thunder Bluff.", objs={"Compendium des Déchus"}},
    [1051] = {n="La vengeance de Vorrel", d="Rapporter l'anneau de mariage de Vorrel Sengutz à Monica Sengutz à Moulin-de-Tarren.", tgo={{"Nancy Vishas"}}},
    [1058] = {n="Magie de la forêt de Jin'Zil", d="Le sorcier-docteur Jin'Zil à Malaka'jin veut 5 doses de Sève des Serres-Rocheuses, 5 Moustaches crépusculaires, 30 Yeux de coursier et une Ecaille de dragon-faë.", tgo={{"Bête de sève"}, {"Coureur crépusculaire"}, {"Coursier à ramure", "Grand coursier"}, {"Dragon-faë", "Dragon-faë rusé", "Nal'taszar"}}},
    [1060] = {n="Lettre à Jin'Zil", d="Remettre la lettre de Darsok à Jin'Zil dans sa caverne des Serres-Rocheuses."},
    [1061] = {n="Les esprits des Serres-Rocheuses", d="Parler à Seereth Stonebreak dans les Serres-Rocheuses."},
    [1062] = {n="Les invasions gobelines", d="Tuer 15 Déboiseurs de la KapitalRisk, puis retourner auprès de Seereth Stonebreak à la frontière des Serres-Rocheuses et des Tarides.", tgo={{"Déboiseur de la KapitalRisk"}}},
    [1063] = {n="L'Ancienne", d="Parler à Magatha à Thunder Bluff."},
    [1064] = {n="L'aide des Réprouvés", d="Parler à l'Apothicaire Zamah aux Bassins de la vision."},
    [1065] = {n="Un voyage vers Moulin-de-Tarren", d="Apporter la Note de Zamah à l'Apothicaire Lydon à Moulin-de-Tarren."},
    [1066] = {n="Le sang des innocents", d="Apporter 5 Fioles de Sang d'innocent à l'apothicaire Lydon à Moulin-de-Tarren.", tgo={{"Mage de l'ombre du Syndicat"}}},
    [1067] = {n="Le retour à Thunder Bluff", d="Apporter la Toxine de Lydon à l'Apothicaire Zamah à Thunder Bluff."},
    [1068] = {n="Les machines à déchiqueter", d="Détruire les Déchiqueteurs XT4 et XT9, puis retourner voir Seereth Stonebreak à la frontière entre les Serres-Rocheuses et les Tarides.", tgo={{"XT:4"}, {"XT:9"}}},
    [1069] = {n="Omelette à la mousse profonde", d="Apporter 15 Œufs des mousses profondes à Mebok Mizzyrix à Ratchet.", objs={"Oeufs de Mousse profonde"}},
    [1087] = {n="L'héritage de Cénarius", d="Tuer 4 Fils de Cénarius, 4 Filles de Cénarius et 4 Botanistes cénariens pour Braelyn Firehand, près de la retraite de Roche-Soleil.", tgo={{"Fils de Cénarius"}, {"Fille de Cénarius"}, {"Botaniste cénarien"}}},
    [1088] = {n="Ordanus", d="Apporter la Tête d'Ordanus à Braelyn Firehand, près de la Retraite de Roche-Soleil.", tgo={{"Gardien Ordanus"}}},
    [1089] = {n="L'Antre", d="Aller dans l'Antre, sur le Pic des Serres-Rocheuses. En utilisant la Clé du gardien, obtenir les objets cachés des druides. Utiliser ces objets pour ouvrir le Trésor de l'Antre des Serres.", objs={"Cache des Dormants", "Cache des druides", "Cache des saisons"}},
    [1093] = {n="Super-Découpeur 6000", d="Trouver le Plan du Super-Découpeur 6000 pour Ziz Fizziks dans les Serres-Rocheuses.", tgo={{"Opérateur de la KapitalRisk"}}},
    [1094] = {n="D'autres instructions", d="Remettre l'Enveloppe scellée à Sputtervalve dans les Tarides."},
    [1095] = {n="D'autres instructions", d="Apporter les nouveaux ordres à Ziz Fizziks dans les Serres-Rocheuses."},
    [1096] = {n="Gerenzo Wrenchwhistle", d="Apporter le Bras mécanique de Gerenzo Wrenchwhistle à Ziz Fizziks dans les Serres-Rocheuses.", tgo={{"Gerenzo Wrenchwhistle"}}},
    [1098] = {n="Des Traqueurs noirs à Ombrecroc", d="Trouver les Traqueurs noirs Adamant et Vincent."},
    [1102] = {n="Un destin funeste", d="Apporter le Cœur de Trancheflanc à Stonespire le Vieil, à Thunder Bluff.", tgo={{"Charlga Trancheflanc"}}},
    [1104] = {n="Le venin acide des salines", d="Apportez 6 doses de Venin de scorpide acide à Fizzle Brassbolts, dans les Salines.", tgo={{"Scorpide terrifiant", "Scorpide ravageur", "Dardeur"}}},
    [1105] = {n="Les carapaces durcies", d="Apporter 9 Carapaces de tortue durcies à Wizzle Brassbolts dans les Salines.", tgo={{"Tortue nacrétoile", "Mordeuse nacrétoile", "Tortue fouisseuse nacrétoile"}}},
    [1106] = {n="Martek l'Exilé", d="Apporter la Lettre de Fizzle à Martek l'Exilé dans les Terres ingrates."},
    [1108] = {n="Indurium", d="Apporter 10 Flocons d'indurium à Martek l'Exilé dans les Terres ingrates.", tgo={{"Cogneur Cavepierre", "Chaman Cavepierre", "Briseur d'os Cavepierre"}}},
    [1109] = {n="Corvée de guano", d="Apporter 1 tas de Guano du kraal au Maître Apothicaire Faranell à Fossoyeuse.", tgo={{"Chauve-souris du kraal", "Grande chauve-souris du kraal", "Chasseur aveugle"}}},
    [1110] = {n="Pièces de chariot explosif", d="Apporter 30 Pièces de Chariot explosif à Kravel Koalbeard des Salines.", objs={"Décombres de chariot explosif"}},
    [1111] = {n="Maître des quais Dizzywig", d="Apporter la Commande de Kravel au Maître des quais Dizzywig à Ratchet."},
    [1113] = {n="Des cœurs zélés", d="Le maître apothicaire Faranell, à Fossoyeuse, veut 20 Cœurs zélés.", tgo={{"Maître-chien Loksey", "Herod", "Commandant écarlate Mograine"}}},
    [1116] = {n="De la Poussière de rêve dans les marécages", d="Apporter 10 Grains de Poussière de rêve à Krazek à Baie-du-Butin. La Poussière de rêve se récupère sur les dragonnets du marais des Chagrins.", tgo={{"Jeune dragonnet", "Dragonnet rêveur", "Wyrmide vert"}}},
    [1123] = {n="Rabine Saturna", d="Parler à Rabine Saturna, au village de Havrenuit, à Reflet-de-Lune. Reflet-de-Lune se trouve entre Gangrebois et le Berceau-de-l'Hiver. Le chemin qui y mène traverse le Repaire des Grumegueules."},
    [1124] = {n="La dévastation", d="Parler à Layo Starstrike, à proximité du Repos des vaillants de Silithus, et lui montrer la Lettre de Rabine."},
    [1125] = {n="Les esprits de Sudevent", d="Libérer l'esprit de 8 Druides torturés et de 8 Sentinelles torturées, dans le village de Sudevent, puis revenir voir Layo Starstrike, au cimetière du Repos des Vaillants de Silithus.", tgo={{"Druide torturé"}, {"Sentinelle torturée"}}},
