    [2283] = {n="Réparer le Collier", d="Rechercher dans l'excavation d'Uldaman un Collier de prix et le rapporter à Dran Droffers à Orgrimmar. Ce Collier peut être endommagé.", tgo={{"Géomètre Ombreforge", "Forban Ombreforge", "Terrassier Ombreforge"}}},
    [2284] = {n="Réparer le Collier, deuxième prise", d="Trouver, dans les profondeurs d'Uldaman, des indices sur la localisation des Gemmes."},
    [2318] = {n="La Traduction du Journal", d="Trouver quelqu'un qui puisse traduire le journal du paladin. L'endroit le plus proche est Kargath, dans les Terres ingrates."},
    [2338] = {n="La Traduction du Journal", d="Laisser Jarkal emprunter le Collier en échange de la traduction du Journal."},
    [2339] = {n="Trouver les Gemmes et la Source d'énergie", d="Récupérer, dans Uldaman, les trois gemmes et une source d'énergie pour le collier, puis les rapporter à Jarkal Mossmeld, à Kargath. Jarkal pense que vous pouvez trouver une source d'énergie sur la machine la plus puissante d'Uldaman.\nC'est dans le journal, vous savez...\n* Le rubis a été caché dans une zone barricadée des Ombreforge.\n* La topaze a été dissimulée dans une urne, dans l'une des zones trogg, pas très loin de nains de Alliance.\n* Le saphir est possession du chef trogg, Grimlok.", tgo={{}, {"Grimlok"}, {}, {"Archaedas"}}, objs={"Cachette d'Ombreforge", "Urne ostentatoire"}},
    [2340] = {n="Livrer les Gemmes", d="Apporter Les gemmes et le collier récupérés à Dran Droffers, à Orgrimmar."},
    [2341] = {n="Réparer le collier, troisième prise", d="Rendre visite à Jarkal Mossmeld à Kargath pour constater (ou non) son succès."},
    [2342] = {n="Des Trésors à recouvrer", d="Rapporter à Patrick Garrett, à Fossoyeuse, son Trésor de famille, qui se trouve dans le Coffre de famille dans le Hall commun sud d'Uldaman.", objs={"Coffre de la famille Garrett"}},
    [2378] = {n="Trouver la Main brisée", d="Voyager vers Orgrimmar pour y parler à Shenthul, dans la Faille de l'ombre."},
    [2379] = {n="Zando'zan", d="Parler à Zando'zan à la Faille de l'ombre."},
    [2381] = {n="Piller les Pilleurs", d="Rapporter le Trésor des Mers du sud à Wrenix le Misérable à Ratchet. Ne pas oublier d'obtenir un B.G.A.C. et des Outils de voleur de l'Appareil bidulotronique de Wreni. Ces deux éléments sont nécessaires pour accomplir la mission.\nEn cas d'attaque par des perroquets particulièrement hostiles, utiliser le B.G.A.C.!", tgo={{"Polly"}}},
    [2382] = {n="Wrenix de Ratchet", d="Aller jusqu'à Ratchet pour voir Wrenix le Misérable."},
    [2383] = {n="Parchemin simple", d="Lire le Simple parchemin, et parler à Frang, dans la Vallée des épreuves."},
    [2418] = {n="Les pierres de puissance", d="Apporter 8 Pierres de puissance Dentrium et 8 Pierres de puissance An'Alleum à Rigglefuzz dans les Terres ingrates.", tgo={{"Géomètre Ombreforge", "Forban Ombreforge", "Terrassier Ombreforge"}, {"Géomètre Ombreforge", "Forban Ombreforge", "Terrassier Ombreforge"}}},
    [2458] = {n="Sous le couvert de la nuit", d="Aller à la tour de la KapitalRisk, au nord de la Videfange, et contacter l'agent secret de la Main brisée, le sous-chef Fizzule.\nUne fois la tour en vue, utiliser le lance-fusées pour se signaler au sous-chef Fizzule. Tirer DEUX fusées, puis s'approcher du sous-chef Fizzule et faire le Salut brisé (/salut).\nRespecter l'ordre de ces actions, car Fizzule attaque et tue toute personne qu'il ne peut pas identifier."},
    [2460] = {n="Le Salut brisé", d="Faire le Salut brisé à Shenthul.", tgo={{"Shenthul"}}},
    [2478] = {n="Mission : possible mais non probable", d="Voler la Clé de la tour de Silixiz au contremaître Silixiz, puis tuer deux Pantins mutants de la KapitalRisk, deux Patrouilleurs de la KapitalRisk, et deux Sentinelles de la KapitalRisk.\nAssassiner le grand contremaître Gallywix et prendre sa tête. Ouvrir le coffre de Gallywix et y voler la Mixture altérée de Zanzil. Apporter la Mixture et la tête de Gallywix à Shenthul à Orgrimmar, et attendre de nouvelles instructions.", tgo={{"Pantin muté de la KapitalRisk"}, {"Sentinelle de la KapitalRisk"}, {"Patrouilleur de la KapitalRisk"}, {"Grand contremaître Puzik Gallywix"}, {"Contremaître Silixiz"}, {}}, objs={"Coffret de Gallywix"}},
    [2479] = {n="L'aide d'Hinott", d="Aller à Moulin-de-Tarren dans les contreforts d'Hillsbrad et livrer l'Échantillon de la mixture de Zanzil à Serge Hinott.\nPour rejoindre Moulin-de-Tarren, prenez le zeppelin à Fossoyeuse et suivez la route du sud, à travers les Pins argentés et vers Hillsbrad. Suivez les panneaux !"},
    [2480] = {n="L'aide d'Hinott", d="Attendre Serge Hinott pour achever le remède."},
    [2521] = {n="Au service de Kum'isha", d="Si vous trouvez une sphère de draenéthyste sans défaut au hasard des voyages dans les Terres foudroyées, apportez-la à Kum'isha le Collecteur.\nCette gemme, l'une des plus rares de tout Azeroth, peut être détenue par n'importe qui dans le pays.\nUne récompense sera donnée pour chaque sphère de draenéthyste sans défaut trouvée et rapportée.", tgo={{"Ogre Cognepeur", "Ogre-mage Cognepeur", "Brute Cognepeur"}}},
