    [3062] = {n="Coeur noir", d="Rapporter le Coeur noir d'Edana Serrehaine à Talo Thornhoof, à Camp Mojache.", tgo={{"Edana Hatetalon"}}},
    [3063] = {n="Se venger des Ruissenord", d="Tuer 4 Harpies Ruissenord, 4 Volplumes Ruissenord, 4 Imploratrices célestes Ruissenord et 4 Pourfendeuses Ruissenord pour Talo Thornhoof.", tgo={{"Harpie Ruissenord"}, {"Volplume Ruissenord"}, {"Pourfendeuse Ruissenord"}, {"Imploratrice céleste Ruissenord"}}},
    [3065] = {n="Tablette simple", d="Lire la Tablette simple, et parler à Frang, dans la Vallée des épreuves."},
    [3082] = {n="Tablette gravée", d="Parler à Jen'shan dans la Vallée des épreuves"},
    [3083] = {n="Tablette codée", d="Lire la Tablette codée, et parler à Rwag, dans la Vallée des épreuves."},
