    [3086] = {n="Tablette glyphée", d="Lire la Tablette glyphée, et parler à Mai'ah, près de l'entrée de l'Antre, dans la Vallée des épreuves."},
    [3087] = {n="Parchemin gravé", d="Lire le Parchemin gravé, et parler à Jen'shan, dans la Vallée des épreuves."},
    [3088] = {n="Parchemin codé", d="Lire le Parchemin codé, et parler à Rwag, dans la Vallée des épreuves."},
