    [3090] = {n="Parchemin contaminé", d="Lire le Parchemin contaminé, et parler à Nartok, à l'intérieur de l'Antre, dans la Vallée des épreuves."},
    [3091] = {n="Note simple", d="Lire la Note simple, et parler à Harutt Thunderhorn, à Camp Narache."},
    [3092] = {n="Note gravée", d="Lire la Note gravée, et parler à Lanka Farshot, sur la Mesa de Nuage rouge."},
    [3093] = {n="Note runique", d="Lire la Note runique, et parler à Meela Dawnstrider, à Camp Narache."},
    [3094] = {n="Note verdoyante", d="Lire la Note verdoyante, et parler à Gart Mistrunner, à Camp Narache."},
    [3095] = {n="Parchemin simple", d="Lire le Parchemin simple, et parler à Dannal Stern, au Glas."},
    [3096] = {n="Parchemin codé", d="Lire le Parchemin codé, et parler à David Trias, au Glas."},
    [3097] = {n="Parchemin béni", d="Lire le Parchemin béni, et parler au sombre clerc Duesten, dans l'église du Glas."},
    [3098] = {n="Parchemin glyphé", d="Lire le Parchemin glyphé, et parler à Isabella, dans l'église du Glas."},
    [3099] = {n="Rouleau contaminé", d="Lire le Rouleau contaminé, et parler à Maximillion, au Glas."},
    [3121] = {n="Une Requête étrange", d="Porter la tête réduite à Neeru Fireblade à Orgrimmar."},
    [3122] = {n="Retourner voir le sorcier-docteur Uzer'i", d="Livrer une Poche d'herbes de Neeru au Sorcier docteur Uzer'i, en Feralas."},
    [3123] = {n="Test du récipient", d="Partez pour les Hinterlands et localisez les Indomptables. Tuez-en 10, puis utilisez le Récipient de muisek pour faire rétrécir et capturer les Indomptables vaincus.\nRamenez 10 Indomptables miniaturisés et le Récipient d'Indomptables miniaturisés au sorcier-docteur Uzer'i, en Feralas.", tgo={{"Chouettard vicieux", "Chouettard primitif", "Chouettard sauvage"}}},
    [3124] = {n="Hippogryphe miniaturisé", d="Tuer 10 Hippogryphes Aigreplume de n'importe quel type, puis utiliser le Vaisseau de muisek pour les faire rétrécir et les capturer.", tgo={{"Hippogryphe Aigreplume", "Cerf ailé Aigreplume", "Tempêtueux Aigreplume"}}},
    [3125] = {n="Dragon féérique miniaturisé", d="Tuer 8 Fées fléchetteuses ou Petits dragons féeriques. Utiliser le Vaisseau de muisek pour faire rétrécir et capturer les dragons féeriques vaincus.", tgo={{"Petit dragon féerique", "Fée fléchetteuse"}}},
    [3126] = {n="Tréant miniaturisé", d="Tuer 3 Marcheurs des bois errants. Utiliser le Vaisseau de muisek pour faire rétrécir et pour capturer les tréants vaincus.", tgo={{"Marcheur des bois errant"}}},
    [3127] = {n="Géant des montagnes miniaturisé", d="Tuer 7 Marcheurs des terres ou Géants des falaises. Utiliser le Récipient de muisek pour faire rétrécir et pour capturer les Géants des montagnes.", tgo={{"Marcheur des terres", "Géant des falaises", "Marcheur des terres zappé"}}},
    [3128] = {n="Matériaux Naturels", d="Apporter 2 Bûches fendues, 6 Minerais incrustés, 20 Morceaux de tendons résistants et 40 Fragments métalliques au sorcier-docteur Uzer'i au Camp Mojache.", tgo={{"Marcheur des bois errant"}, {"Petit dragon féerique", "Fée fléchetteuse", "Marcheur des terres"}, {"Chouettard vicieux", "Chouettard primitif", "Chouettard sauvage"}, {"Chouettard vicieux", "Chouettard primitif", "Chouettard sauvage"}}},
    [3129] = {n="Armes de l'Esprit", d="Le sorcier-docteur Uzer'i veut que vous patientez tandis qu'il prépare les armes."},
    [3161] = {n="Gahz'ridian", d="Marvon Rivetseeker à Tanaris veut que vous collectiez 30 Ornements Gahz'ridian.", objs={"Gahz'ridian"}},
    [3221] = {n="Parler à Renferrel", d="Parler à l'apothicaire Renferrel au Sépulcre."},
    [3261] = {n="Jorn Skyseer", d="Parler à Jorn Skyseer, à Camp Taurajo."},
    [3281] = {n="Argent volé", d="Rapportez l'Argent volé à Gazrog à la Croisée.", objs={"Argent volé"}},
    [3301] = {n="Mura Runetotem", d="Parler à Mura Runetotem au Sépulcre."},
    [3341] = {n="L'anéantissement", d="Andrew Brownell veut que vous tuiez Amnennar le Porte-froid et que vous lui rameniez son crâne.", tgo={{"Amnennar le Porte-froid"}}},
    [3362] = {n="La vallée des Chardonniers", d="Tran'rek, à Gadgetzan, voudrait que vous tuiez 8 Chardonniers noueux et 8 Chardonniers taille-racines.", tgo={{"Chardonnier noueux"}, {"Chardonnier taille-racine"}}},
    [3369] = {n="Au coeur des cauchemars", d="Apporter l'Eclat de cauchemar à Hamuul Runetotem à la Cime des Anciens."},
    [3373] = {n="L'Essence d'Eranikus", d="Placer l'Essence d'Eranikus dans le Réceptacle d'essence situé dans son antre dans le Temple englouti."},
    [3376] = {n="La fin de Brochaigu !", d="Apporter la Tête du chef Brochaigu Mantépine à Brave Windfeather à la mesa de Nuage rouge.", tgo={{"Chef Brochaigu Mantépine"}}},
    [3380] = {n="Le Temple englouti", d="Trouver Marvon Rivetseeker à Tanaris."},
    [3441] = {n="Châtiment divin", d="Écouter le récit de Velarok Lamevent.", tgo={{"Velarok Lamevent"}}},
    [3442] = {n="La flamme parfaite", d="Réunir 4 Cœurs des flammes et 4 globes d'Huile de golem puis rapporter ces objets à Velarok Lamevent.", tgo={{"Elémentaire flamboyant", "Elémentaire infernal", "Elémentaire de magma"}, {"Golem de guerre", "Golem de guerre lourd", "Elémentaire de magma"}}},
    [3443] = {n="Forger le manche", d="Apporter 8 Dagues plaquées en thorium à Velarok Lamevent.", tgo={{"Géologue Sombrefer", "Forge-vapeur Sombrefer", "Esclave ouvrier"}}},
    [3444] = {n="Le Cercle de pierres", d="Récupérer le Cercle de pierres à l'Atelier de Marvon Rivetseeker à Ratchet.", objs={"Coffre de Marvon"}},
    [3446] = {n="Dans les profondeurs", d="Trouver l'Autel d'Hakkar dans le Temple englouti du marais des Chagrins."},
    [3447] = {n="Le secret du cercle", d="Voyager jusqu'au Temple englouti et découvrir le secret du cercle de statues."},
    [3452] = {n="L'enveloppe de la flamme", d="Trouver et apporter un Symbole de Ragnaros à Velarok Lamevent.", tgo={{"Chaman noir du crépuscule", "Gardefeu du crépuscule", "Géomancien du crépuscule"}}},
    [3453] = {n="La Torche de vindicte", d="Attendre que Velarok Lamevent termine la Torche de vindicte.", tgo={{"Velarok Lamevent"}}},
    [3454] = {n="La Torche de vindicte", d="Prendre la Torche de vindicte."},
    [3462] = {n="L'écuyer Maltrake", d="Parler à l'écuyer Maltrake."},
    [3463] = {n="Allumer le feu !", d="Mettre le feu aux Tours de garde nord, sud, est, et ouest en utilisant la Torche de vindicte à l'intérieur de chaque tour.", objs={"Brasero de sentinelle"}},
    [3481] = {n="Bibelots...", d="Ouvrir le coffre."},
    [3501] = {n="Tout se compte en grandes quantités", d="Apporter des Fragments imparfaits de draenéthyste à Kum'isha et toucher une récompense pour chaque fragment rapporté.", tgo={{"Ogre Cognepeur", "Ogre-mage Cognepeur", "Brute Cognepeur"}}},
    [3504] = {n="Trahison", d="Apporter la Lettre Scellée à Ag'tor Bloodfist dans Azshara."},
    [3505] = {n="Trahison", d="Tuer 10 Vengeurs elfes de sang et 10 Géomètres elfes de sang avant de rechercher le campement du magus Rimtori. Une fois le camp trouvé, chercher quelque chose d'important pour elle et qui peut être utilisé pour l'obliger à se battre.", tgo={{"Vengeur elfe de sang"}, {"Géomètre elfe de sang"}}},
    [3517] = {n="L'art du vol", d="Trouvez la tablette de Beth'Amara, la tablette de Jin'yael, la tablette de Markri et la tablette de Sael'hai puis retournez voir Jediga à Valormok.", objs={"Tablette de Beth'Amara", "Tablette de Jin'yael", "Tablette de Markri", "Tablette de Sael'hai"}},
    [3518] = {n="Une livraison pour Magatha Totem-Sinistre", d="Apportez la tablette de Beth'Amara à Magatha Totem-Sinistre aux Pitons-du-Tonnerre."},
    [3520] = {n="Esprits de Hurleurs", d="Capturer l'Esprit de 3 Hurleurs en Feralas, puis retourner voir Yeh'kinya à Port Gentepression.", tgo={{"Esprit d'Hurleur"}}},
    [3523] = {n="Le Fléau des Souilles", d="Pour aider Belnistrasz, lui parler de nouveau et lui rendre la Pierre de voeu qu'il vous avait donnée."},
    [3525] = {n="L'extinction de l'idole", d="Escorter Belnistrasz jusqu'à l'Idole des hurans dans les Souilles de Tranchebauge.\nProtéger Belnistrasz tandis qu'il exécute le rituel pour arrêter l'idole."},
    [3527] = {n="La prophétie de Mosh'aru", d="Apporter les Première et Deuxième tablettes Mosh'Aru à Yeh'kinya, à Tanaris.", tgo={{"Theka le Martyr", "Theka le Martyr changeforme"}, {"Hydromancienne Velratha"}}},
    [3528] = {n="Le dieu Hakkar", d="Apporter l'Oeuf Rempli d'Hakkar à Yeh'kinya dans Tanaris."},
    [3541] = {n="Livraison pour Jes'rimon", d="Apporter la Tablette de Jin'yael à Jes'rimon dans Orgrimmar."},
    [3542] = {n="Livraison à Andron Gant", d="Apporter la Tablette de Markri à Andron Gant à Fossoyeuse."},
    [3601] = {n="Kim'jael évidemment !", d="Fouiller le Camp de base thalassien pour trouver la Boussole, la Lunette, le Poulet farci et le Wizzlegoober de Kim'Jael, puis les lui rapporter à Azshara.", objs={"Equipement de Kim'jael"}},
    [3631] = {n="Invoquer un Palefroi corrompu", d="Parler à Strahad Farsan, dans les Tarides."},
    [3783] = {n="Yéti ? Y es-tu ?", d="Collecter 10 Fourrures épaisses de yéti pour Umi Rumplesnicker, à Long-guet.", tgo={{"Chardon de glace insoumis", "Yéti Chardon de glace"}}},
    [3801] = {n="Héritage Sombrefer", d="Parler à Franclorn Forgewright si obtenir une clé de la Cité majeure vous intéresse."},
    [3802] = {n="Héritage Sombrefer", d="Tuer Fineous Darkvire et récupérer le grand marteau, Souillefer. Apporter Souillefer au sanctuaire de Thaurissan et le placer sur la statue de Franclorn Forgewright.", tgo={{"Fineous Darkvire"}}},
    [3821] = {n="Le Rocher des Cognepeurs", d="S'aventurer dans les Steppes ardentes et découvrir ce qu'il est advenu de Sha'ni Proudtusk."},
    [3822] = {n="Krom'Grul", d="Récupérer l'Anneau de nez de Sha'ni sur Krom'Grul, et le rapporter à Thal'trak, à Kargath. Fouiller les différentes grottes et mines du Rocher des Cognepeurs.", tgo={{"Krom'Grul"}}},
    [3844] = {n="C'est un Secret pour tout le monde", d="Rechercher dans l'étang un indice sur l'identité du propriétaire du radeau brisé."},
    [3845] = {n="C'est un secret pour tout le monde", d="Examiner les objets du paquet et les apporter à leur propriétaire."},
    [3881] = {n="Le sauvetage de l'expédition", d="Apporter une Caisse de nourriture et de l'Equipement de recherche à Williden Marshal dans le Cratère d'Un'Goro.", objs={"Caisse de nourriture", "Equipement de recherches"}},
    [3882] = {n="Faites rouler les os", d="Apporter 8 Os de dinosaure à Spark Nilminer, au cratère d'Un'Goro.", tgo={{"Stégodon", "Stégodon cuirassé", "Stégodon à pointes"}}},
    [3884] = {n="Le journal de Williden", d="Rapporter le Journal à Williden Marshal quelque part dans le Cratère d'Un'Goro."},
    [3901] = {n="Faites cliqueter les thorax !", d="Tuez 12 Squelettes Cliquethorax, puis retournez voir le prêtre des ombres Sarvis au Glas.", tgo={{"Squelette Cliquethorax"}}},
    [3902] = {n="La chasse aux trésors", d="Fouiller Le Glas et ses alentours pour trouver 6 pièces de fournitures de récupération, et les ramener au Garde noir Saltain.", objs={"Boîtes d'équipement"}},
    [3906] = {n="Discordance des flammes", d="Partir pour la carrière dans le mont Blackrock et tuer le Grand maître Pyron. Retourner voir Thunderheart une fois votre mission accomplie.", tgo={{"Grand seigneur Pyron"}}},
    [3907] = {n="Discordance des flammes", d="Pénétrer dans les Profondeurs de Blackrock et traquer le Seigneur Incendius. Le tuer puis donner tous les renseignements que vous pouvez trouver à Thunderheart.", tgo={{"Seigneur Incendius"}, {"Seigneur Incendius"}}},
    [3908] = {n="C'est un Secret pour tout le monde", d="Apporter l'Epée de Linken à Donova Snowden dans le Berceau-de-l'Hiver."},
    [3909] = {n="L'élixir de Videre", d="Rechercher Gregan Brewspewer au nord de Feralas. Apprendre de lui comment vous pouvez acquérir l'élixir de Videre, puis retourner voir Donova Snowden, au Berceau-de-l'Hiver.", tgo={{"Gregan Brewspewer"}}},
    [3912] = {n="Rendez-vous à la tombe", d="Se rendre au cimetière au-dehors de Gadgetzan et boire l'élixir de Videre. Suivre le reste des instructions de Donova pour trouver Gaeriyan."},
    [3913] = {n="Une situation grave", d="Ressusciter, puis rechercher la pierre tombale que Gaeriyan vous a demandé de trouver."},
    [3914] = {n="L'épée de Linken", d="Remettre l'Epée excellente de Linken à Linken dans le cratère d'Un'Goro."},
    [3941] = {n="Un gnome dans le besoin", d="Trouver J.D. Collie dans la caverne du refuge des Marshal."},
    [3942] = {n="Les souvenirs de Linken", d="Trouver Eridan Bluewind dans le sud de Gangrebois."},
    [4021] = {n="La contre-attaque !", d="Apporter un Morceau de la bannière de Krom'zar à Regthar Deathgate, à l'ouest de la Croisée.", objs={"Bannière de Krom'zar"}},
    [4061] = {n="La révolte des machines", d="S'aventurer dans les Steppes ardentes et récupérer 10 Fragments d'élémentaires cassés pour la Hiérophante Theodora Mulvadania.\nTheodora vous a indiqué que les golems et les élémentaires étaient la source de ces fragments.", tgo={{"Grand élémentaire d'obsidienne", "Ravageur de guerre", "Ravageur défectueux"}}},
    [4062] = {n="La révolte des machines", d="Apporter l'Echantillon de fragment d'élémentaire à Lotwil Veriatus.\nTheodora vous a dit qu'il se trouvait au camp à l'est."},
    [4081] = {n="TUER A VUE : nains Sombrefer", d="Pénétrer dans les Profondeurs de Blackrock et tuer les vils agresseurs !\nLe chef de guerre Goretooth veut que vous tuiez 15 Gardes Ragenclumes, 10 Gardiens Ragenclumes et 5 Fantassins Ragenclumes. Retourner le voir une fois votre mission accomplie.", tgo={{"Garde Ragenclume"}, {"Gardien Ragenclume"}, {"Fantassin Ragenclume"}}},
    [4084] = {n="Coeur d'argent", d="Trouver 11 Griffes d'argent et 1 Cœur d'Arbrefer pour Eridan Bluewind à Gangrebois.", tgo={{"Ours de la griffe colérique", "Grizzly de la griffe colérique", "Mutilateur de la griffe colérique"}, {"Arbrefer errant", "Arbrefer marteleur"}}},
    [4102] = {n="Purifie Gangrebois", d="Apporter 15 Ambres de sang à Maybess Riverbreeze à Gangrebois.", tgo={{"Ecorcheur Crochebois", "Déchireur Crochebois", "Dessecus"}}},
    [4120] = {n="La force de la corruption", d="Talo Thornhoof, à Camp Mojache, dans Feralas, voudrait que vous tuiez 12 Grizzlis de la griffe colérique et 12 Ravageurs Gangrepatte, à Gangrebois.", tgo={{"Grizzly de la griffe colérique"}, {"Ravageur Gangrepatte"}}},
    [4123] = {n="Le Coeur de la montagne", d="Apporter le Cœur de la montagne à Maxwort Uberglint dans les Steppes ardentes.", objs={"Coeur de la montagne"}},
    [4134] = {n="La recette perdue de Thunderbrew", d="Apporter la Recette perdue de la Thunderbrew à Vivian Lagrave à Kargath.", tgo={{"Hurley Blackbreath", "Compère de Blackbreath"}}},
    [4136] = {n="Ribbly Screwspigot", d="Apporter la Tête de Ribbly à Yuka Screwspigot dans les Steppes ardentes.", tgo={{"Ribbly Screwspigot"}}},
    [4145] = {n="Larion et Muigin", d="Chasser 5 Flagellants Pétale-de-sang, 5 Batteurs Pétale-de-sang, 5 Ecorcheurs Pétale-de-sang et 5 Trappeurs Pétale-de-sang pour Larion au refuge des Marshal.", tgo={{"Flagellant Pétale-de-sang"}, {"Trappeur Pétale-de-sang"}, {"Ecorcheur Pétale-de-sang"}, {"Batteur Pétale-de-sang"}}},
    [4147] = {n="Atelier de Marvon", d="Se rendre à l'Atelier de Marvon Rivetseeker à Ratchet."},
    [4284] = {n="Cristaux de puissance", d="Récupérer 7 Cristaux de puissance de chaque couleur (rouge, bleu, jaune et vert). Les apporter à J.D. Collie au refuge des Marshal.", objs={"Cristal de puissance rouge", "Cristal de puissance jaune", "Cristal de puissance vert", "Cristal de puissance bleu"}},
    [4285] = {n="Le Pylône nord", d="Découvrir l'emplacement du Pylône de cristal nord dans le Cratère d'Un'Goro.", objs={"Pylône de cristal nord"}},
    [4287] = {n="Le Pylône est", d="Trouver l'emplacement du Pylône de cristal est dans le Cratère d'Un'Goro.", objs={"Pylône de cristal est"}},
    [4288] = {n="Le Pylône ouest", d="Découvrir l'emplacement du Pylône de cristal ouest.", objs={"Pylône de cristal ouest"}},
    [4289] = {n="Les gorilles d'Un'Goro", d="Apporter 2 Peaux de gorille d'Un'Goro, 2 Peaux de marteleur d'Un'Goro et 2 Peaux de foudroyeur d'Un'Goro à Torwa Pathfinder à l'entrée du cratère d'Un'Goro.", tgo={{"Gorille d'Un'Goro", "Gorille d'Un'Goro"}, {"Marteleur d'Un'Goro"}, {"Foudroyeur d'Un'Goro"}}},
    [4290] = {n="La nourriture de Lar'korwi", d="Trouver la dernière victime de Lar'korwi et voler un Morceau de carcasse d'un battrodon, puis retourner voir Torwa Pathfinder au Cratère d'Un'Goro.", objs={"Carcasse fraîche de battrodon"}},
    [4291] = {n="Un parfum pour Lar'korwi", d="Apporter 2 Glandes de phéromone de ravasaure à Torwa Pathfinder près de l'entrée du Cratère d'Un'Goro.", tgo={{"Compagne de Lar'korwi"}}},
    [4292] = {n="Un appât pour Lar'korwi", d="En utilisant le contenu de la Sacoche de Torwa, appeler Lar'korwi et le vaincre. Puis apporter la Tête de Lar'korwi à Torwa Pathfinder près de l'entrée du Cratère d'Un'Goro.", tgo={{"Lar'korwi"}}},
    [4296] = {n="Tablette des Sept", d="Apporter la Transcription de la tablette à Maxwort Uberglint dans les Steppes ardentes.", objs={"Tablette des Sept"}},
    [4300] = {n="Les armes aux lames d'os", d="Apporter 8 Griffes blanches de ravasaure à Jes'rimon à Orgrimmar.", tgo={{"Ravasaure", "Ravasaure coureur", "Ravasaure chasseur"}}},
    [4301] = {n="Le puissant U'cha", d="Apporter la Peau d'U'cha à Torwa Pathfinder à l'entrée du Cratère d'Un'Goro.", tgo={{"U'cha"}}},
    [4321] = {n="Ceci explique cela", d="Parler à J.D. Collie dans un moment."},
    [4324] = {n="Yuka Screwspigot", d="Parler à Yuka Screwspigot dans les Steppes ardentes."},
    [4402] = {n="Surprise aux pommes de cactus de Galgar", d="Apportez à Galgar 10 Pommes de cactus. Il vous a précisé qu'elles se trouvaient souvent à côté des cactus.", objs={"Pomme de cactus"}},
    [4449] = {n="Piégé !", d="Tuer 8 Géologues Sombrefer et rapporter 15 morceaux d'Etoffe de soie à la personne enfermée de les toilettes de la gorge des Vents brûlants.", tgo={{"Géologue Sombrefer"}, {}}, objs={"Granit d'Alterac", "Coffre en morceaux", "Coffre solide"}},
    [4489] = {n="Invoquer un Palefroi corrompu", d="Parler à Strahad Farsan, à Ratchet."},
    [4490] = {n="Invoquer un Palefroi corrompu", d="Parler à Strahad Farsan, à Ratchet pour apprendre à invoquer un Palefroi corrompu."},
    [4491] = {n="Un peu d'aide de mes amis", d="Conduire Ringo à Spraggle Frock, au refuge des Marshal.\nSi Ringo s'évanouit, utiliser la Gourde de Spraggle pour le réanimer."},
    [4492] = {n="Perdu !", d="Trouver Ringo sur la crête de la Fournaise."},
    [4494] = {n="La marche des silithides", d="Parler à l'alchimiste Pestlezugg à Gadgetzan."},
    [4496] = {n="Fiasco dans la jungle", d="Apporter une Glande olfactive Gorishi et 5 Echantillons d'Humus d'Un'Goro à l'alchimiste Pestlezugg, à Gadgetzan.", tgo={{"Guêpe Gorishi", "Ouvrier Gorishi", "Ravageur Gorishi"}, {}}, objs={"Tas de poussière d'Un'Goro"}},
    [4502] = {n="Activité volcanique", d="Collecter 9 Echantillons de cendre Un'Goro sur les Elémentaires de brûlure qui se trouvent autour du volcan, dans le Cratère d'Un'Goro, puis les apporter à Liv Rizzlefix, à Ratchet.", tgo={{"Elémentaire de brûlure", "Brasier vivant", "Blazerunner"}}},
    [4503] = {n="La machine volante de Shizzle", d="Apporter 8 Ecailles étoilées de dimeurtrodon et 8 Ecailles étoilées de pterreurdactyles à Shizzle, au refuge des Marshal.", tgo={{"Jeune dimeurtrodon", "Dimeurtrodon", "Ancien dimeurtrodon"}, {"Petit pterreurdactyle", "Pterreurdactyle", "Pterreurdactyle frénétique"}}},
    [4504] = {n="Ultra collant", d="Collecter 12 échantillons de Goudron ultra collant pour Tran'rek, à Gadgetzan.", tgo={{"Bête du goudron", "Rôdeur du goudron", "Seigneur du goudron"}}},
    [4505] = {n="Puits de la corruption", d="Collecter un échantillon d'eau corrompue dans le Puits de lune des satyres Jadefeu, puis le rapporter à Winna Hazzard, au Poste de la Vénéneuse.", objs={"Le Puits de lune corrompu"}},
    [4506] = {n="Sabres corrompus", d="Amener le chaton de Winna au Puits de lune corrompu, le relâcher, puis le rapporter à Winna.\nUne fois de retour auprès de Winna, cliquer sur le chat pour le lui rendre."},
    [4521] = {n="Gardiens sauvages", d="Trull Failbane de Gangrebois veut que vous tuiez 15 Chouettards enragés et 15 Chouettards éreintés.", tgo={{"Chouettard enragé"}, {"Chouettard éreinté"}}},
    [4542] = {n="Un message pour le poste de Librevent", d="Apporter le Message urgent au garde-falaise Longhorn au Poste de Librevent."},
    [4641] = {n="Votre place en ce monde", d="Parler à Gornek. Souvenez-vous que Kaltunk vous a indiqué où il se trouvait sur votre carte et vous a dit que Gornek résidait dans l'Antre, un bâtiment vers l'ouest."},
    [4724] = {n="La maîtresse de meute", d="Tuer Halycon, la maîtresse de la meute des worgs Bloodaxe.", tgo={{"Halycon"}}},
    [4726] = {n="L'essence de rejeton", d="Apporter 8 Essences de Rejeton et le Draco-Incarcinatrix 900 à Tinkee Steamboil à la Corniche des flammes dans les Steppes ardentes.", objs={"Essence de rejeton"}},
    [4729] = {n="Les animaux exotiques de Kibler", d="Aller au Pic Blackrock et trouver de Jeunes worgs Bloodaxe. Utiliser la cage pour transporter ces petites bêtes féroces. Rapporter un Jeune worg en cage à Kibler."},
    [4737] = {n="À la recherche de Menara Voidrender", d="Parler à Menara Voidrender dans les Tarides."},
    [4739] = {n="À la recherche de Menara Voidrender", d="Parler à Menara Voidrender dans les Tarides."},
    [4742] = {n="Le sceau de l'ascension", d="Trouver les trois gemmes de commandement : la Gemme de Smolderthorn, la Gemme de Pierre-du-pic et la Gemme de Bloodaxe. Rapportez-les, ainsi que le Sceau d'ascension non décoré, à Vaelan.\nLes généraux, comme vous l'a dit Vaelan, sont : le maître de guerre Voone de Smolderthorn ; le généralissime Omokk des Pierres-du-pic ; et le seigneur Wyrmthalak de Bloodaxe.", tgo={{"Généralissime Omokk"}, {"Maître de guerre Voone"}, {"Seigneur Wyrmthalak"}, {"Grunt du Bouclier balafré", "Sentinelle du Bouclier balafré", "Acolyte du Bouclier balafré"}}},
    [4743] = {n="Le sceau de l'ascension", d="Allez à la tourbière du Ver dans le marécage d'Âprefange. Trouvez l'ancien drake, Brandeguerre, et frappez-le sans merci jusqu'à ce que sa volonté soit brisée.\nA cet instant précis, vous devez placer le Sceau d'ascension brut devant l'énorme bête. Vous devez ensuite utiliser rapidement l'Orbe d'énergie draconique sur sa forme affaiblie et prendre possession de ses facultés mentales. Contrôlez la bête et dirigez les flammes du Vol noir sur le Sceau d'ascension brut !", objs={"Sceau d'ascension forgé"}},
    [4767] = {n="Le cavalier céleste", d="Apporter 10 Oeufs de wyverne de Haut-perchoir à Elu au poste de Librevent.", objs={"Oeuf de wyverne de Haut-perchoir"}},
    [4768] = {n="La tablette de Darkstone", d="Apporter la Tablette de Darkstone à l'ombremage Vivian Lagrave à Kargath.", objs={"Tablette de Darkstone"}},
    [4769] = {n="Vivian Lagrave et la tablette de Darkstone", d="Parler à l'ombremage Vivian Lagrave."},
    [4770] = {n="Vers le pays natal", d="Escorter Pao'ka Swiftmountain à partir de Haut-perchoir, puis parler à Motega Firemane au poste de Blanc-relais."},
    [4781] = {n="Les composants de la robe sanglante dorée enchantée", d="Apporter une Barre d'or à Xizk Goodstitch dans la vallée de Strangleronce.", objs={"Coffre en morceaux", "Coffre solide", "Coffre de l'Alliance"}},
    [4782] = {n="Les composants de la robe sanglante dorée enchantée", d="Retourner voir Menara Voidrender dans les Tarides."},
    [4783] = {n="Les composants de la robe sanglante dorée enchantée", d="Apporter 10 Fioles de sang de Fielfurie et 1 Pierre infernale inférieure à Menara Voidrender dans les Tarides.", tgo={{"Voleur Fielfurie", "Entourloupeur Fielfurie", "Lige de la corruption Fielfurie"}, {"Infernal mineur", "Gardien du Portail démoniaque"}}},
    [4784] = {n="Les composants de la robe sanglante dorée enchantée", d="Apporter du Fil d'or fin, 2 Charbons ardents et un Fragment d'âme à Menara Voidrender dans les Tarides.", tgo={{"Xizk Goodstitch"}, {"Exilé ardent"}, {}}},
    [4785] = {n="Fil d'or fin"},
    [4786] = {n="La Robe terminée", d="Attendre que Menara Voidrender ait terminé votre robe puis lui parler de nouveau.", tgo={{"Menara Voidrender"}}, star={"Robe sanglante dorée enchantée", {"WARLOCK"}}},
    [4787] = {n="L'oeuf antique", d="Apporter l'Oeuf antique à Yeh'kinya à Tanaris.", objs={"Oeuf antique"}},
    [4808] = {n="Felnok Steelspring", d="Donner la Lettre de Tinkee à Felnok Steelspring."},
    [4809] = {n="Cornes de Noroît", d="Apporter 8 Cornes intactes de Noroît à Felnok Steelspring.", tgo={{"Petite Noroît", "Chimère Noroît", "Ravageur Noroît"}}},
    [4810] = {n="Retourner voir Tinkee", d="Apporter le Paquet de Felnok à Tinkee Steamboil dans les Steppes ardentes."},
    [4821] = {n="L'oeuf étrange", d="Rapporter l'Oeuf étrange à Hagar Lightninghoof au Poste de Librevent.", objs={"Oeuf étrange"}},
    [4841] = {n="Pacifier les centaures", d="Tuer 12 Eclaireurs galak, 10 Querelleurs galak, et 6 Chasse-vent galak, puis retourner auprès du garde-falaise Longhorn au Poste de Librevent.", tgo={{"Eclaireur galak"}, {"Querelleur galak"}, {"Chasse-vent galak"}}},
    [4842] = {n="Sources étranges", d="Suivre les instructions de Donova Snowden, puis faire un rapport."},
    [4862] = {n="Mauvais", d="Aller au Pic Blackrock et ramasser 15 Oeuf d'araignée du pic pour Kibler.\nCes oeufs peuvent être trouvés à proximité des araignées.", objs={"Oeuf d'araignée du pic"}},
    [4865] = {n="Serpent sauvage", d="Faire un rapport de vos trouvailles à Motega Firemane."},
    [4881] = {n="Complot d'assassinat", d="Prévenir Kanati Greycloud au Poste de Blanc-relais qu'un complot le menace."},
    [4903] = {n="Ordre du chef de guerre", d="Tuer le généralissime Omokk, le maître de guerre Voone et le seigneur Wyrmthalak. Récupérer les Importants documents Blackrock. Retourner voir le chef de guerre Goretooth à Kargath une fois la mission accomplie.", tgo={{"Seigneur Wyrmthalak"}, {"Généralissime Omokk"}, {"Maître de guerre Voone"}, {}}, objs={"Documents discrets"}},
    [4904] = {n="Libre, enfin !", d="Escorter Lakota Windsong hors de la Cime de Noir-nuage, puis parler à Thalia Amberhide au Poste de Librevent."},
    [4921] = {n="Disparition au combat", d="Trouver la femme de Mankrik puis retourner le voir à la Croisée.", tgo={{"Cadavre battu"}}},
    [4941] = {n="Sagesse d'Eitrigg", d="Parler à Eitrigg, à Orgrimmar. Après avoir discuté avec Eitrigg, demander conseil à Thrall.\nVous avez déjà vu Eitrigg dans les Appartements de Thrall."},
    [4961] = {n="Purifie l'Orbe d'Orahil", d="Tuer le Démon de l'Orbe, puis parler à Tabetha.", tgo={{"Démon de l'Orbe"}}},
    [4962] = {n="Un éclat de gangrechien", d="Prendre le Rubis de Felhas et l'utiliser sur l'un des gangrechiens de Désolace. Quand vous aurez réussi, rapporter le Rubis de Felhas et l'Esprit de gangrechien emprisonné à Menara Voidrender, dans les Tarides.", tgo={{"Mange-mana"}}},
    [4963] = {n="Eclat d'Infernal", d="Prendre l'Emeraude d'Infus et l'utiliser sur les Infernaux qui se trouvent en Désolace. Quand vous aurez réussi, rapporter l'Emeraude d'Infus et l'Esprit d'Infernal emprisonné à Menara Voidrender, dans les Tarides.", tgo={{"Infernal mineur"}}},
    [4964] = {n="L'Orbe complet de Dar'Orahil", d="Attendre que Menara Voidrender termine l'Orbe de Dar'Orahil, puis lui reparler.", tgo={{"Menara Voidrender"}}},
    [4966] = {n="Protéger Kanati Greycloud", d="Protéger Kanati Greycloud contre l'attaque centaure.", tgo={{"Assassin galak"}}},
    [4967] = {n="Connaissance de l'Orbe d'Orahil", d="Parler à Menara Voidrender dans les Tarides."},
    [4969] = {n="Connaissance de l'Orbe d'Orahil", d="Parler à Menara Voidrender dans les Tarides."},
    [4971] = {n="Une question de temps", d="Utiliser le Déplaceur temporel à côté de l'un des silos d'Andorhal pour révéler des Parasites temporels.\nTuer 15 Parasites temporels et rapporter le Déplaceur temporel à Chromie, à l'auberge d'Andorhal, dans les Maleterres de l'ouest.", tgo={{"Parasite temporel"}}},
    [4972] = {n="Arrêt du temps", d="Trouver 5 Montres d'Andorhal, dans des coffrets qui se trouvent parmi les décombres de la cité, et les rapporter à Chromie à l'Auberge d'Andorhal, dans les Maleterres de l'ouest.", objs={"Petit coffret"}},
    [4974] = {n="Pour la Horde !", d="Aller au Pic Blackrock et tuer le Chef de guerre, Rend Blackhand. Prendre sa tête et retourner à Orgrimmar.", tgo={{"Chef de guerre Rend Blackhand"}}},
    [4975] = {n="L'Orbe complet de Noh'Orahil", d="Attendre que Menara Voidrender ait terminé l'Orbe de Noh'Orahil, puis lui reparler.", tgo={{"Menara Voidrender"}}},
    [4976] = {n="Rapporter l'Orbe purifié", d="Rapporter l'Orbe infernal purifié à Menara Voidrender, dans les Tarides."},
    [4981] = {n="Agent Bijou", d="Aller au Pic Blackrock et découvrir ce qui est arrivé à Bijou."},
    [4982] = {n="Les effets de Bijou", d="Trouver les Affaires de Bijou et les lui rapporter. Elle vous a dit les avoir cachées dans le niveau inférieur de la ville.", objs={"Affaires de Bijou"}},
    [4983] = {n="Rapport de reconnaissance de Bijou", d="Rapporter le Rapport de reconnaissance de Bijou au Grand-maître Lexlort, à Kargath."},
    [4984] = {n="La faune et la flore souffrent aussi", d="Détruire 8 Loups malades, puis retourner voir Mulgris Deepriver, au Repaire putride dans les Maleterres de l'ouest.", tgo={{"Loup malade"}}},
    [4985] = {n="La faune et la flore en souffrent aussi", d="Détruire 8 Grizzlis malades, puis retourner voir Mulgris Deepriver au Repaire putride, dans les Maleterres de l'ouest.", tgo={{"Grizzly malade"}}},
    [5021] = {n="Mieux vaut tard que jamais", d="Le discours incohérent de la femme fantomatique indique qu'elle a besoin qu'on livre un colis pour elle. Elle a dit que le colis se trouvait là où se trouve son cheval. Le fantôme est incompréhensible lorsqu'il s'agit de préciser où se trouve son cheval ou l'endroit où le paquet doit être livré."},
    [5023] = {n="Mieux vaut tard que jamais", d="Se renseigner auprès des Surveillants royaux d'Undercity pour apprendre l'adresse d'un certain Jeremiah Felstone. En général, il y a un officier du recensement près du bureau d'inscription des guildes et tabards."},
    [5041] = {n="Ravitaillement pour la Croisée", d="Trouver et rapporter les Caisses de ravitaillement de la Croisée à Thork dans les Tarides.", objs={"Caisses de ravitaillement de la Croisée"}},
    [5049] = {n="Le blues de Jeremiah", d="Trouver Jeremiah Payson dans Undercity et découvrir s'il est en fait Jeremiah Felstone. Si c'est le cas, il appréciera peut-être le colis que Janice Felstone lui a préparé."},
    [5050] = {n="Charme porte-bonheur", d="Rapporter son Demi-charme porte-bonheur à Janice Felstone dans les Maleterres de l'ouest."},
    [5051] = {n="Deux moitiés deviennent Une", d="Trouver l'autre moitié du Charme porte-bonheur quelque part dans le périmètre de la Ferme Felstone dans les Maleterres de l'ouest et le recoller.\nDonner le Charme porte-bonheur à Janice Felstone à la Ferme Felstone, dans les Maleterres de l'ouest."},
    [5052] = {n="Joyaux de sang d'Agammagan", d="Apporter un Joyau de sang à Mangletooth, à Camp Taurajo, dans les Tarides.\nCollectez plus de Joyaux de sang, si vous souhaitez qu'il vous gratifie de la puissance d'Agamaggan.", tgo={{"Chasseur Dos-hirsute", "Sourcier Dos-hirsute", "Tisseur d'épines Dos-hirsute"}}},
    [5054] = {n="Ursius des Crocs acérés", d="Storm Shadowhoof, à Long-guet au Berceau-de-l'Hiver, veut que vous tuiez Ursius.", tgo={{"Ursius"}}},
    [5058] = {n="Journal de Mme Dalson"},
    [5059] = {n="Enfermé", d="Butin sur : Squelette errant", tgo={{"Squelette errant"}}},
    [5060] = {n="Enfermé", d="Butin sur : Fermier Dalson", tgo={{"Fermier Dalson"}}},
    [5062] = {n="Feu sacré", d="Ramasser 10 boisseaux d'agave d'Incendia, puis consulter Magatha Grimtotem sur la Cime des Anciens dans Thunderbluff.", objs={"Agave d'incendia"}},
    [5064] = {n="Espionner le Totem sinistre", d="Trouver et récupérer les trois Notes Secrètes à la Cime de Noir-nuage.", objs={"Coffre de documents"}},
    [5082] = {n="La menace des Tombe-hiver", d="Donova Snowden du Berceau-de-l'Hiver veut que vous tuiez 8 Guides, 8 Protecteurs et 8 Totémiques de la tribu Tombe-hiver.", tgo={{"Guide Tombe-hiver"}, {"Protecteur Tombe-hiver"}, {"Totémique Tombe-hiver"}}},
    [5083] = {n="L'eau de feu de Tombe-hiver", d="Apporter le Flacon d'eau de feu vide à Donova Snowden du Berceau-de-l'Hiver."},
    [5084] = {n="Corrompu", d="Chercher un indice dans le camp des furbolgs Mort-bois, dans le nord de Gangrebois."},
    [5085] = {n="Gelée mystère", d="Aller faire un rapport de vos trouvailles à Donova Snowden."},
    [5086] = {n="Horreurs toxiques", d="Récolter 3 Gouttelettes d'Horreur toxique pour Donova Snowden au Berceau-de-l'Hiver.", tgo={{"Horreur toxique"}}},
    [5087] = {n="Les messagers des Tombe-hiver", d="Trouver les Messagers Tombe-hiver et les empêcher de livrer leur cargaison au village Tombe-hiver.", tgo={{"Messager Tombe-hiver"}}},
    [5096] = {n="Diversions écarlates", d="Se rendre au camp de base de la Croisade écarlate situé entre le Champ de Felstone et les Larmes de Dalson et détruire leur tente d'état-major.\nPlacer la bannière du Fléau sur le camp, puis revenir auprès du Grand exécuteur Derrington à la Barricade, dans les Maleterres de l'ouest."},
    [5098] = {n="Tout au long des tours de guet", d="À l'aide de la Torche-balise, marquer chaque tour à Andorhal ; il faut se tenir dans l'embrasure de la porte de la tour pour pouvoir la marquer.\nQuand les quatre tours seront marquées, rapporter la Torche-balise au Grand exécuteur Derrington à la Barricade, dans les Maleterres de l'ouest.", tgo={{"Andorhal Tour un"}, {"Andorhal Tour deux"}, {"Andorhal Tour trois"}, {"Andorhal Tour quatre"}}},
    [5121] = {n="Le grand chef Tombe-hiver", d="Donova Snowden du Berceau-de-l'Hiver veut que vous triomphiez du Grand chef Tombe-hiver.", tgo={{"Grand chef Tombe-hiver"}}},
    [5122] = {n="Le médaillon de foi", d="Utiliser/ramasser : Coffre de Malor", objs={"Coffre de Malor"}},
    [5123] = {n="Le dernier morceau", d="Apporter le Journal mal écrit à Donova Snowden au Berceau-de-l'Hiver."},
    [5125] = {n="L'estimation d'Aurius"},
    [5147] = {n="ON RECHERCHE : Arnak Totem-sinistre", d="Tuer Arnak Grimtotem et apporter une preuve de votre acte au garde-falaise Longhorn au Poste de Librevent.", tgo={{"Arnak Grimtotem"}}},
    [5149] = {n="Poupée de Pamela", d="Trouver la poupée de Pamela."},
    [5151] = {n="Hypercapaciteur bidulotron", d="Tuer la bête et rapporter l'Hypercapaciteur et la Clé de la cage de la panthèse à Wizlo Bearingshiner.", tgo={{"Panthère enragée"}}},
    [5152] = {n="Tante Marlene", d="Parler à Marlene, au sud des ruines d'Andorhal."},
    [5153] = {n="Un étrange historien", d="Apporter l'Alliance de Joseph à Chromie.", objs={"Monument de Joseph Redpath"}},
    [5154] = {n="Les annales de Darrowshire", d="Apporter les Annales de Darrowshire à Chromie, à Andorhal.", objs={"Tome moisi"}},
    [5155] = {n="Les forces de Jaedenar", d="Entrer dans Jaedenar et tuer 4 Molosses de Jaedenar, 4 Gardiens de Jaedenar, 6 Adeptes de Jaedenar, et 6 Sectateurs de Jaedenar avant de retourner auprès de Greta Mosshoof dans Gangrebois.", tgo={{"Molosse de Jaedenar"}, {"Gardien de Jaedenar"}, {"Adepte de Jaedenar"}, {"Sectateur de Jaedenar"}}},
    [5156] = {n="Enquête sur la corruption", d="Trouver et détruire 2 Bêtes d'entropie et 2 Horreurs d'entropie tout en explorant le Val Grêlé. Après avoir vérifié que les cratères à cet endroit sont toujours remplis d'eau corrompue, retourner auprès de Taronn Redfeather dans Gangrebois.", tgo={{"Bête d'entropie"}, {"Horreur d'entropie"}}},
    [5157] = {n="Recueillir de l'eau souillée", d="Amener la Gourde vide au Puits de lune au centre de Jaedenar et la remplir avant de retourner voir Greta Mosshoof dans Gangrebois.", objs={"Le Puits de lune corrompu de Jaedenar"}},
    [5158] = {n="À la recherche de soutien spirituel", d="Apporter l'Eau de Puits de lune corrompue à Islen Waterseer dans les Tarides."},
    [5159] = {n="L'eau purifiée retourne à Gangrebois", d="Apporter l'Eau de Puits de lune purifiée à Greta Mosshoof dans Gangrebois."},
    [5163] = {n="Yéti ? Y es-tu ?", d="Prendre le yéti mécanique d'Umi et effrayer ses amis avec :\nLegacki, à Long-guet (Berceau-de-l'Hiver)\nSprinkle, à Gadgetzan (Tanaris)\nQuixxil, au refuge des Marshal (Cratère d'Un'Goro)\nQuand vous aurez terminé, rapporter le yéti mécanique à Umi.", tgo={{"Legacki"}, {"Sprinkle"}, {"Quixxil"}}},
    [5165] = {n="En calmant les flammes de protection", d="Avec de l'Eau de Puits de lune purifiée, éteindre les flammes des quatre braseros de protection à l'intérieur du Fort des ombres dans Gangrebois.", objs={"Brasero de la Douleur", "Brasero de la Malice", "Brasero de la Souffrance", "Brasero de la Haine"}},
    [5211] = {n="Défenseurs de Darrowshire", d="Libérer 15 Esprits de Darrowshire et retourner auprès de Carlin Redpath.", tgo={{"Esprit de Darrowshire"}}},
    [5212] = {n="La chair ne ment pas", d="Récupérer 20 Echantillons de chair pestiférée à Stratholme puis les rapporter à Betina Bigglezink. Vous pensez que toutes les créatures de Stratholme possèdent de tels échantillons de chair.", tgo={{"Cadavre en décomposition", "Cadavre mutilé", "Goule pestilentielle"}}},
    [5213] = {n="L'agent actif", d="Se rendre jusqu'à Stratholme et fouiller les ziggourats. Trouver et ramener de nouvelles informations sur le Fléau à Betina Bigglezink.", objs={"Donnée du Fléau"}},
    [5214] = {n="Le grand Ezra Grimm", d="Trouver le magasin de tabac d'Ezra Grimm à Stratholme et récupérer une boîte de Tabac d'Ezra. Retourner auprès de Smokey LaRue quand ce sera fait.", tgo={{"Fras Siabi"}}},
    [5228] = {n="Les chaudrons du Fléau", d="Parler à la prêtresse des ombres Vandis à la Barricade, dans les Maleterres de l'ouest."},
    [5229] = {n="Cible : le Champ de Felstone", d="Se rendre au Champ de Felstone, dans les Maleterres de l'ouest pour trouver et vaincre le Seigneur du Chaudron qui s'y trouve. Il aura peut-être une clé qui permet d'accéder au chaudron. Il faut se munir de la Bouteille d'échantillon du Champ de Felstone vide pour pouvoir prélever un échantillon des poisons qui sont dans le chaudron.", tgo={{"Seigneur du Chaudron Bilegueule"}}},
    [5230] = {n="Retour à la Barricade", d="Apporter la Bouteille du Champ de Felstone remplie à la prêtresse des ombres Vandis à la Barricade, dans les Maleterres de l'ouest."},
    [5231] = {n="Cible : les Larmes de Dalson", d="Se rendre aux Larmes de Dalson dans les Maleterres de l'ouest pour trouver et vaincre le Seigneur du Chaudron qui s'y trouve, puis utiliser sa clé pour accéder au chaudron. Il faut se munir de la Bouteille des larmes de Dalson vide pour pouvoir prendre un échantillon des poisons qui sont dans le chaudron.", tgo={{"Seigneur du Chaudron Malvinious"}}},
    [5232] = {n="Retour à la Barricade", d="Apporter la Bouteille des Larmes de Dalson remplie à la prêtresse des ombres Vandis à la Barricade, dans les Maleterres de l'ouest."},
    [5233] = {n="Cible : le Repaire putride", d="Se rendre au Repaire putride dans les Maleterres de l'ouest pour trouver et vaincre le Seigneur du Chaudron qui s'y trouve, et utiliser sa clé pour accéder au chaudron. Il faut se munir de la Bouteille vide du Repaire putride pour pouvoir récupérer un échantillon des poisons à l'intérieur du chaudron.", tgo={{"Seigneur du Chaudron Razarch"}}},
    [5234] = {n="Retour à la Barricade", d="Ramener la Bouteille du Repaire putride remplie à la prêtresse des ombres Vandis à la Barricade, dans les Maleterres de l'ouest."},
    [5235] = {n="Cible : la Flétrissure de Gahrron", d="Se rendre à la Flétrissure de Gahrron dans les Maleterres de l'ouest pour trouver et vaincre le Seigneur du Chaudron qui s'y trouve, et utiliser sa clé pour accéder au chaudron. Il faut se munir de la Bouteille vide de la Flétrissure de Gahrron pour pouvoir récupérer un échantillon des poisons à l'intérieur du chaudron.", tgo={{"Seigneur du Chaudron Irâme"}}},
    [5236] = {n="Retour à la Barricade", d="Apporter la Bouteille de la Flétrissure de Gahrron remplie à la prêtresse des ombres Vandis à la Barricade, dans les Maleterres de l'ouest."},
    [5238] = {n="Mission accomplie !", star={"Epée courte vaillante", {"PALADIN", "MAGE", "WARLOCK"}}},
    [5241] = {n="Oncle Carlin", d="Trouver Carlin Redpath."},
    [5242] = {n="Un coup final", d="Tuer Moora et Salia, et rapporter la Tête du Seigneur des ténèbres Fel'dan à Greta Mosshoof dans Gangrebois.", tgo={{"Moora"}, {"Salia"}, {"Seigneur des ténèbres Fel'dan"}}},
    [5243] = {n="Les demeures du Sacré", d="Se rendre à Stratholme, au nord. Fouiller les caisses de fournitures qui encombrent la cité et récupérer 5 Eaux sacrées de Stratholme. Retourner auprès de Leonid Barthalomew le Révéré quand vous avez récolté assez de liquide béni.", objs={"Caisse de fournitures", "Caisse de fournitures de Stratholme"}},
    [5251] = {n="L'archiviste", d="Voyager jusqu'à Stratholme et trouver l'Archiviste Galford de la Croisade écarlate. L'abattre et brûler les Archives écarlates.", tgo={{"Archiviste Galford"}, {}}, objs={"Archives écarlates"}},
    [5281] = {n="Âmes tourmentées", d="Trouver Egan. Vous savez seulement qu'on l'a vu pour la dernière fois aux alentours de Stratholme."},
    [5282] = {n="Âmes tourmentées", d="Se servir du Libérateur d'Egan sur les citoyens fantomatiques et spectraux de Stratholme. Quand les esprits sans repos se libèrent de leur enveloppes fantomatiques, utiliser de nouveau le Libérateur - ils seront enfin libres !\nLibérer 15 Esprits sans repos puis retourner auprès d'Egan.", tgo={{"Ame sans repos"}}},
    [5306] = {n="Pierre du serpent de la chasseresse des ombres", d="Aller jusqu'au Pic Blackrock et abattre la chasseresse des ombres Vosh'gajin. Récupérer la Pierre du serpent de Vosh'gajin et la ramener à Kilram.", tgo={{"Chasseresse des ombres Vosh'gajin"}}},
    [5341] = {n="Fortune de la famille Barov", d="S'aventurer jusqu'à Scholomance et récupérer la fortune de la famille Barov. Cette fortune se compose de quatre titres de propriété : le titre de propriété de Caer Darrow ; le titre de propriété de Brill ; le titre de propriété de Moulin-de-Tarren ; et le titre de propriété de Southshore. Revenir auprès d'Alexi Barov quand la tâche est accomplie.", objs={"Titre de propriété de Brill", "Titre de propriété de Caer Darrow", "Titre de propriété de Southshore", "Titre de propriété de Moulin-de-Tarren"}},
    [5361] = {n="Arbre familial", d="Apporter le Rapport du garde-falaise Longhorn à Nataka Longhorn au poste de Rôdeur-fantôme en Désolace."},
    [5381] = {n="La Main d'Iruxos", d="Récupérer la Boîte démoniaque dans la forteresse de Hache-Tonnerre, puis la rapporter à Taiga Wisemane, à Proie-de-l'Ombre.", tgo={{"Esprit démon"}}},
    [5382] = {n="Docteur Theolen Krastinov, le boucher", d="Trouver le docteur Theolen Krastinov à l'intérieur de la Scholomance. Le tuer, puis brûler le Cadavre d'Eva Sarkhoff et le Cadavre de Lucien Sarkhoff. Retourner auprès d'Eva Sarkhoff quand la tâche est accomplie.", tgo={{"Docteur Theolen Krastinov"}, {}, {}}, objs={"Cadavre d'Eva Sarkhoff", "Cadavre de Lucien Sarkhoff"}},
    [5386] = {n="La prise du jour", d="Parler à Jinar'Zillen à Proie-de-l'Ombre, puis amener 2 poissons Ventre-rouge à Nataka Longhorn.", tgo={{"Jinar'Zillen"}}},
    [5441] = {n="Les péons paresseux", d="Utiliser la Masse du contremaître sur les Péons paresseux, lorsqu'ils sont en train de dormir. Réveiller 5 Péons, puis rapporter la Masse du contremaître au contremaître Thazz'ril, dans la Vallée des épreuves.", tgo={{"Péon fainéant"}}},
    [5481] = {n="La tâche de Gordo", d="Récolter 3 herbes des ténèbres et les apporter à l'Apprenti Apothicaire Holland au cimetière de Brill.", objs={"Herbe des ténèbres"}},
    [5482] = {n="Herbe maléfique", d="Récolter 10 Herbes maléfiques et les apporter à l'apprenti apothicaire Holland.", objs={"Herbe maléfique"}},
    [5501] = {n="Collectionneur d'os", d="Apporter à Bibbly F'utzbuckle à la Hutte de Kormek 10 Os de kodo provenant du Cimetière des kodos.", objs={"Os de kodo"}},
    [5511] = {n="La clé de Scholomance"},
    [5514] = {n="Moisissure rime avec…", d="Apporter les Fragments de squelette imprégnés et 15 pièces d'or à Krinkle Goodsteel à Gadgetzan."},
    [5518] = {n="La tenue d'ogre gordok", d="Apportez 4 Rouleaux d'étoffe runique, 8 Cuirs robustes, 2 Fils runiques et du Tanin ogre à Knot Thimblejack. Il est actuellement enchaîné dans l'aile Gordok de Hache-tripes.", objs={"Felsteel Chest", "Panier de tanin ogre", "Réserve de Knot Thimblejack"}},
    [5525] = {n="Libérez Knot !", d="Butin sur : Brute Gordok, Seigneur-mage Gordok, Capitaine Gordok", tgo={{"Brute Gordok", "Seigneur-mage Gordok", "Capitaine Gordok"}}},
    [5526] = {n="Fragment de la Gangrevigne", d="Trouvez la Gangrevigne à Hache-tripes et prenez-en un fragment. Il est probable que vous ne pourrez vous en emparer qu'après la mort d'Alzzin le Modeleur. Servez-vous du Reliquaire de Pureté pour conserver le fragment, et retournez à Reflet-de-Lune voir Rabine Saturna au village de Havrenuit."},
    [5527] = {n="Un reliquaire de pureté", d="Rendez-vous en Silithus et cherchez un Reliquaire de pureté dans les ruines du village de Sudevent. Si vous parvenez à le trouver, ramenez-le à Rabine Saturna à Havrenuit, Reflet-de-Lune.", objs={"Reliquaire poussiéreux"}},
    [5528] = {n="La dégustation gordok"},
    [5529] = {n="Portée contaminée", d="Tuer 20 Jeunes pestiférés, puis retourner auprès de Betina Bigglezink à la Chapelle de l'Espoir de Lumière.", tgo={{"Jeune pestiféré"}}},
    [5534] = {n="L'équipement \"manquant\" de Kim'jael", d="Trouver \"une rune\" détenue par les nagas dans les ruines d'Eldarath et la rapporter à Kim'jael à Azshara.", tgo={{"Sirène Fouette-bile", "Myrmidon Fouette-bile", "Maître de guerre Fouette-bile"}}},
    [5535] = {n="Agitation spirituelle", d="Détruire 6 Apparitions de Bien-nés et 6 Jeunes liches bien-nées avant de retourner auprès de Loh'atu à Azshara.", tgo={{"Apparition bien-née"}, {"Jeune liche bien-née"}}},
    [5536] = {n="Un pays plein de haine", d="Tuer 6 satyres Haldarr, 2 Entourloupeurs Haldarr, 2 Lige de la corruption Haldarr puis revenir auprès de Loh'atu à la frontière d'Ashenvale.", tgo={{"Satyre Haldarr"}, {"Entourloupeur Haldarr"}, {"Lige de la corruption Haldarr"}}},
    [5542] = {n="Chiens-démons", d="Tuer 20 Chiens pestiférés chétifs, 5 Chiens pestiférés et 5 Chiens pestiférés frénétiques. Retourner voir Tirion Fordring, quand la mission sera terminée.", tgo={{"Chien pestiféré chétif"}, {"Chien pestiféré"}, {"Chien pestiféré frénétique"}}},
    [5543] = {n="Ciel couleur de sang", d="Tuer 30 Chauves-souris pestiférées, puis retourner voir Tirion Fordring.", tgo={{"Chauve-souris pestiférée"}}},
    [5544] = {n="Larve putride", d="Chercher les Larves putrides et les Dévoreurs de la région. Les tuer et récupérer leur viande. Retourner voir Tirion Fordring quand 15 pièces de Chair de Ver putride auront été récupérées.", tgo={{"Larve putride", "Dévoreur putride"}}},
    [5561] = {n="Le rassemblement des kodos", d="Ramener cinq Kodos domptés et le Kombobulateur kodo à Smeed Scrabblescrew au camp de Scrabblescrew."},
    [5581] = {n="Les portails de la Légion", d="Bannir 6 Portails, dans le convent de Mannoroc, puis retourner voir Taiga Wisemane, à Proie-de-l'Ombre.", tgo={{"Gardien du Portail démoniaque"}}},
    [5601] = {n="Pamela, ma sœur", d="Trouver Pamela Redpath dans le Darrowshire."},
    [5648] = {n="Vêtements de la spiritualité", d="Trouver le grunt Kor'ja et la guérir de ses blessures en utilisant Soins inférieurs (Rang 2). Lui accorder ensuite le Mot de pouvoir : Robustesse, puis retourner voir Tai'jin, sur Tranchecolline.", tgo={{"Grunt Kor'ja"}}},
    [5649] = {n="Au service de la spiritualité", d="Parler à Tai'jin en Durotar."},
    [5650] = {n="Vêtements des ténèbres", d="Trouver le Garde noir Kel et le guérir de ses blessures en utilisant Soins inférieurs (Rang 2). Lui accorder ensuite le Mot de pouvoir : Robustesse, puis retourner voir le sombre clerc Beryl, à Brill.", tgo={{"Garde noir Kel"}}},
    [5651] = {n="Au service des ténèbres", d="Parler au sombre clerc Beryl dans les Clairières de Tirisfal."},
    [5652] = {n="Le maléfice de faiblesse"},
    [5654] = {n="Le maléfice de faiblesse", d="Parler à Ur'kyo à Orgrimmar."},
    [5658] = {n="Toucher de faiblesse"},
    [5679] = {n="Sombre sacrifice"},
    [5680] = {n="Garde des ténèbres"},
    [5722] = {n="À la recherche de la sacoche perdue", d="Fouiller le Gouffre de Ragefeu pour trouver le cadavre de Maur Grimtotem et tout élément intéressant."},
    [5723] = {n="Tester la force de l'ennemi", d="Chercher le gouffre de Ragefeu dans Orgrimmar, puis tuer 8 Troggs Ragefeu et 8 Chamans Ragefeu avant de revenir auprès de Rahauro à Thunder Bluff.", tgo={{"Trogg Ragefeu"}, {"Chaman Ragefeu"}}},
    [5724] = {n="Rapporter la sacoche perdue", d="Apporter la Sacoche du Totem sinistre à Rahauro à Thunder Bluff."},
    [5725] = {n="Le pouvoir de détruire...", d="Apporter les livres de Sorts des Ombres et d'Incantations du Néant à Varimathras, à Fossoyeuse.", tgo={{"Sectateur de la Lame brûlante", "Démoniste de la Lame brûlante"}, {"Sectateur de la Lame brûlante", "Démoniste de la Lame brûlante"}}},
    [5726] = {n="Ennemis cachés", d="Apporter un Insigne de lieutenant à Thrall à Orgrimmar.", tgo={{"Fanatique de la Lame ardente", "Apprenti de la Lame ardente"}}},
    [5727] = {n="Ennemis cachés", d="Apporter l'Insigne du Lieutenant à Neeru Fireblade et lui parler. Essayer de déterminer s'il vous croit membre de la Lame ardente puis retourner voir Thrall à Orgrimmar.", tgo={{"Neeru Fireblade"}}},
    [5728] = {n="Ennemis cachés", d="Tuer Bazzalan et Jergosh l'Invocateur avant de retourner voir Thrall à Orgrimmar.", tgo={{"Bazzalan"}, {"Jergosh l'Invocateur"}}},
    [5729] = {n="Ennemis cachés", d="Parler à Neeru Fireblade à Orgrimmar."},
    [5730] = {n="Ennemis cachés", d="Parler à Thrall à Orgrimmar et lui dire ce que vous avez appris."},
    [5741] = {n="Sceptre de lumière", d="Prendre le Sceptre de lumière et le rapporter à Azore Aldamort, dans la tour d'Ethel Rethor.", tgo={{"Prophète de la Lame ardente"}}},
    [5742] = {n="Rédemption", d="Écouter ce que Tirion Fordring a à dire.", tgo={{"Tirion Fordring"}}},
    [5761] = {n="Tuer la bête", d="Pénétrer dans le Gouffre de Ragefeu et tuer Taragaman l'Affameur, puis rapporter son coeur à Neeru Fireblade à Orgrimmar.", tgo={{"Taragaman l'Affameur"}}},
    [5762] = {n="Hemet Nesingwary", d="Apporter la Caisse de Kravel à Hemet Nesingwary, à Strangleronce."},
    [5763] = {n="Chasse à Strangleronce", d="Apporter la Corne de kodo de Roon à Hemet Nesingwary à Strangleronce."},
    [5781] = {n="Aux mémoires perdues", d="Aller au caveau de Zaeldarr - situé dans la section la plus au sud des Maleterres de l'est - et récupérer le Marteau de Taelan. Retourner auprès de Tirion Fordring après avoir accompli la mission.", tgo={{"Mercutio Filthgorger"}}},
    [5802] = {n="Forgée dans la Fournaise", d="Prendre le moule de la Clé squelette et deux barres de thorium au sommet de la crête de la Fournaise dans le cratère d'Un'Goro. Se servir du moule de la Clé squelette pour forger la Clé squelette inachevée.\nApporter la Clé squelette inachevée à l'Apothicaire Dithers à la Barricade, Maleterres de l'Ouest.", objs={"Lac de Lave de la Crête de la Fournaise"}},
    [5804] = {n="Le Scarabée d'Araj", d="Vaincre Araj l'Invocateur et apporter le Scarabée d'Araj à l'apothicaire Dithers à la Barricade, dans les Maleterres de l'ouest.", objs={"Phylactère d'Araj"}},
    [5843] = {n="Bienvenue !", d="Apporter le Bon-cadeau (Vallée des Epreuves) à Magga."},
    [5844] = {n="Bienvenue !", d="Apporter le Bon-cadeau (Camp Narache) à Vorn Skyseer."},
    [5845] = {n="De l'honneur perdu", d="Se rendre à Valnord, dans la région nord-est des Maleterres de l'est, et récupérer le Symbole de l'honneur perdu. Revenir auprès de Tirion Fordring quand la tâche est accomplie.", objs={"Symbole de l'honneur perdu"}},
    [5846] = {n="L'amour et la famille", d="Voyager jusqu'à l'île de Caer Darrow, dans la région centre-sud des Maleterres, et chercher un indice de l'emplacement du tableau."},
    [5848] = {n="De l'amour et de la famille", d="Se rendre à Stratholme, dans la partie nord des Maleterres. C'est dans le Bastion écarlate que se trouve le tableau De l'amour et de la famille, caché derrière une autre peinture représentant les lunes jumelles.\nRapporter le tableau à Tirion Fordring.", objs={"Peinture inachevée"}},
    [5863] = {n="La base des Cognedunes", d="Andi Lynn de Gadgetzan veut que vous détruisiez la Base des Cognedunes en tuant 10 Brutes Cognedunes, 10 Massacreurs Cognedunes, et Gor'marok le Ravageur.", tgo={{"Brute Cognedune"}, {"Massacreur Cognedune"}, {"Gor'marok le Ravageur"}}},
    [5881] = {n="Puiser dans les réserves", d="Maggran voudrait que vous apportiez une lettre à Grish Longrunner, à la Grande élévation, dans les Tarides."},
    [5901] = {n="Une Plaie sur la Croisade", d="Utiliser le Pot de Termites vide sur la Termitière, dans les Maleterres de l'est. Après avoir récupéré 100 Termites des Maleterres, retourner voir Mickey Levine, à la Barricade, dans les Clairières de Tirisfal.", objs={"Grande termitière"}},
    [5902] = {n="Une Plaie sur la Croisade", d="Trouver un endroit judicieux, au centre de la scierie de la Crête du nord, dans les Maleterres de l'ouest, pour placer le Tonneau de Termites des Maleterres."},
    [5922] = {n="Reflet-de-Lune", d="Utiliser le sort \"Téléportation : Reflet-de-Lune\" pour aller à Reflet-de-Lune. Une fois sur place, parler à Dendrite Starblaze, au village de Havrenuit."},
    [5926] = {n="Écouter l'appel", d="Parler à Turak Runetotem, sur la Cime des Anciens de Thunder Bluff."},
    [5927] = {n="Écouter l'appel", d="Parler à Turak Runetotem, sur la Cime des Anciens de Thunder Bluff."},
    [5928] = {n="Écouter l'appel", d="Parler à Turak Runetotem, sur la Cime des Anciens de Thunder Bluff."},
    [5930] = {n="Esprit du Grand ours", d="Aller voir l'esprit du Grand ours, au nord-ouest de Reflet-de-Lune et apprendre ce qu'il peut vous enseigner sur la nature de l'ours. Quand cela est fait, retourner voir Dendrite Starblaze, à Havrenuit, dans Reflet-de-Lune.", tgo={{"Esprit du Grand ours"}}},
    [5932] = {n="Retour vers Thunder Bluff", d="Retourner à Thunder Bluff, et parler à Turak Runetotem, sur la Cime des Anciens."},
    [6002] = {n="Corps et cœur", d="Utiliser la Poussière lunaire cénarienne sur la Pierre des séléniens, entre Mulgore et les Tarides, pour invoquer Lunegriffe. Affronter Lunegriffe, et gagner la force physique et spirituelle qu'il possède.\nQuand cela est fait, parler à Turak Runetotem, à Thunder Bluff.", tgo={{"Esprit de Lunegriffe"}}},
    [6022] = {n="Tuer utile", d="Allez à l'est à la Croisée de Corin et détruisez les membres du Fléau qui habitent la ville. Rassemblez sept morceaux de Pourriture vivante en moins de dix minutes. Utilisez le Mortier et le pilon pour réduire la Pourriture vivante en Pourriture coagulée."},
    [6027] = {n="Le Livre des Anciens", d="Obtenir le Livre des Anciens, puis le rapporter à Azore Aldamort, dans la tour d'Ethel Rethor.", tgo={{"Seigneur Kragaru"}}},
    [6029] = {n="Le rapport de Long-guet", d="Livrer le Rapport de Long-guet à l'officier Garush de l'Aube d'argent, à la Barricade, dans les Maleterres de l'ouest."},
    [6030] = {n="Le duc Nicholas Zverenhoff", d="Apportez le livre \" Etudes sur la langue des Esprits \" au duc Nicholas Zverenhoff, à la chapelle de l'Espoir de Lumière, dans les Maleterres de l'est."},
    [6042] = {n="Les petits soucis de la non-vie", d="Tuer 20 Chauves-souris pestiférées nuisibles et 10 Chauves-souris pestiférées monstrueuses. Retourner voir Nathanos le Flétrisseur quand ce sera fait.", tgo={{"Chauve-souris pestiférée nuisible"}, {"Chauve-souris pestiférée monstrueuse"}}},
    [6061] = {n="Dompter la bête", d="Utiliser le Bâtonnet de domptage pour dompter un trotteur des plaines adulte. S'entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Yaw Sharpmane, à Sabot-de-Sang.", tgo={{"Trotteur des plaines adulte"}}},
    [6062] = {n="Dompter la bête", d="Utiliser le Bâtonnet de domptage pour dompter un sanglier tacheté redoutable. S'entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Thotar de Tranchecolline.", tgo={{"Sanglier tacheté redoutable"}}},
    [6065] = {n="La voie du chasseur", d="Parler à Yaw Sharpmane, au village Bloodhoof."},
    [6066] = {n="La voie du chasseur", d="Parler à Yaw Sharpmane, au village Bloodhoof."},
    [6067] = {n="La voie du chasseur", d="Parler à Yaw Sharpmane, à Sabot-de-Sang."},
    [6068] = {n="La voie du chasseur", d="Parler à Thotar, à Tranchecolline."},
    [6069] = {n="La voie du chasseur", d="Parler à Thotar, à Tranchecolline."},
    [6070] = {n="La voie du chasseur", d="Parler à Thotar, à Tranchecolline."},
    [6081] = {n="Entraîner la bête", d="Adressez-vous à Orkmar Grimshot à Orgrimmar."},
    [6082] = {n="Dompter la bête", d="Domptez un Scorpide blindé à l'aide du Bâtonnet de domptage. Entraînez-vous puis retournez voir Thotar à Tranchecolline.", tgo={{"Scorpide blindé"}}},
    [6083] = {n="Dompter la bête", d="Utiliser le Bâtonnet de domptage pour dompter un Clampant de l'écume. S'entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Thotar, à Tranchecolline.", tgo={{"Clampant de l'écume"}}},
    [6087] = {n="Dompter la bête", d="Utiliser le Bâtonnet de domptage pour dompter un Traqueur des prairies. S'entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Yaw Sharpmane, à Sabot-de-Sang.", tgo={{"Traqueur des prairies"}}},
    [6088] = {n="Dompter la bête", d="Utiliser le Bâtonnet de domptage pour dompter un Rapace. S'entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Yaw Sharpmane, à Sabot-de-Sang.", tgo={{"Rapace"}}},
    [6089] = {n="Entraîner la bête", d="Parler à Holt Thunderhorn, sur la Cime des Chasseurs, à Thunder Bluff."},
    [6126] = {n="Nouvelles leçons", d="Aller à Reflet-de-Lune, et parler à Dendrite Starblaze, au village de Havrenuit."},
    [6127] = {n="Le principe originel", d="Utiliser la Fiole d'échantillon vide du Pic de Brume-funeste pour collecter un échantillon de l'eau d'un bassin, au sommet du Pic de Brume-funeste.\nApporter ensuite la Fiole d'échantillon remplie à Tonga Runetotem, à la Croisée, dans les Tarides.", objs={"Dreadmist Peak Pool"}},
    [6128] = {n="Rassembler les ingrédients du remède", d="Apporter 5 Terrestrines et 5 Cornes de kodo à Tonga Runetotem, à la Croisée, pour qu'il puisse préparer un baume curatif.", tgo={{"Jeune pousse de flagellant", "Irevigne"}, {"Kodo égaré des Tarides", "Kodo des Tarides"}}},
    [6129] = {n="Soigner la maladie", d="Utiliser le Remède pour animaux sur 10 Gazelles malades qui se trouvent dans la partie nord des Tarides ; ceci les soignera. Les Gazelles malades ont été vues au nord de la route orientée est-ouest qui traverse la Croisée.", tgo={{"Gazelle malade"}}},
    [6130] = {n="Pouvoir contre le poison", d="Retourner voir Turak Runetotem, sur la Cime des Anciens, à Thunder Bluff."},
    [6134] = {n="Chasse à l'ectoplasme", d="Apporter 8 Fantôm-o-plasmes et la Caisse d'aimants fantômes à Hornizz Brimbuzzle, en Désolace.", tgo={{"Spectre de centaure"}}},
    [6142] = {n="Des praires comme appât", d="Trouver 10 morceaux de Chair de praire et les apporter à Mai'Lahii, à Proie-de-l'Ombre.", tgo={{"Clampant des récifs enragé"}}},
    [6143] = {n="D'autres poissons-chats à fouetter", d="Tuer 7 Myrmidons Ondulame, 7 Nagas Ondulame et 5 Sorcières Ondulame, puis parler à Drulzegar, à Proie-de-l'Ombre, en Désolace.", tgo={{"Myrmidon Ondulame"}, {"Naga Ondulame"}, {"Sorcière Ondulame"}}},
    [6161] = {n="Revendiquer le trésor de Rackmore !", d="Trouver la Clé d'argent de Rackmore. Trouver la Clé d'or de Rackmore. Trouver et ouvrir le Coffre de Rackmore.", tgo={{"Rampant Claquesec", "Pinceur Claquesec"}, {"Naga Ondulame", "Sorcière Ondulame", "Guerrier Ondulame"}}},
    [6162] = {n="La dernière bataille d'un mari", d="Tuer le Seigneur Ror et apporter sa Griffe à Dreka'Sur, au Poste de la Vénéneuse, en Gangrebois.", tgo={{"Seigneur Ror"}}},
    [6164] = {n="Le livre de compte d'Augustus", d="Apporter le Livre de compte d'Augustus à Augustus le Touché à Val-Terreur.", objs={"Livre de compte d'Augustus"}},
    [6282] = {n="La menace des harpies", d="Maggran Earthbinder de la retraite de Roche-Soleil veut que vous anéantissiez sept Harpies, sept Embusquées, sept Tueuses et sept Volplumes Rougefuries.", tgo={{"Harpie Rougefurie"}, {"Embusquée Rougefurie"}, {"Tueuse Rougefurie"}, {"Volplume Rougefurie"}}},
    [6283] = {n="La lignée Rougefurie", d="Maggran, à la Retraite de Roche-Soleil, vous demande de détruire la Déchiqueteuse Rougefurie et de rapporter son corps comme preuve de votre exploit.", tgo={{"Déchiqueteuse Rougefurie"}}},
    [6284] = {n="Arachnophobie", d="Tuer Besseleth, et apporter le Croc de Besseleth à Maggran, dans la Retraite de Roche-Soleil.", tgo={{"Besseleth"}}},
    [6301] = {n="Cycle de la renaissance", d="Tammra Windfield, de la retraite de Roche-Soleil, vous demande de rassembler 10 Graines de Gaea.", objs={"Graine de Gaea"}},
    [6381] = {n="Nouvelle vie", d="Planter 10 Graines de Gaea sur les Monticules de Gaea, puis parler à Tammra, à la Retraite de Roche-Soleil.", objs={"Monticule de poussière de Gaea"}},
    [6382] = {n="La Chasse d'Ashenvale", d="Parler à Senani Thunderheart, au Poste de Bois-brisé, à Ashenvale."},
    [6383] = {n="La Chasse d'Ashenvale"},
    [6390] = {n="Une Plaie sur la Croisade", d="Libérez les Termites des Maleterres dans la scierie de la Crête du nord, puis retournez voir Mickey Levine, à la Barricade, dans les Clairières de Tirisfal, avec le Tonneau de Termites des Maleterres."},
    [6393] = {n="Guerre élémentaire", d="Apporter 10 Incendrites à Tsunaman, dans la Retraite de Roche-Soleil.", tgo={{"Esprit flamboyant insoumis", "Ravageur ardent", "Destructeur ardent"}}},
    [6394] = {n="La pioche de Thazz'ril", d="Apportez la Pioche de Thazz'rill au contremaître Thazz'rill.", objs={"Pioche de Thazz'ril"}},
    [6395] = {n="La dernière volonté de Marla", d="Apporter le Cadavre de Samuel Fipps sur la Tombe de Marla, puis retourner voir la novice Elreth.", objs={"Tombe de Marla"}},
    [6421] = {n="Le ravin des Eboulis", d="Explorer la grotte du ravin des Eboulis, et apporter 10 Cristaux de résonite à Mor'rogal, dans la Retraite de Roche-Soleil.", objs={"Cristal de résonite"}},
    [6441] = {n="Cornes de satyre", d="Collecter 16 Cornes de satyre pour Pixel, au Poste de Bois-brisé.", tgo={{"Voleur de Xavian", "Traître de Xavian", "Lige de la corruption de Xavian"}}},
    [6442] = {n="Des nagas sur la grève de Zoram", d="Apporter 20 Têtes d'Irequeue à Marukai, le long de la grève de Zoram.", tgo={{"Myrmidon Irequeue", "Rasoir Irequeue", "Chevaucheur des vagues Irequeue"}}},
    [6461] = {n="Suceurs de sang", d="Xen'zilla, à Malaka'Jin, voudrait que vous tuiez 10 Rampants des mousses profondes et 7 Venimeux des mousses profondes.", tgo={{"Rampant des mousses profondes"}, {"Venimeux des mousses profondes"}}},
    [6462] = {n="Charme troll", d="Apporter 8 Charmes trolls à Mitsuwa, à l'Avant-poste de Zoram'gar.", objs={"Coffre de troll"}},
    [6481] = {n="Un Terrestre se lève", d="Ouvrir la Gangue de résonite avec le Cristal de résonite enchanté, puis tuer Goggeroc. Retourner voir Mor'rogal pour l'informer et lui rapporter le Cristal de résonite enchanté.", tgo={{"Goggeroc"}}},
    [6482] = {n="Liberté pour Ruul", d="Escorter Ruul, puis parler à Yama Snowhoof, au Poste de Bois-brisé."},
    [6503] = {n="Les estafettes d'Ashenvale", d="Tuer 9 Estafettes d'Ashenvale, puis retourner voir Kuray'bin, à l'avant-poste de Bois-brisé.", tgo={{"Estafette d'Ashenvale"}}},
    [6504] = {n="Les pages perdues", d="Trouver les 12 pages manquantes du Manuel d'utilisation du Déchiqueteur, puis les rassembler pour constituer les Chapitres 1, 2, et 3. Ramener les pages à Gurda Ragescar près du poste de Bois-brisé."},
    [6521] = {n="Une alliance impie", d="Apporter la Tête de l'Ambassadeur Malcin à Varimathras, à Fossoyeuse.", tgo={{"Ambassadeur Malcin"}}},
    [6522] = {n="Une alliance impie", d="Apporter le Petit parchemin à Varimathras, à Fossoyeuse."},
    [6541] = {n="Rapport à Kadrak", d="Faire un rapport à Kadrak, dans la tour de guet, dans le nord des Tarides."},
    [6543] = {n="Les rapports chanteguerres", d="Apporter les Rapports du clan Chanteguerre à l'Eclaireur chanteguerre, au Messager chanteguerre et au Voltigeur chanteguerre. Rapporter leurs comptes rendus mis à jour à Kadrak, dans la tour de guet nord, dans les Tarides."},
    [6544] = {n="L'assaut de Torek", d="Escorter Torek lors de son attaque contre l'Avant-poste d'Aile-argent et Duriel Moonfire, puis faire un rapport à Ertog Ragetusk, au Poste de Bois-brisé."},
    [6545] = {n="Mise à jour du Messager chanteguerre"},
    [6546] = {n="Mise à jour du voltigeur chanteguerre"},
    [6547] = {n="Mise à jour de l'Eclaireur chanteguerre"},
    [6561] = {n="L'infamie de Brassenoire", d="Apporter la tête du Seigneur du crépuscule Kelris à Bashana Runetotem, à Thunder Bluff.", tgo={{"Seigneur du crépuscule Kelris"}}},
    [6562] = {n="Problèmes dans les profondeurs", d="Parler à Je'neu Sancrea, à Ashenvale."},
    [6563] = {n="L'Essence d'Aku'Mai", d="Apporter 20 Saphirs d'Aku'Mai à Je'neu Sancrea, à Ashenvale.", objs={"Saphir d'Aku'Mai"}},
    [6564] = {n="Allégeance aux Dieux très anciens", d="Apporter la Note humide à Je'neu Sancrea, à Ashenvale."},
    [6565] = {n="Allégeance aux Dieux très anciens", d="Tuer Lorgus Jett, dans les Profondeurs de Brassenoire et retourner voir Je'neu Sancrea, à Ashenvale.", tgo={{"Lorgus Jett"}}},
    [6621] = {n="Le roi des Vile-sylve", d="Placer la Bannière de Karang sur le Monticule du totem Vile-sylve. Ne pas laisser les furbolgs détruire la Bannière. Tuer le chef Murgut, et apporter le Totem de Murgut à Karang Amakkar, à Zoram'gar.", tgo={{"Chef Murgut"}}},
    [6626] = {n="L'hôte du mal", d="Tuer 8 Gardes de guerre Tranchebauge, 8 Tisseurs d'épines Tranchebauge et 8 Sectateur de la Tête de mort, puis retourner voir Myriam Moonsinger, à l'entrée des Souilles de Tranchebauge.", tgo={{"Garde de guerre de Tranchebauge"}, {"Tisseur d'épines de Tranchebauge"}, {"Sectateur de la Tête de Mort"}}},
    [6627] = {n="L'épreuve de la Connaissance", d="Réussir à répondre à la question de Braug Dimspirit, puis lui reparler. Il se trouve dans les Serres-Rocheuses."},
    [6641] = {n="Vorsha la Flagellante", d="Garantir la sécurité de Muglash tandis qu'il voyage vers le brasero. L'aider à éteindre le brasero, puis le protéger, en combattant les nagas.\nEn cas de réussite, retourner à l'avant-poste de Zoram'gar et informer le messager chanteguerre de la mort de Vorsha la Flagellante."},
    [6681] = {n="Ravenholdt, le manoir", d="Apporter le Sceau de Ravenholdt à Fahrad, au Manoir de Ravenholdt, dans les collines d'Hillsbrad.\nVotre sagacité sera mise à l'épreuve tout au long de la route. Préparez-vous.", tgo={{"Ravenholdt"}}},
    [6701] = {n="Emblèmes du Syndicat", d="Butin sur : Assassin du Syndicat, Conjurateur du Syndicat, Détrousseur du Syndicat", tgo={{"Assassin du Syndicat", "Conjurateur du Syndicat", "Détrousseur du Syndicat"}}},
    [6844] = {n="Umber, Archiviste", d="Apporter l'Objet silithide incrusté à Umber, l'archiviste du Cercle cénarien, au village de Havrenuit, à Reflet-de-Lune."},
    [6845] = {n="Les secrets du passé", d="Parler à Rabine Saturna, au village de Havrenuit, à Reflet-de-Lune."},
    [6921] = {n="Parmi les ruines", d="Apporter le Noyau de la brasse à Je'neu Sancrea, à l'Avant-poste de Zoram'gar, dans Ashenvale.", objs={"Pierre de la Brasse"}},
    [6922] = {n="Baron Aquanis", d="Apporter le Globe d'eau étrange à Je'neu Sancrea, à l'Avant-poste de Zoram'gar, dans Ashenvale."},
    [6981] = {n="L'Eclat luminescent", d="Allez à Ratchet pour trouver quelqu'un qui puisse vous en dire plus sur l'Eclat luminescent.\nPuis livrez l'Eclat, selon les instructions.", tgo={{"Sputtervalve"}}},
    [7003] = {n="Géants rétrécis", d="Utilisez l'Ultra-réducteur de Zorbin sur des géants de n'importe quel type en Féralas afin les rendre plus faciles à gérer. Apportez 15 résidus de miniaturisation que vous trouverez sur les versions rétrécies des géants à Zorbin Poudrozieu aux quais de la côte Oubliée, en Féralas.", tgo={{"Marcheur des terres", "Géant des falaises", "Marcheur des rivages"}}},
    [7028] = {n="Forces maléfiques retorses", d="Collecter 25 Ciselures de Cristaux Théradriques pour Saule, en Désolace.", tgo={{"Centaure maudit", "Satyre Putridus", "Entourloupeur Putridus"}}},
    [7029] = {n="La corruption de Vylelangue", d="Remplir la Fiole céruléenne renforcée, au Bassin de cristal orange, dans Maraudon.\nEn faire usage sur les Vignes de Vylevrille pour forcer les Engeances de Noxxious corrompues à en sortir.\nSoigner 8 plantes en tuant les Engeances de Noxxious, puis retourner voir Vark Battlescar, à Proie-de-l'Ombre.", tgo={{"Engeance de Noxxious"}, {}}, objs={"Bassin de cristal orange de Maraudon"}},
    [7044] = {n="Légendes de Maraudon", d="Retrouver les deux parties du Sceptre de Celebras : le Bâtonnet de Celebras et le Diamant de Celebras.\nTrouvez un moyen de parler à Celebras.", tgo={{"Seigneur Vylelangue"}, {"Noxxion", "Rejeton de Noxxion"}}},
    [7046] = {n="Le sceptre de Celebras", d="Aidez Celebras le Racheté pendant qu'il recrée le Sceptre de Celebras.\nParlez-lui après la réussite du rituel.", objs={"Incantation of Celebras"}},
    [7064] = {n="Corruption de la terre et de la graine", d="Anéantir la princesse Theradras et retourner voir Selendra près de Proie-de-l'Ombre, en Désolace.", tgo={{"Princesse Theradras"}}},
    [7066] = {n="Graine de vie", d="Chercher Remulos à Reflet-de-Lune, et lui donner la Graine de vie."},
    [7067] = {n="Les instructions du paria", d="Lire les instructions du paria. Après cela, obtenir l'Amulette d'union de Maraudon et la ramener au centaure renégat, dans le sud de Désolace."},
    [7068] = {n="Fragments d'Ombréclat", d="Collecter 10 Fragments d'Ombréclats dans Maraudon, et les ramener à Uthel'nay, à Orgrimmar.", tgo={{"Grondeur Ombréclat", "Fracasseur Ombréclat", "Foudroyeur Ombréclat"}}},
    [7201] = {n="Le dernier élément", d="Partir pour les Profondeurs de Blackrock et trouver 10 Essences des éléments. Commencer vos recherches par les golems et par les créateurs de golems. Vivian Lagrave a aussi marmonné quelque chose à propos d'élémentaires.", tgo={{"Golem de lave de guerre", "Golem ravarage", "Assemblage porteguerre"}}},
    [7441] = {n="Pusillin et l'Ancien Azj'Tordin", d="Rendez-vous à Hache-tripes et trouvez le diablotin Pusillin. Persuadez-le par tous les moyens de vous rendre le Livre d'Incantations d'Azj'Tordin.\nSi vous parvenez à le récupérer, retournez voir Azj'Tordin au Pavillon de Lariss, en Feralas.", tgo={{"Pusillin"}}},
    [7461] = {n="Folie intérieure", d="Vous devez détruire les gardiens qui protègent les 5 Pylônes qui alimentent la Prison d'Immol'thar. Une fois que les Pylônes seront coupés, le champ de force qui entoure Immol'thar se dissipera.\nEntrez dans la Prison d'Immol'thar et éradiquez l'infâme démon qui se trouve en son cœur. Enfin, affrontez le prince Tortheldrin à l'Athenaeum.\nLorsque vous aurez terminé, retournez voir l'Ancienne des Shen'dralar dans la cour.", tgo={{"Immol'thar"}, {"Prince Tortheldrin"}}},
    [7463] = {n="Rafraîchissement arcanique", d="Rendez-vous dans le quartier de Crochebois de Hache-tripes et tuez Hydrogénos, l'élémentaire de l'eau. Retournez voir le Gardien du savoir Lydros à l'Athenaeum avec l'Essence d'Hydrogénos.", tgo={{"Hydrogénos"}}},
    [7481] = {n="Légendes elfiques", d="Fouillez Hache-tripes à la recherche de Telmius Cherche-Rêve. Lorsque vous aurez des informations, donnez-les au Sage Korolusk du Camp Mojache.", objs={"Squelette de Telmius Cherche-Rêve"}},
    [7489] = {n="Le filet de Lethtendris", d="Ramenez le Filet de Lethtendris à Talo Thornhoof au Camp Mojache, en Feralas.", tgo={{"Lethtendris"}}},
    [7492] = {n="Camp Mojache", d="Parlez à Talo Thornhoof au Camp Mojache, en Feralas."},
    [7498] = {n="Garona : une étude en discrétion et en trahison", d="Rendez ce livre à ses légitimes propriétaires."},
    [7499] = {n="Le codex de défense", d="Rendez ce livre à ses légitimes propriétaires."},
    [7500] = {n="Les recettes de l'arcaniste", d="Rendez ce livre à ses légitimes propriétaires."},
    [7501] = {n="La lumière et comment l'altérer", d="Rendez ce livre à ses légitimes propriétaires."},
    [7502] = {n="Contrôler les ombres", d="Rendez ce livre à ses légitimes propriétaires."},
    [7503] = {n="La plus grande race de chasseurs", d="Rendez ce livre à ses légitimes propriétaires."},
    [7504] = {n="Sainte Bolognaise : Ce que la lumière ne vous dit pas", d="Rendez ce livre à ses légitimes propriétaires."},
    [7505] = {n="Le Horion de givre et vous", d="Rendez ce livre à ses légitimes propriétaires."},
    [7506] = {n="Le Rêve d'Emeraude…", d="Rendez ce livre à ses légitimes propriétaires."},
    [7601] = {n="Les Commandements de Niby", d="Parlez à Démonet à Gangrebois."},
    [7602] = {n="La gangressence parfaite", d="Démonet vous a demandé de lui apporter trois Gangressences parfaites, venant de trois régions distinctes.\nLes satyres Legashi d'Azshara, les légionnaires de Jaedenar et les gangregardes sentinelles des Terres foudroyées détiennent la Gangressence parfaite de leur région.\nRécupérez les Gangressences parfaites et rapportez-les à Démonet, à Gangrebois.", tgo={{"Satyre Legashi", "Voleur Legashi", "Prêtre noir Legashi"}, {"Légionnaire de Jaedenar"}, {"Gangregarde sentinelle"}}},
    [7603] = {n="Le noyau infernal de Kroshius", d="Fouillez le Val Grêlé pour trouver les restes de Kroshius. Quand vous les aurez localisés, utilisez le Gangrefeu à proximité et attendez le retour de Kroshius. Quand l'Infernal se sera réveillé, tuez-le et prenez le Noyau infernal sur son cadavre.\nRapportez le Noyau infernal de Kroshius à Niby le Tout-Puissant, à Gangrebois.", tgo={{"Kroshius"}, {"Kroshius"}}},
    [7701] = {n="ON RECHERCHE : Surveillant Maltorius", d="Loin dans les profondeurs de la Fosse aux scories dans le Chaudron, dans la Gorge des Vents brûlants, vous trouverez le nain traître du clan Sombrefer répondant au nom de surveillant Maltorius.\nTuez le surveillant Maltorius et prenez sa tête. Apportez-la au capitaine de guet Lolo Longstriker dans la Gorge des Vents brûlants pour la récompense.", tgo={{"Surveillant Maltorius"}}},
    [7721] = {n="Du carburant pour la zappette", d="Récupérez 10 Noyaux élémentaires d'eau sur les Elémentaires marins et les Embruns le long de la Côte oubliée de Feralas, et rapportez-les à Zorbin Fandazzle, près du quai là-bas.", tgo={{"Elémentaire marin", "Embruns"}}},
    [7722] = {n="Le Flux embrasé", d="Quelque part dans la Fosse aux scories du Chaudron, vous trouverez les Plans secrets : Flux embrasé dérobés par le surveillant Maltorius. Trouvez ces plans et rapportez-les au Maître forgeron Burninate dans la gorge des Vents brûlants.", objs={"Plans secrets : Flux embrasé"}},
    [7723] = {n="Maudits gros doigts", d="Hansel Heavyhands veut que vous tuiez 20 Golems de guerre lourds.\nLes golems de guerre lourds errent dans les régions qui entourent le Chaudron dans la Gorge des Vents brûlants. Quand vous en aurez tué assez, revenez voir Hansel dans la Gorge des Vents brûlants.", tgo={{"Golem de guerre lourd"}}},
    [7724] = {n="Une menace incandescente", d="Hansel Lourdemains veut que vous tuiez 20 araignées de lave incendiaires dans la gorge des Vents brûlants. Vous pouvez trouver les araignées de lave incendiaires dans les plateaux et les mares de lave de la gorge des Vents brûlants.\nRevenez voir Hansel Lourdemains dans la gorge des Vents brûlants quand vous aurez tué assez de araignées de lave incendiaires.", tgo={{"Araignée de lave incendiaire"}}},
    [7727] = {n="Incendosaures ? N'importosaures, plutôt", d="Hansel Heavyhands veut que vous tuiez 20 Incendosaures.\nOn peut les trouver dans les bassins de lave de la Fosse aux scories, qui occupe une partie du Chaudron de la gorge des Vents brûlants.\nRetournez voir Hansel Heavyhands dans la gorge des Vents brûlants lorsque vous aurez tué suffisamment d'Incendosaures.", tgo={{"Incendosaure"}}},
    [7728] = {n="OBJETS VOLES : Tuyère et longue-vue", d="Trouvez la Tuyère de forge et la Longue-vue du guetteur et rapportez-les au sous-chef Scrange dans la gorge des Vents brûlants.\nLes seules informations dont vous disposez sur ces objets sont les suivantes : ils ont été dérobés par les nains Sombrefer, la Tuyère de forge est un outil utilisé par les forgerons et la Longue-vue du guetteur est un outil de surveillance inestimable pour les guetteurs.", tgo={{"Forge-vapeur Sombrefer"}, {"Guetteur Sombrefer"}}},
    [7729] = {n="OFFRE D'EMPLOI : Réduire la concurrence", d="Tuez 15 Sous-chefs Sombrefer et 15 Esclavagistes Sombrefer. Revenez voir le sous-chef Scrange dans la gorge des Vents brûlants quand vous aurez accompli cette tâche.", tgo={{"Sous-chef Sombrefer"}, {"Esclavagiste Sombrefer"}}},
    [7730] = {n="Infestation de Zukk'ash", d="Rapportez 20 Carapaces de Zukk'ash à Hadoken Swiftstrider au Camp Mojache en Feralas.", tgo={{"Aiguillonneuse Zukk'ash", "Guêpe Zukk'ash", "Ouvrière Zukk'ash"}}},
    [7731] = {n="Fouet-cuisant", d="Battez Fouet-cuisant dans le Gouffre grouillant et rapportez ses glandes à Hadoken Swiftstrider au Camp Mojache en Feralas.", tgo={{"Fouet-cuisant"}}},
    [7732] = {n="Le rapport sur les Zukk'ash", d="Apportez le rapport sur les Zukk'ash du Camp Mojache à Zilzibin Drumlore. Il réside à la Herse d'Orgrimmar"},
    [7734] = {n="Qualité améliorée", d="Fournir 10 Peaux de yéti Griffe Féroce à Jangdor Swiftstrider au Camp Mojache, en Feralas.", tgo={{"Yéti Griffe féroce", "Ancien Griffe féroce", "Griffe féroce enragé"}}},
    [7738] = {n="Une peau de yéti parfaite", d="Apporter la Peau de yéti parfaite à Jangdor Swiftstrider au Camp Mojache, en Feralas."},
    [7761] = {n="Les ordres de Blackhand", d="Cet orc est stupide. Il semble que vous deviez trouver un moyen d'obtenir la Marque de Drakkisath pour accéder à l'Orbe de commandement.\nD'après la lettre, la Marque est gardée par le général Drakkisath. Vous devriez peut-être enquêter."},
    [7815] = {n="Les Gueules d'acier, l'ami !", d="Katoom le pêcheur, du village des Revantusk des Hinterlands, veut que vous tuiez 15 tortues Gueules d'acier des mers. Retournez le voir lorsque vous aurez terminé.", tgo={{"Gueule d'acier des mers"}}},
    [7816] = {n="Gammerita, l'ami !", d="Katoom le pêcheur, du village des Revantusk dans les Hinterlands, veut que vous tuiez Gammerita et que vous récupériez le Meilleur appât de Katoom sur son cadavre.\nKatoom a mentionné que Gammerita rôdait sur la côte, avec d'autres tortues.", tgo={{"Gammerita"}}},
    [7828] = {n="Traquer les traqueurs", d="Le veneur Markhor du village des Revantusk, dans les Hinterlands, veut que vous tuiez 15 Traqueurs Crins-d'argent et 15 Hurleurs Crins-d'argent. Retournez le voir lorsque vous aurez terminé.\nD'après Makhor, les loups se cachent dans les régions sauvages des Hinterlands.", tgo={{"Traqueur Crins-d'argent"}, {"Hurleur Crins-d'argent"}}},
    [7829] = {n="Chasser les sauvages", d="Le veneur Markhor du village des Revantusk des Hinterlands veut que vous tuiez 20 Chouettards sauvages. Retournez le voir lorsque vous aurez terminé.\nMarkhor a mentionné que les Chouettards sauvages vivaient dans les régions sauvages des Hinterlands.", tgo={{"Chouettard sauvage"}}},
    [7830] = {n="Venger les victimes", d="Le veneur Markhor, du village des Revantusk des Hinterlands, veut que vous tuiez un Seigneur du ciel Bec-rasoir et que vous récupériez une Plume de Seigneur du ciel. Revenez le voir lorsque vous aurez terminé votre tâche.\nD'après Makhor, les Seigneurs du ciel Bec-rasoir sont des créatures rares qui vivent dans les régions sauvages des Hinterlands.", tgo={{"Seigneur du ciel Bec-rasoir"}}},
    [7839] = {n="Les voyous Vilebranch", d="Le forgeron Slagtree du village des Revantusk, dans les Hinterlands, vous demande de retrouver les Outils perdus de Slagtree. Retournez le voir lorsque vous les aurez.\nIl a laissé entendre qu'ils pourraient se trouver dans l'un des temples des Vilebranch, au nord-est des Hinterlands. Vous devriez aussi jeter un coup d'œil au rocher de l'Affût.", objs={"Outils perdus de Slagtree"}},
    [7840] = {n="Lard a perdu son déjeuner !", d="Lard, du village des Revantusk, dans les Hinterlands, veut que vous retrouviez le Repas de Lard. Retournez le voir lorsque ce sera fait.\nD'après Lard, il l'aurait laissé dans l'île, au nord. Prenez garde aux trolls Vilebranch !", tgo={{"Kidnapper Vilebranch"}}},
    [7845] = {n="L'Ancien Torntusk a été enlevé !", d="L'Aînée Torntusk du village des Raventusk des Hinterlands vous demande de libérer son compagnon, l'Ancien Torntusk, de Jintha'alor.\nVous savez qu'il est prisonnier au sommet de Jintha'alor, la capitale des Vilebranch, qui se trouve au sud des Hinterlands."},
    [7846] = {n="Récupérez la clé !", d="L'Ancien Torntusk, à Jintha'alor, veut que vous tuiez Hitah'ya la Gardienne afin de récupérer la Clé des menottes qui le retiennent. Lorsque vous aurez cette clé, retournez voir l'Ancien Torntusk.", tgo={{"Hitah'ya la Gardienne"}}},
    [7847] = {n="Retourner voir l'Aînée Torntusk", d="L'Ancien Torntusk, à Jintha'alor, veut que vous retourniez voir l'Aînée Torntusk du village des Revantusk et que vous lui appreniez qu'il est sauvé."},
    [7848] = {n="Harmonisation avec le Cœur du Magma", d="Aventurez-vous jusqu'au portail d'entrée du Cœur du Magma dans les profondeurs de Blackrock et récupérez un Fragment du Magma. Lorsque ce sera fait, retournez voir Lothos Riftwalker au mont Blackrock.", objs={"Fragment du Magma"}},
    [7849] = {n="L'angoisse de la séparation", d="Le veneur Markhor du village des Revantusk, dans les Hinterlands, veut que vous récupériez les restes de son frère jumeau. Trouvez le Crâne du veneur Malkhor et les Os du veneur Malkhor, et ramenez-les au veneur Markhor.\nMarkhor vous a dit que les restes de son frère avaient été abandonnés aux limons et aux loups des Vilebranch. Il a également mentionné l'existence d'une décharge remplie de limons à Jintha'alor, ainsi que celle d'un enclos à loups. Tous deux se trouvent près du sommet du temple.", objs={"Pile de crânes", "Pile d'ossements"}},
    [7850] = {n="Les calices ténébreux", d="L'Aînée Torntusk du village des Revantusk, dans les Hinterlands, veut que vous récupériez 10 Calices de sang corrompu à Jintha'alor. Retournez voir l'Aînée Torntusk lorsque vous aurez terminé.", objs={"Calice de sang corrompu"}},
    [7861] = {n="ON RECHERCHE : la vile prêtresse Maléficia et ses sbires", d="Vous avez reçu l'ordre de tuer la vile prêtresse Maléficia et 20 Gardes Ama'zasi Vilebranch. Lorsque vous aurez terminé, allez voir l'Aînée Torntusk au village des Revantusk, dans les Hinterlands.\nLa vile prêtresse Maléficia et la garde Aman'zasi ont leurs quartiers au sommet de Jintha'alor, dans les Hinterlands.", tgo={{"Vile prêtresse Maléficia"}, {"Garde Aman'zasi Vilebranch"}}},
    [7862] = {n="Offre d'emploi : capitaine de la garde du village des Revantusk", d="Vous avez été chargé de liquider 20 Berserkers Vilebranch, 20 Chasseurs des ombres Vilebranch, 20 Sanguinaires Vilebranch et 20 Mangeurs d'âmes Vilebranch.\nLorsque vous aurez terminé, allez parler à l'Aînée Torntusk, du village de Revantusk dans les Hinterlands.", tgo={{"Berserker Vilebranch"}, {"Chasseur des ombres Vilebranch"}, {"Sanguinaire Vilebranch"}, {"Mangeur d'âmes Vilebranch"}}, star={"Rune de capitaine de la garde", {"PALADIN", "WARRIOR", "ROGUE", "HUNTER"}}},
    [7877] = {n="Le trésor des Shen'dralar", d="Retournez à l'Athenaeum et trouvez le Trésor des Shen'dralar. Prenez votre récompense !"},
    [8151] = {n="Le charme du chasseur", d="Parlez à Ogtinc en Azshara."},
    [8153] = {n="La ramure de coursier", d="Rapporter deux Ramures de coursier parfaites à Ogtinc en Azshara. Ogtinc vit au sommet des collines au nord-est des ruines d'Eldarath.", tgo={{"Coursier Sabots-de-mousse"}}},
    [8231] = {n="Vandales des flots", d="Apporter 6 Ecailles de vandale des flots à Ogtinc en Azshara. Ogtinc demeure au sommet des falaises au nord-est des ruines d'Eldarath.", tgo={{"Jeune Vandale des flots", "Vandale des flots", "Grand Vandale des flots"}}},
    [8232] = {n="Le drake vert", d="Apporter la Dent de Morphaz à Ogtinc en Azshara. Ogtinc demeure au sommet des falaises au nord-est des ruines d'Eldarath.", tgo={{"Morphaz"}}, star={"Oeil de diablosaure", {"HUNTER"}}},
    [8233] = {n="Une requête toute simple", d="Parlez au seigneur Jorach Ravenholdt, au manoir de Ravenholdt."},
    [8234] = {n="Sac azur scellé", d="Récupérer le Sac azur scellé auprès du chaman Grumegueule en Azshara. Puis apportez le sac à l'archimage Xylem, également en Azshara.", tgo={{"Chaman Grumegueule", "Chaman noiregueule"}}},
    [8235] = {n="Les fragments codés", d="Apporter 10 Fragments codés à l'archimage Xylem à Azshara.", tgo={{"Limon forestier"}}},
    [8236] = {n="La clé d'azur", d="Rendre la Clé d'azur au seigneur Jorach Ravenholdt.", tgo={{"Morphaz"}}, star={"Drapé de chauve-souris du crépuscule", {"ROGUE"}}},
    [8250] = {n="L'art du mage", d="Trouvez Sanath Lim-Yo et obtenez d'être <mené/menée> à l'archimage Xylem."},
    [8251] = {n="La poussière magique", d="Procurer 10 doses de Poussière lumineuse à l'archimage Xylem.", tgo={{"Géomètre elfe de sang", "Vengeur elfe de sang", "Défenseur elfe de sang"}}},
    [8252] = {n="Le corail des sirènes", d="Récupérer 6 Coraux enchantés et les apporter à l'archimage Xylem.", tgo={{"Sirène Fouette-bile"}}},
    [8253] = {n="Détruire Morphaz", d="Récupérer le Fragment d'arcane sur Morphaz et le rendre à l'archimage Xylem.", tgo={{"Morphaz"}}, star={"Rubis de feu", {"MAGE"}}},
    [8254] = {n="Aider le Cercle", d="Chercher Ogtinc en Azshara."},
    [8255] = {n="Courser les coursiers", d="Récupérer 4 Glandes de coursier en bonne santé et les apporter à Ogtinc en Azshara. Ogtinc réside au sommet des falaises, au nord-est des ruines d'Eldarath.", tgo={{"Coursier Sabots-de-mousse"}}},
    [8256] = {n="L'ichor de non-mort", d="Récupérer une dose d'Ichor de non-mort pour le compte d'Ogtinc en Azshara. Ogtinc réside au sommet des falaises, au nord-est des ruines d'Eldarath.", tgo={{"Zombie Zanzil", "Chasseur Zanzil", "Ecorcheur Squelette"}}},
    [8257] = {n="Le sang de Morphaz", d="Tuez Morphaz dans le temple englouti d'Atal'Hakkar, et ramenez son sang à Greta Sabot-de-mousse à Gangrebois. L'entrée du temple englouti se trouve dans le marais des Chagrins.", tgo={{"Morphaz"}}, star={"Chapelet béni", {"PRIEST"}}},
    [8276] = {n="La reconquête de Silithus", d="Parler à l'imploratrice céleste Proudhorn au Fort cénarien, en Silithus."},
    [8277] = {n="Venin mortel du désert", d="Beetix Ficklespragg au Fort cénarien en Silithus veut que vous ramassiez 8 Dards de scorpide Cinglepierre et 8 Crocs de Glisseuse du sable. Retournez la voir quand vous aurez terminé.", tgo={{"Scorpide Cinglepierre"}, {"Glisseuse du sable"}}},
    [8278] = {n="Le dernier espoir de Noggle", d="Beetix Ficklespragg, du Fort cénarien en Silithus, veut que vous ramassiez 3 Dards de pinceurs Cinglepierre, 3 Dards d'écorcheur Cinglepierre et 3 Crocs de traqueuse des rochers.", tgo={{"Ecorcheur Cinglepierre"}, {"Pinceur Cinglepierre"}, {"Traqueuse des rochers"}}},
    [8280] = {n="Sécuriser les lignes d'approvisionnement", d="L'Imploratrice céleste Proudhorn au Fort cénarien en Silithus veut que vous tuiez 15 Frappeurs térébrants.", tgo={{"Frappeur térébrant"}}},
    [8281] = {n="Améliorer la sécurité", d="L'Imploratrice céleste Corne-fière au Fort cénarien en Silithus veut que vous tuiez 20 Écraseurs térébrants.", tgo={{"Ecraseur térébrant"}}},
    [8284] = {n="Le mystère du Crépuscule", d="La géologue Larksbane du Fort cénarien en Silithus veut que vous rassembliez 8 Fragments de Tablette du crépuscule.", objs={"Fragment de la Tablette du crépuscule"}},
    [8285] = {n="Le déserteur", d="Apportez la Tablette réparée à l'ermite Ortell en Silithus."},
    [8318] = {n="Communications secrètes", d="Apporter 10 Textes du crépuscule cryptés à Bor Wildmane au Fort cénarien.", tgo={{"Gardien du crépuscule Havunth", "Vengeur du crépuscule", "Géoseigneur du crépuscule"}}},
    [8365] = {n="Ohé, des chapeaux de pirate !", d="La Modiste arrogante veut que vous lui rapportiez 20 Chapeaux de pirate des Mers du sud au port Gentepression, en Tanaris.", tgo={{"Pirate des Mers du sud", "Flibustier des Mers du sud", "Portefaix des Mers du sud"}}},
    [8366] = {n="Le racket des Mers du sud", d="Le chef de la sécurité Bilgewhizzle du port Gentepression, en Tanaris, veut que vous tuiez 10 Pirates des Mers du sud, 10 Flibustiers des Mers du sud, 10 Portefaix des Mers du sud et 10 Bretteurs des Mers du sud.", tgo={{"Pirate des Mers du sud"}, {"Flibustier des Mers du sud"}, {"Portefaix des Mers du sud"}, {"Bretteur des Mers du sud"}}},
    [8411] = {n="Maîtriser les éléments", d="Apportez les éléments terre, air, feu et eau à Bath'rah la Vigie des vents.", tgo={{"Diable de poussière", "Exilé foudroyant", "Cyclonien"}, {"Elémentaire de roche", "Furie-de-pierre", "Elémentaire asservi"}, {"Ambassadeur Infernus", "Exilé ardent", "Esprit flamboyant insoumis"}, {"Elémentaire d'eau mineur", "Exilé grimpeur", "Gardien invoqué"}}},
    [8412] = {n="Le totem des esprits", d="Apportez les différents morceaux du Totem des esprits à Bath'rah la Vigie des Vents.", tgo={{"Vautour putride", "Rôdeuse putride", "Rôdeuse venimeuse des brumes"}, {"Vautour putride", "Ours noir malade", "Grizzly malade"}}},
    [8413] = {n="Vaudou !", d="Apporter les Plumes vaudou à Bath'rah la Vigie des vents.", tgo={{"Balafreur", "Zul'Lor", "Balafreur"}, {"Hukku", "Mijan", "Hukku"}, {"Zolo", "Loro", "Loro"}}, star={"Esprit de l'eau amoureux", {"SHAMAN"}}},
    [8417] = {n="Un esprit troublé", d="Parler au Héros déchu de la Horde à l'entrée des Terres foudroyées."},
    [8420] = {n="Chaud et piquant", d="Apportez un morceau de gangrétoffe à Démonet à Gangrebois.", tgo={{"Chasseur corrompu", "Gangregarde sentinelle", "Satyre Legashi"}}},
    [8421] = {n="L'anti-étoffe des héros", d="Apporter 10 morceaux de Bois pourri et 4 Essences de Vénéneuse à Démonet, en Gangrebois.", tgo={{"Arbrefer errant", "Arbrefer marteleur", "Protecteur flétri"}, {"Limon corrompu"}}},
    [8422] = {n="Les trolls d'un même plumage…", d="Apporter 6 Plumes vaudou des trolls du Temple englouti.", tgo={{"Balafreur", "Zul'Lor", "Balafreur"}, {"Hukku", "Mijan", "Hukku"}, {"Zolo", "Loro", "Loro"}}, star={"Moissonneuse d'âmes", {"WARLOCK"}}},
    [8423] = {n="Fraternité entre guerriers", d="Tuez 7 Sangliers infernaux dans les Terres Foudroyées, et revenez voir le Héros de la Horde tombé au combat.", tgo={{"Sanglier infernal"}}},
    [8424] = {n="La guerre contre les liges d'ombre", d="Tuez les Liges d'ombre dans les Terres Foudroyées et revenez voir le Héros de la Horde tombé au combat.", tgo={{"Adepte lige d'ombre"}, {"Sectateur lige d'ombre"}, {"Nervi lige d'ombre"}}},
    [8425] = {n="Plumes vaudou", d="Apportez les Plumes vaudou des trolls du Temple englouti au Héros de la Horde tombé au combat.", tgo={{"Balafreur", "Zul'Lor", "Balafreur"}, {"Hukku", "Mijan", "Hukku"}, {"Zolo", "Loro", "Loro"}}, star={"Flacon de diamant", {"WARRIOR"}}},
    [8460] = {n="Allié des Grumegueules", d="Grifleur veut que vous prouviez votre valeur en tuant 6 Guerriers Mort-bois, 6 Guides Mort-bois et 6 Jardiniers Mort-bois. Lorsque ce sera fait, retournez le voir dans le sud de Gangrebois, près du Sanctuaire d'émeraude.", tgo={{"Guerrier Mort-bois"}, {"Guide Mort-bois"}, {"Jardinier Mort-bois"}}},
    [8461] = {n="Les Mort-bois du nord", d="Nafien veut que vous tuiez 6 Protecteurs Mort-bois, 6 Vengeurs Mort-bois et 6 Chamans Mort-bois. Ensuite, retournez le voir dans le nord de Gangrebois, près de l'entrée du repaire des Grumegueules.", tgo={{"Protecteur Mort-bois"}, {"Vengeur Mort-bois"}, {"Chaman Mort-bois"}}},
    [8462] = {n="Parler à Nafien", d="Suivre la route principale de Gangrebois vers le nord et parler à Nafien le furbolg. Il monte la garde à côté de l'entrée du repaire des Grumegueules."},
    [8464] = {n="Les Tombe-hiver s'agitent", d="Salfa voudrait que vous tuiez 8 Chamans Tombe-hiver, 8 Protecteurs Tombe-hiver et 8 Ursas Tombe-hiver. Salfa se trouve juste à l'extérieur de l'entrée du repaire des Grumegueules, au Berceau-de-l'hiver.", tgo={{"Chaman Tombe-hiver"}, {"Protecteur Tombe-hiver"}, {"Ursa Tombe-hiver"}}},
    [8465] = {n="Parler à Salfa", d="Traverser le repaire des Grumegueules et sortir au Berceau-de-l'Hiver. Parlez à Salfa, qui monte la garde à l'extérieur du repaire des Grumegueules."},
    [8551] = {n="Le coffre du capitaine", d="Apporter le coffre au capitaine Hecklebury Smotts à Baie-du-Butin.", tgo={{"Gorlash"}}},
    [9051] = {n="Test de toxicité", d="Piquez un Diablosaure avec l'Aiguillon de diablosaure. Retournez voir Torwa Pathfinder au Cratère d'Un'goro lorsque vous aurez accompli cette tâche."},
    [9052] = {n="Le poison de Pétale-de-sang", d="Récupérez 8 Chapeaux de sang et 8 Dards de Gorishi, puis retournez voir Torwa Pathfinder au cratère d'Un'goro.", tgo={{"Guêpe Gorishi", "Dard Gorishi"}, {}}, objs={"Pousse de Pétale-de-sang"}},
    [9053] = {n="Un meilleur ingrédient", d="Récupérez une Liane putride sur le Gardien au fond du Temple englouti et revenez voir Torwa Pathfinder.", tgo={{"Atal'alarion"}}, star={"Fourrure grisonnante", {"DRUID"}}},
    [65593] = {n="Les cœurs des amoureux", d="Apportez les Cœurs d'Avelina Lilly et d'Isaac Pearson à Carendin Halgar dans le Temple des Damnés.", tgo={{"Avelina Lilly"}, {"Isaac Pearson"}}},
    [65597] = {n="Le lien", d="Utilisez les Cœurs des amoureux pour invoquer et soumettre un incube, puis rapportez les Cœurs des amoureux à Carendin Halgar, dans le Quartier de la magie de Fossoyeuse.", tgo={{"Incube invoqué"}}},
    [65601] = {n="Les affres de l'amour", d="Parlez à Magar, à Orgrimmar."},
    [65604] = {n="Le lien", d="Utilisez l'Écharpe flétrie pour invoquer et asservir un Incube, puis rapportez-la à Gan'rul Bloodeye, à Orgrimmar.", tgo={{"Incube invoqué"}}},
    [65610] = {n="Comme tu me manques", d="Explorez le Lac Tombeciel en Ashenvale et rendez compte de vos découvertes à Gan'rul Bloodeye, à Orgrimmar.", tgo={{"Bouge-pierre Sombretaillis", "Arracheur Sombretaillis", "Oracle Sombretaillis"}}},
    [78261] = {n="La Corne de Xelthos", d="Trouvez la Corne de Xelthos dans le donjon d'Ombrecroc. Puis rapportez-la au point de livraison de C, près du village de Bois-du-Bûcher. Vous devez accomplir cette tâche sans l'aide de personne."},
    [78270] = {n="Rossignols gobelins", d="Butin sur : Défricheur de la KapitalRisk, Opérateur de la KapitalRisk, Déboiseur de la KapitalRisk", tgo={{"Défricheur de la KapitalRisk", "Opérateur de la KapitalRisk", "Déboiseur de la KapitalRisk"}}},
    [78307] = {n="La Corne de Xelthos", d="Log"},
    [78676] = {n="L'Œil de Bhossca", d="Trouvez l'Œil de Bhossca dans le monastère Écarlate. Puis rapportez-la au point de livraison de C, près du village de Bois-du-Bûcher. Vous devez accomplir cette tâche sans l'aide de personne.", objs={"Reliquaire cadenassé"}},
    [78699] = {n="L'Œil de Bhossca", d="Log"},
    [78830] = {n="Terreur des cieux désertiques", d="Obtenez une plume trophée écarlate auprès de Gharrik dans les Terres ingrates, puis retournez voir Hemet Nesingwary dans la vallée de Strangleronce.", tgo={{"Gharrik"}}},
    [79229] = {n="Crime de grand chemin", d="Trouvez quelqu'un à Désolace qui connaît ce campement pillé."},
    [79235] = {n="En cavale", d="Trouvez un membre des maraudeurs de Désolace."},
    [79236] = {n="Une cerise, et tu me dis tout ?", d="Achetez un grog à la cerise à Tokal, dans la Baie-du-Butin, pour entendre la suite de son récit."},
    [79360] = {n="Soutien élémentaire", d="Éliminez Charlga Trancheflanc au kraal de Tranchebauge et recueillez des renseignements sur les plans des Hurans.", tgo={{"Charlga Trancheflanc"}}},
    [79361] = {n="Tempête, terre et feu", d="Récupérez 5 totems de feu tordus, 5 totems de terre tordus, 5 totems d'air tordus et 5 totems d'eau tordus pour Prate Œil-des-Nuages dans les Mille pointes.", tgo={{"Bondisseur Aileron boueux", "Murloc Aileron boueux", "Guerrier Aileron boueux"}, {"Rôdeboue Perdu", "Pêcheur Perdu", "Chasseur Perdu"}, {"Brise-crâne Cavepierre", "Briseur d'os Cavepierre", "Chaman Cavepierre"}, {"Querelleur maraudine", "Marteleur maraudine", "Chasse-vent maraudine"}}},
    [79364] = {n="Surveiller les cieux", d="Parlez à Prate Œil-des-Nuages aux Mille pointes."},
    [79365] = {n="Le vent sous les ailes", d="Retournez voir Rau Cours-les-falaises au poste de Librevent dans les Mille pointes."},
    [79366] = {n="Entendez mon appel", d="Utilisez les totems tordus pour mettre un terme au rituel des Hurans.", tgo={{"Tempête ravageuse"}}},
    [79442] = {n="Les armes de la tempête", d="Remettez l'œil de la tempête à Bath'rah la Vigie des vents, dans les montagnes d'Alterac.", star={"Rage du cyclone / Emprise de la foudre / Griffe de porte-marées"}},
    [80411] = {n="The Talisman of Kazdor", d="Utiliser/ramasser : Coffre de guerre envoûté", objs={"Coffre de guerre envoûté"}},
    [80526] = {n="Fool Me Twice", d="Speak to Fahrad when you're ready to hear his plan."},
    [82084] = {n="Un cours d'écriture", d="Localisez et collectez les éléments demandés par le bibliothécaire pour la création d'un grimoire.", tgo={{"Chouettard vicieux", "Chouettard primitif", "Chouettard sauvage"}, {"Aiguillonneuse Zukk'ash", "Guêpe Zukk'ash", "Ouvrière Zukk'ash"}, {"Zombie de Zul'Farrak"}}},
    [84398] = {n="A Study of the Light", d="Utiliser/ramasser : Livre", objs={"Livre"}},
    [86576] = {n="Les babioles des Rougefuries", d="Apportez 15 héliolites lumineuses à Mor'rogal.", tgo={{"Harpie Rougefurie", "Volplume Rougefurie", "Tueuse Rougefurie"}}},
    [90902] = {n="Redécouverte de la Lumière", d="Soignez 5 nécrogardes blessés avec votre technique Lumière sacrée.", tgo={{"Nécrogarde blessé"}}},
    [91208] = {n="L'acceptation", d="Trouvez la paladine effrayée au Glas.", tgo={{"Paladine effrayée"}}},
    [91209] = {n="Poursuivre votre entraînement", d="Suivez la route vers l'est à la sortie du Glas pour rejoindre le village de Brill. Présentez-vous à Shari Morpuits afin de poursuivre votre entraînement.", tgo={{"Shari Morpuits"}}},
    [91282] = {n="Un second foyer", d="Trouvez la forteresse de Bandarion et présentez-vous devant Breton Samuels."},
    [91285] = {n="Des Murlocs à nos portes", d="Tuez 8 attaquants aileron noir et 8 oracles aileron noir, puis retournez voir Breton Samuels une fois que c'est fait.", tgo={{"Attaquant aileron noir"}, {"Oracle aileron noir"}}},
    [91294] = {n="En patrouille", d="Parlez aux habitants la forteresse de Bandarion.", tgo={{"Hilda la Briseuse"}, {"Jorin Croge"}, {"Ander Solliden"}, {"Danitha Morr"}}},
    [91316] = {n="Procéder aux réparations", d="Récupérez 12 morceaux de bois solides à Ombreval, dans les clairières de Tirisfal.", objs={"Tas de bois"}},
    [91317] = {n="Les ternis", d="Tuez 8 manœuvres ternis et 6 zélotes ternis, puis récupérez la tête du commandant Rudolph Gelhardt dans les clairières de Tirisfal.", tgo={{"Rudolph Gelhardt"}}},
    [91497] = {n="Seals of the Sin'dorei", d="Butin sur : Lieutenant Suncrest, Magistrice Falcoiffe, Ranger Lydrea", tgo={{"Lieutenant Suncrest"}, {"Magistrice Falcoiffe"}, {"Ranger Lydrea"}}},
    [91500] = {n="An Explosive Gambit", d="Butin sur : Magus Rimtori", tgo={{"Magus Rimtori"}}},
    [91531] = {n="Revenge Exacted", d="Bring the Head of Magus Rimtori to Belgrom Rockmaul in Orgrimmar."},
    [91858] = {n="Incident diplomatique", d="Rendez-vous au Sépulcre dans la forêt des Pins-Argentés et parlez à Trevan Rol des voyageurs disparus du Cercle terrestre."},
    [91859] = {n="Un curieux duo", d="Parlez au nécrogarde Baldren à propos des mystérieux voyageurs du Cercle terrestre récemment passés au Sépulcre."},
    [91860] = {n="Un sort terrible", d="Fouillez l'île de Fenris à l'est pour apprendre le sort des voyageurs du Cercle terrestre.", objs={"Restes carbonisés"}},
    [91861] = {n="Dans le donjon de Fenris", d="Inspectez le donjon de Fenris, au nord, et tentez de localiser le membre disparu du groupe du Cercle terrestre."},
    [91862] = {n="Lumina Chantelevent", d="Récupérez la clé de l'île de Fenris sur des Gnolls poil-putride et utilisez-la pour libérer Lumina Chantelevent.", tgo={{"Sauvage Poil-Putride", "Furieux Poil-Putride", "Cogneur Poil-Putride"}}},
    [91920] = {n="Yeux sauvages", d="Récupérez 3 yeux de Murlocs et apportez-les à l'apothicaire Renferrel au Sépulcre.", tgo={{"Enfourneur", "Ecumeur Branchie-bleue", "Chasse-marée murloc"}}},
    [91921] = {n="Retour vers Quinn (encore une fois)", d="Apporter la potion de Quinn à Quinn Yorick au lopin d'Ivar, au nord du Sépulcre."},
    [92069] = {n="Les griffes qui pourfendent, les défenses qui étripent", d="Apportez les griffes du Grand ours et les défenses de l'Indompté à Ogtinc en Azshara."},
    [92343] = {n="Get to the Roots of It", d="Gather 10 Nordrassil Root Caps inside Blackmaw Hold for Nara Wildmane in Thunder Bluff."},
    [92346] = {n="Beneath Nordrassil", d="Speak to Nara Wildmane at Elder Rise in Thunder Bluff."},
    [92401] = {n="Une requête apeurée", d="Enquêtez sur la disparition d'Edward Tissecœur dans les ruines de Lordaeron."},
