    [96605] = {n="Les grands espaces sauvages", d="Asseyez-vous près du feu de camp basique de Kaga et attendez de recevoir l'amélioration Repos amplifié.", objs={"Basic Campfire"}},
    [96638] = {n="L'aventurier", d="Parlez à Raan Aile-sauvage près de Shen'dar."},
