    [96898] = {n="Les vestiges de la guerre", d="Rassemblez 12 fragments de cristal nécrotique dans les clairières de Tirisfal.", tgo={{"Néophyte sombre", "Massacreur sombre"}}},
    [96899] = {n="La forteresse de Bandarion", d="Retrouvez Leonid Barthalomew à la forteresse de Bandarion, dans les clairières de Tirisfal."},
    [96984] = {n="Cœur de la perturbation", d="Récupérez le granule arcanique pour le magus Wordeen Toisevide à Moulin-de-Tarren."},
    [96986] = {n="Le Chevalier de la tombe", d="Triomphez d'Atrexis le Chevalier de la tombe dans la cité de Dalaran pour Melisara à Moulin-de-Tarren."},
    [96987] = {n="Éducation opportuniste", d="Récupérez La fondation de Dalaran dans la cité de Dalaran pour Rexxie Pincentime près de l'entrée des égouts."},
    [96988] = {n="Source de pouvoir", d="Récupérez 6 noyaux de sentinelles fissurés dans la cité de Dalaran pour le docteur Martin Felben à Fossoyeuse.", objs={"Factionnaire fragmenté"}},
    [97022] = {n="Rendre compte à Danitha", d="Parlez à Danitha Morr à la forteresse de Bandarion."},
    [97049] = {n="Essence of Seeping Slimes", d="Gather 8 Seeping Slime Essence in the Shaper's Terrace."},
    [97196] = {n="L'Œil du Porte-froid", d="Récupérez l'œil du Porte-froid dans les souilles de Tranchebauge."},
    [97198] = {n="Magie noiregueule", d="Récupérez un totem rituel noiregueule au repaire des Noiregueules."},
    [97223] = {n="La matriarche griffesang", d="Apportez les œufs de la matriarche griffesang à Xar'Ti, au village de Sen'jin.", tgo={{"Matriarche griffesang"}}},
    [97225] = {n="Idoles de Loa oubliées", d="Récupérez 8 idoles de Loas oubliées sur les îles de l'Écho. Apportez-les au maître Gadrin, au village de Sen'jin.", objs={"Idole de Loa oubliée"}},
    [97243] = {n="L'appel du feu", d="Apportez la torche de la flamme dormante à Olariaan Vivebrûle au sanctuaire des Flammes, dans les plaines Aérelles."},
    [97244] = {n="L'appel du feu", d="Tuez le prêtre céleste Faladiel dans les plaines Aérelles, puis récupérez son cœur.", tgo={{"Prêtre céleste Faladiel"}}},
    [97245] = {n="L'appel du feu", d="Trouvez le repaire de Kuramaa dans les hautes-terres de Shen'dar et vainquez l'esprit au combat. Une fois victorieuse, rapportez le masque de Kuramaa à Olariaan Vivebrûle dans les plaines Aérelles.", tgo={{"Kuramaa"}}},
    [97250] = {n="Accusé à tort, corrigé à raison", d="Tuez des soldats de l'Alliance qui empiètent sur les Tarides, à la frontière du marécage d'Âprefange. Puis retournez voir le grunt Logmar, au camp Taurajo.", tgo={{"Soldat envahissant"}, {"Pilleur indigné"}}},
    [97253] = {n="Foire à la ferraille", d="Récupérez 5 poignées de pièces complexes au camp des pirates, au sud de Cabestan, puis retournez voir Wrenix le Misérable, à Cabestan.", objs={"Tas de pièces complexes"}},
    [97257] = {n="L'appel du feu", d="Attendez qu'Olariaan commence le rituel au brasero d'offrande, puis suivez ses instructions.\nVous devez remettre la flamme éternelle à Valanaar avant la fin du temps imparti.", tgo={{"Brasero d'offrande"}, {"Brasero de la flamme éternelle"}}, star={"Totem des flammes chargées", {"SHAMAN"}}},
    [97265] = {n="Furie contre les Fielfuries", d="Éliminez différents Satyres fielfuries à Sargeron, en Désolace, puis retournez auprès d'Aka'rai au village de Proie-de-l'Ombre.", tgo={{"Entourloupeur Fielfurie"}, {"Implorateur de l'enfer Fielfurie"}, {"Traqueur des ténèbres Fielfurie"}, {"Lige de la corruption Fielfurie"}, {"Voleur Fielfurie"}}},
    [97279] = {n="Armes égarées", d="Récupérez 6 armes d'entraînement abandonnées, puis retournez auprès de Kzan Trancheronce, dans l'Antre.", objs={"Arme d'entraînement abandonnée"}},
    [97281] = {n="Une tempête en approche", d="Apportez l'orbe de tempête émoussé à Rezlak, près du ravin Asséché."},
    [97282] = {n="Un potentiel houleux", d="Apportez 5 organes de lézard-tonnerre chargés à Rezlak, près du ravin Asséché.", tgo={{"Lézard-tonnerre", "Foudroyant", "Halikor"}}},
    [97287] = {n="Négociations avisées", d="Allez parler à l'image de l'archimage Modera, près de Dalaran."},
    [97288] = {n="Tourment interminable", d="Apportez la tête abominable au maître apothicaire Faranell à Fossoyeuse."},
    [97289] = {n="Tourment interminable", d="Apportez la tête du baron au corps d'Othmar, à Fossoyeuse."},
    [97290] = {n="Tourment interminable", d="Faites votre rapport au maître apothicaire Faranell, à Fossoyeuse."},
    [97291] = {n="Tourment interminable", d="Récupérez un calot toxique auprès de Grisette Fauve dans le quartier des Marchands, de la cloquette auprès de la maîtresse des herboristes et de l'essence d'agonie auprès du marchand de poison du quartier des Voleurs, pour le maître apothicaire Faranell à Fossoyeuse.", objs={"Cloquette"}},
    [97292] = {n="Tourment interminable", d="Injectez le sérum sifflant dans le dispositif au-dessus du corps d'Othmar, pour le maître apothicaire Faranell.", objs={"Othmar's Head"}},
    [97327] = {n="Blackmaw Pouches", d="Butin sur : Blackmaw Berserker, Blackmaw Thrall, Blackmaw Headhunter", tgo={{"Blackmaw Berserker", "Blackmaw Thrall", "Blackmaw Headhunter"}}},
    [97328] = {n="Tout ce qui vaut cher", d="Récupérez 8 cargaisons volées dans les ruines de Zul'Kunda, dans la vallée de Strangleronce, et apportez vos trouvailles à quelqu'un, à Baie-du-Butin."},
    [97329] = {n="Où est la clé ?", d="Obtenez la clé primitive auprès des Trolls des ruines de Zul'Kunda, dans la vallée de Strangleronce, et apportez-la à Zimmix Krachétincelle.", tgo={{"Eclaireur Bloodscalp", "Chasseur Bloodscalp", "Berserker Bloodscalp"}}},
    [97331] = {n="La grande évasion de Zimmix", d="Conduisez Zimmix Krachétincelle hors des ruines de Zul'Kunda, puis informez le maître des quais Lozouïe de votre sauvetage."},
    [97332] = {n="Une confiance deux fois mal placée", d="Apportez le paquet doublement renouvelé au maître des quais Sifflebruit, au port de Poudremèche, sur les rives Claires."},
    [97386] = {n="L'offensive de Grom'gol", d="Le commandant Aggro'gosh du campement Grom'gol vous demande de tuer des Ogres au tertre des Ogres mosh'Ogg.", tgo={{"Magicien Mosh'Ogg"}, {"Combattant Mosh'Ogg"}, {"Mutileur Mosh'Ogg"}, {"Chaman Mosh'Ogg"}}},
    [97453] = {n="Tonte des mauvaises herbes", d="Tuez 6 herbes carnivores au sud de Grom'gol, puis informez la mère de Gemmil.", tgo={{"Herbe carnivore"}}},
    [97485] = {n="Traditions des pitons", d="Achetez un paquet d'herbes à Nida l'herboriste, un fagot de brindilles de cèdre à Nata la fournisseuse de composants d'enchantements, des fibres tendineuses à Mahu le fournisseur de matériel de travail du cuir, ainsi que du silex et de l'amadou de cérémonie à Naal le fournisseur de matériel de cuisine.\nCombinez ces composants, puis répandez l'encens depuis la cime des Chasseurs.", objs={"Brûle-encens"}},
    [97530] = {n="Collecte chez les Cognedunes", d="Le chef de la sécurité Bilgewhizzle du port Gentepression en Tanaris veut que vous retrouviez un bracelet particulièrement brillant perdu près de la base des Ogres cognedunes.", tgo={{"Ogre Cognedune", "Massacreur Cognedune", "Ogre-mage Cognedune"}}},
    [97534] = {n="Dans le cambouis", d="Quinn vous demande de collecter 7 débris du désert et de les lui rapporter à Gadgetzan."},
    [97539] = {n="Sutures soyeuses", d="Rapportez 12 soies d'araignée chirurgicales au docteur Gregory Victor au Trépas-d'Orgrim, dans les hautes-terres Arathies.", tgo={{"Rampant des plaines", "Rampant des plaines géant"}}},
    [97558] = {n="Des peaux pour les Réprouvés", d="Apportez à Shelene Rhobart 8 membranes d'ailes de chauve-souris de la pénombre, 6 peaux de sombredogue et 3 peaux de Murloc aileron noir.", tgo={{"Grande chauve-souris du crépuscule", "Chauve-souris du crépuscule vampirique"}, {"Sombredogue décrépit", "Sombredogue maudit"}, {"Oracle mineur Aileron noir", "Marche-boue Aileron noir"}}},
    [97908] = {n="Introduction au camping : le dépeçage", d="Parlez à Thuwd, à Orgrimmar, pour apprendre à fabriquer un objet de camping propre à votre métier une fois que vous vous serez fait la main.", tgo={{"Thuwd"}}},
    [97936] = {n="Introduction au camping : le dépeçage", d="Parlez à Yonn Entaille-Profonde, à Sabot-de-Sang, pour apprendre à fabriquer un objet de camping propre à votre métier une fois que vous vous serez fait la main.", tgo={{"Yonn Deepcut"}}},
    [98024] = {n="Un voyage à la Croisée", d="Faites votre rapport à Thork à la Croisée, dans les Tarides."},
    [98069] = {n="Les fournitures de Librevent volées", d="Rapportez 8 fournitures de Librevent volées à Jandia, au poste de Librevent."},
    [98070] = {n="Interruption des hurlements", d="Tuez 5 harpies hurlantes, 5 Volplumes hurlantes et 5 imploratrices célestes hurlantes.", tgo={{"Harpie hurlante"}, {"Volplume hurlante"}, {"Imploratrice céleste hurlante"}}},
    [98093] = {n="Un champ à nettoyer", d="Sulhasa des Tarides du sud souhaite que vous éliminiez 7 lézards cuir-tempête et 7 traqueuses jappecroc dans les environs afin qu'elle puisse quitter son arbre en toute sécurité.", tgo={{"Traqueuse Jappecroc"}, {"Orageux"}}},
    [98094] = {n="Soutien aux éclaireurs", d="La grande exécutrice Darthalia vous charge de remettre des ordres mis à jour au nécrotraqueur Masoj, au sud de Moulin-de-Tarren, à l'extérieur de Dun Garok."},
    [98095] = {n="Positions stratégiques", d="Le nécrotraqueur Masoj vous demande de placer les trois flacons d'apothicaire sur les hauteurs des contreforts de Hautebrande, puis de revenir le voir."},
    [98298] = {n="La folie d'Arugal", d="Rapportez 6 morceaux worgens à Dalar Tisselaube au Sépulcre.", tgo={{"Hurle-sang Ragelune"}}},
    [98299] = {n="Endiguer la propagation", d="Tuez 5 réfugiés malades et 5 réfugiés hagards pour Dalar Tisselaube au Sépulcre.", tgo={{"Réfugié hagard"}, {"Réfugié malade"}}},
    [98340] = {n="L'esprit du Grand félin", d="Parlez à Dendrite Brasétoile au village de Havrenuit, à Reflet-de-Lune."},
    [98341] = {n="L'esprit du Grand félin du vent", d="Partez à la recherche de l'avatar de Saeyleenan dans la partie sud de Reflet-de-Lune et découvrez ce qu'il peut vous apprendre sur la nature du félin du vent."},
    [98342] = {n="L'esprit du Grand félin", d="Récupérez la relique du croc, la relique de la griffe et la relique de l'ombre furtive dans le refuge des saisons de Malfurion, puis rapportez-les à l'esprit du Grand félin.", objs={"Relique du Croc", "Relique de la Griffe", "Relique de l'ombre furtive"}},
    [98362] = {n="Vers les Pitons-du-Tonnerre", d="Retournez aux Pitons-du-Tonnerre et parlez à Turak Totem-runique, sur la cime des Anciens."},
    [98389] = {n="Une lumière dans les ténèbres", d="Libérez 6 victimes entoilées dans la grotte des tisse-nuit pour Aramis Mainmartel, au Glas."},
    [98404] = {n="L'esprit du Grand félin du vent", d="Récupérez la relique du croc, la relique de la griffe et la relique de l'ombre furtive dans le refuge des saisons de Malfurion, puis rapportez-les à l'avatar de Saeyleenan.", objs={"Relique du Croc", "Relique de la Griffe", "Relique de l'ombre furtive"}},
    [98405] = {n="L'esprit du Grand félin", d="Partez à la recherche de l'esprit du Grand félin dans la partie sud de Reflet-de-Lune, et découvrez ce qu'il peut vous apprendre sur la nature du félin."},
    [98424] = {n="Les notes de Vibrouage", d="Récupérez les pages du superviseur Vibrouage se trouvant encore à l'intérieur de la mine de la KapitalRisk, et apportez-les à Morin Traqueur-de-Nuage, près de Sabot-de-Sang.", objs={"Notice d'utilisation du déchiqueteur", "Bonnes pratiques des opérations menées dans les Tarides", "Un certain « Gerenzo » des Serres-Rocheuses"}},
    [98427] = {n="Fin des opérations", d="Apportez la clé de déboiseur à Morin Traqueur-de-Nuage, à l'extérieur de Sabot-de-Sang.", tgo={{"Déboiseur de la KapitalRisk"}}},
    [98430] = {n="Les longues-marches", d="Aidez Périth Sabot-tempête à fuir le rocher des Crins-pâles, et allez aux Pitons-du-Tonnerre pour informer Cairne Sabot-de-Sang que Périth est sain et sauf."},
    [98435] = {n="Rapport de Corne-Tonnerre", d="Apportez le rapport de Corne-Tonnerre à l'archidruide Hamuul Totem-Runique, aux Pitons-du-Tonnerre."},
    [98575] = {n="Tablette corrompue", d="Lisez la tablette corrompue, et parlez à Nartok, à l'intérieur de l'Antre, dans la vallée des Épreuves."},
    [98576] = {n="Parchemin glyphé", d="Lisez le parchemin glyphé, et parlez à Mai'ah, près de l'entrée de l'Antre de la vallée des Épreuves."},
    [98601] = {n="Un chemin tortueux", d="Lisez le parchemin consacré et parlez à Aramis Mainmartel, dans l'église du Glas."},
    [98738] = {n="Bénédiction de l'esprit du Grand félin du vent", d="Aller voir l'esprit du Grand ours, au nord-ouest de Reflet-de-Lune et apprendre ce qu'il peut vous enseigner sur la nature de l'ours. Quand cela est fait, retourner voir Dendrite Starblaze, à Havrenuit, dans Reflet-de-Lune."},
    [98739] = {n="Bénédiction de l'esprit du Grand félin", d="Parlez à Dendrite."},
    [98823] = {n="Écho terrestre", d="Apportez la relique des Titans à Muln Rageterre, sur le plateau de Guette-ciel au nord-ouest de Mulgore."},
    [99048] = {n="Une main en moins", d="Trouvez Heglan Ombredœil au nord du donjon de Tiragarde."},
    [99049] = {n="Une menace venue d'en bas", d="Trouvez des traces de ce qui a attaqué Heglan Ombredœil.", objs={"Dague abandonnée", "Débris étranges", "Fragment d'arme"}},
    [99051] = {n="Une menace venue d'en bas", d="Récupérez 9 ailerons épineux de Nagas.", tgo={{"Eclaireur fouette-bile", "Domestique fouette-bile"}}},
    [99052] = {n="Une menace venue d'en bas", d="Tuez le Géant des mers au large de la côte nord de Durotar, puis rapportez une preuve de votre victoire.", tgo={{"Aggor le Jeune"}}},
    [99079] = {n="Longue-marche Malah", d="Trouvez la longue-marche Malah Longuebrise à l'est de Sabot-de-Sang, près de la frontière de Mulgore."},
    [99080] = {n="Qu'ils disparaissent", d="Tuez 6 Centaures galak et 4 estafettes galak, puis apportez la tête d'Herak le Pilleur à Baine Sabot-de-Sang.", tgo={{"Centaure galak"}, {"Estafette galak"}, {"Herak le Pilleur"}}},
    [99081] = {n="De sombres nouvelles", d="Apportez le rapport de la longue-marche Malah au brave Course-Sauvage à Sabot-de-Sang."},
    [99082] = {n="Le grand chef", d="Sollicitez une audience auprès de Cairne Sabot-de-Sang aux Pitons-du-Tonnerre."},
    [99101] = {n="Un adversaire ancien", d="Apportez le rapport de la longue-marche Malah à Baine Sabot-de-Sang."},
    [99108] = {n="Combat d'entraînement", d="Battez 3 autres personnages-joueurs en duel ou guerriers novices pour Tang Sabot-de-Pierre.", tgo={{"Guerrier novice"}}},
    [99123] = {n="Perdue dans les ombres", d="Aidez Pal'juh à sortir de la combe des Kolkar, puis informez-en maître Vornal, au village de Sen'jin."},
    [99134] = {n="Discipline", d="Punissez 5 nécrogardes pour l'exécuteur Zygand."},
    [99141] = {n="Patience", d="Obtenez les rapports des nécrogardes Dillinger et Kristof et de Gordo pour l'exécuteur Zygand.", tgo={{"Garde noir Dillinger"}, {"Nécrogarde Kristof"}, {"Gordo"}}},
    [99142] = {n="Herbes sépulcrales", d="Récoltez 5 herbes sépulcrales et apportez-les à l'apprenti apothicaire Holland.", objs={"Herbe sépulcrale"}},
    [99156] = {n="Patrouille d'arrière-garde", d="Apportez le cœur de Fendécorche à la nécrogarde Linnea.", tgo={{"Fendécorche"}}},
    [99187] = {n="The Reliquary of Tyr", d="Travel to Blackmaw Hold in Kalimdor, and recover the Reliquary of Tyr.", star={"Sword of Mourning", {"PALADIN"}}},
    [99411] = {n="Kyle a disparu !", d="Ahab Sabot-de-Blé, à Sabot-de-Sang en Mulgore, veut que vous nourrissiez son précieux chiot, Kyle le Frénétique.\nDonnez de la Viande de trotteur tendre à Kyle puis retournez voir Ahab Sabot-de-Blé.", tgo={{"Kyle le frénétique"}}},
  },
